/**
 * scene-state.ts - 场景状态跟踪系统
 *
 * 本文件实现了帧间场景状态比对机制，用于检测哪些类型的场景元素发生了变化。
 * 这是 SuperSplat"按需渲染"策略的核心：只有当场景内容真正改变时才重新渲染。
 *
 * 工作原理：
 * 1. 每帧调用 pack() 让每个元素将自己的状态序列化为浮点数数组
 * 2. 使用 compare() 比对当前帧和上一帧的状态
 * 3. 检测 4 种变化类型：新增(added)、移除(removed)、顺序移动(moved)、值变化(changed)
 *
 * 设计亮点：
 * - 双缓冲机制：两个 SceneState 交替使用，避免每帧分配大量临时对象
 * - 高效的差异检测：基于索引和值比较，而非深度对象比对
 * - 类型级粒度：返回变化发生在哪些 ElementType 上，上层据此决定响应策略
 */

import { Element, ElementType, ElementTypeList } from './element';
import { Serializer } from './serializer';

/** 跨帧共享的通用元素集合（模块级复用，避免每次 compare 分配新 Set） */
const common = new Set<Element>();

/**
 * SceneState 类 - 单帧的场景状态快照。
 *
 * 为每种元素类型维护一个状态结构，包含：
 * - elements: Map<Element, number> - 元素到索引的映射（保留顺序信息）
 * - values: number[] - 连续存储的序列化值数组
 * - valueStart: number[] - 每个元素的值在 values 中的起始偏移
 * - valueCount: number[] - 每个元素的值的数量
 */
class SceneState {
    /** 按元素类型分组的全部状态数据 */
    states: any = {};
    /** 当前填充的值数组引用（在 pack 期间被重定向） */
    activeValues: any[];

    /**
     * 创建一个序列化器，每当元素调用 pack/packa 时，
     * 数据会被追加到 activeValues 数组中。
     */
    serializer = new Serializer((value: any) => {
        this.activeValues.push(value);
    });

    constructor() {
        // 为每种元素类型初始化空的状态结构
        for (let i = 0; i < ElementTypeList.length; ++i) {
            this.states[ElementTypeList[i]] = {
                elements: new Map<Element, number>(),
                valueStart: [],
                valueCount: [],
                values: []
            };
        }
    }

    /** 重置所有状态数据，准备记录新的一帧 */
    reset() {
        ElementTypeList.forEach((type) => {
            const state = this.states[type];
            state.elements.clear();
            state.valueStart.length = 0;
            state.valueCount.length = 0;
            state.values.length = 0;
        });
    }

    /**
     * 打包一个元素的状态。
     *
     * 调用元素的 serialize() 方法，该方法通过 Serializer 将状态值
     * 追加到 values 数组中。同时记录该元素在 values 中的偏移和长度。
     *
     * @param element - 要序列化的场景元素
     */
    pack(element: Element) {
        const state = this.states[element.type];
        const start = state.values.length;

        // 将 activeValues 重定向到当前元素类型的 values 数组，
        // 这样 Serializer 的 push 操作就会直接写入正确的位置
        this.activeValues = state.values;
        element.serialize(this.serializer);

        // 记录元素顺序和值的位置
        state.elements.set(element, state.elements.size);
        state.valueStart.push(start);
        state.valueCount.push(state.values.length - start);
    }

    /**
     * 与另一个 SceneState（上一帧）进行比对。
     *
     * 比对逻辑针对每种元素类型分别执行：
     * 1. added   - 元素在当期存在但上期不存在
     * 2. removed - 元素在上期存在但当期不存在
     * 3. moved   - 共同元素的顺序索引不同
     * 4. changed - 共同元素的序列化值发生了改变
     *
     * @param other - 上一帧的 SceneState 对象
     * @returns 包含四种变化类型的 ElementType 数组
     */
    compare(other: SceneState) {
        /**
         * 计算两个 Map 的键集合交集，结果存入 result。
         * 用于找出"在上下两帧中都存在"的元素。
         */
        function intersection<K, V>(result: Set<K>, a: Map<K, V>, b: Map<K, V>) {
            result.clear();
            for (const e of a.keys()) {
                if (b.has(e)) {
                    result.add(e);
                }
            }
        }

        /**
         * 检测 a 中是否有不在 b 中的元素（差集检测）。
         * 用于检测新增或移除。
         */
        function diff<K, V>(a: Map<K, V>, b: Set<K>) {
            for (const e of a.keys()) {
                if (!b.has(e)) {
                    return true;
                }
            }
        }

        /** 迭代器中的"任一满足"判断 */
        function some<T>(it: IterableIterator<T>, predicate: (t: T) => boolean) {
            for (const e of it) {
                if (predicate(e)) {
                    return true;
                }
            }
            return false;
        }

        const result = {
            added: new Array<ElementType>(),
            removed: new Array<ElementType>(),
            moved: new Array<ElementType>(),
            changed: new Array<ElementType>()
        };

        ElementTypeList.forEach((type) => {
            const prevState = other.states[type];
            const currState = this.states[type];

            const prev = prevState.elements;
            const curr = currState.elements;

            // 找出两帧共有的元素
            intersection(common, prev, curr);

            // 检测新增：当期有但上期没有
            if (diff(curr, common)) {
                result.added.push(type);
            }

            // 检测移除：上期有但当期没有
            if (diff(prev, common)) {
                result.removed.push(type);
            }

            // 检测移动：共有元素在两帧中的顺序索引不同
            if (
                some(common.values(), (e: Element) => {
                    return prev.get(e) !== curr.get(e);
                })
            ) {
                result.moved.push(type);
            }

            // 检测变化：共有元素的序列化值数组不同
            if (
                some(common.values(), (e: Element) => {
                    const prevIdx = prev.get(e);
                    const currIdx = curr.get(e);
                    const count = prevState.valueCount[prevIdx];

                    // 先比较值数量：数量不同则一定发生了变化
                    if (count !== currState.valueCount[currIdx]) {
                        return true;
                    }

                    // 数量相同时逐值比较
                    const prevStart = prevState.valueStart[prevIdx];
                    const currStart = currState.valueStart[currIdx];
                    const prevValues = prevState.values;
                    const currValues = currState.values;

                    for (let i = 0; i < count; ++i) {
                        if (prevValues[prevStart + i] !== currValues[currStart + i]) {
                            return true;
                        }
                    }

                    return false;
                })
            ) {
                result.changed.push(type);
            }
        });

        return result;
    }
}

export { SceneState };
