/**
 * recent-files.ts - 最近打开文件管理
 *
 * 本模块使用浏览器 IndexedDB 实现本地文件历史记录功能，
 * 记录用户最近通过 File System Access API 打开的 .splat 文件。
 *
 * 核心功能：
 * 1. add()   - 将文件添加到最近文件列表（或更新已存在的记录）
 * 2. get()   - 获取按时间倒序排列的最近文件列表
 * 3. clear() - 清空全部历史记录
 * 4. count() - 获取历史记录数量
 *
 * 为什么使用 IndexedDB：
 * - 需要存储 FileSystemFileHandle 对象（File System Access API 的句柄）
 * - FileSystemFileHandle 是结构化可克隆对象，可以存储在 IndexedDB 中
 * - 存储句柄后，用户下次可以重新获取文件访问权限，无需再次通过文件选择器
 *
 * 为什么按文件名作为键（而不是完整路径）：
 * - File System Access API 的限制：无法获取文件的完整目录路径
 * - 因此不同目录下的同名文件会被视为同一文件
 * - 这是 API 层面的固有限制，不是设计缺陷
 * - 参见 constructor 中的注释
 */

/** IndexedDB 数据库名称 */
const DB_NAME = 'supersplat';

/** 数据库版本号 - 修改对象存储结构时需要递增 */
const DB_VERSION = 1;

/** 对象存储（类似 SQL 中的表）名称 */
const STORE_NAME = 'recent-files';

/**
 * 最近文件记录的数据结构
 *
 * handle - FileSystemFileHandle: File System Access API 的文件句柄。
 *   这个对象不是普通的文件路径，而是浏览器授予的一个"文件访问令牌"，
 *   可以用于后续的读写操作（受权限生命周期限制）。
 *
 * name - string: 文件名（不含路径，因为 API 不暴露完整路径）
 *
 * date - number: 最后访问时间戳（毫秒），用于排序
 */
interface RecentFile {
    handle: FileSystemFileHandle;
    name: string;
    date: number;
}

/**
 * 将 IndexedDB 的请求对象包装为 Promise
 *
 * IndexedDB 的原生 API 使用事件回调机制（onsuccess / onerror），
 * 不支持 Promise。此辅助函数将其"Promise化"，方便配合 async/await 使用。
 *
 * 用法示例：
 *   const request = store.put(data);
 *   await wrap(request);  // 等待操作完成后继续
 *
 * @param IDBRequest - IndexedDB 的请求对象（IDBRequest<T>）
 * @returns Promise - 成功时 resolve(IDBRequest.result)，失败时 reject(IDBRequest.error)
 */
const wrap = (IDBRequest: IDBRequest): Promise<any> => {
    return new Promise((resolve, reject) => {
        IDBRequest.onsuccess = () => resolve(IDBRequest.result);
        IDBRequest.onerror = () => {
            console.error('IndexedDB error', IDBRequest.error);
            reject(IDBRequest.error);
        };
    });
};

/**
 * RecentFiles 类 - 管理用户最近打开的文件列表
 *
 * 封装了对 IndexedDB 的 CRUD 操作。在应用启动时自动初始化数据库连接。
 * 使用单例模式（模块底部创建实例并导出）。
 */
class RecentFiles {
    /** 数据库连接的 Promise - 初始化后可用 await 等待就绪 */
    db: Promise<IDBDatabase>;

    /**
     * 构造函数 - 打开或创建 IndexedDB 数据库
     *
     * 数据库初始化流程：
     * 1. 调用 indexedDB.open() 打开数据库
     * 2. 如果版本号变更或首次创建，触发 onupgradeneeded 事件
     * 3. 在 onupgradeneeded 中创建对象存储
     * 4. 将打开的结果（IDBDatabase）存入 this.db
     *
     * 关于 keyPath 的设计说明：
     * - 使用 'name'（文件名）作为主键
     * - 这意味着相同文件名的记录会覆盖旧记录（更新日期）
     * - 缺点：不同目录下的同名文件会被视为同一文件
     * - 原因：File System Access API 的限制，无法区分不同目录的同名文件
     */
    constructor() {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onupgradeneeded = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            // 如果对象存储不存在则创建（首次运行或版本升级时）
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                // 以文件名作为主键（keyPath），同名文件覆盖旧记录
                db.createObjectStore(STORE_NAME, { keyPath: 'name' });
            }
        };
        this.db = wrap(request);
    }

    /**
     * 添加或更新最近文件记录
     *
     * 如果该文件名已存在（keyPath 相同），则 put 会更新旧记录；
     * 如果不存在，则新增一条记录。这自然实现了"重复文件只保留最新记录"。
     *
     * @param handle - 通过 window.showOpenFilePicker() 获取的文件句柄
     */
    async add(handle: FileSystemFileHandle) {
        const db = await this.db;

        // 创建读写事务（readwrite），操作 'recent-files' 存储
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        // put() 写入记录：如果 keyPath(name) 已存在则更新，否则插入
        const request = store.put({
            handle: handle,
            name: handle.name,
            date: Date.now()
        });

        await wrap(request);
    }

    /**
     * 获取所有最近文件，按时间倒序排列（最新的在前）
     *
     * @returns 最近文件数组，最新打开的文件在数组最前面
     */
    async get(): Promise<RecentFile[]> {
        const db = await this.db;
        // 创建只读事务（readonly），性能更好，允许多个只读操作并发
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const result = await wrap(store.getAll()) as RecentFile[];

        // 按 date 降序排列（b.date - a.date > 0 意味着 b 更新，b 排在前面）
        result.sort((a, b) => b.date - a.date);
        return result;
    }

    /**
     * 清空所有最近文件记录
     */
    async clear() {
        const db = await this.db;
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        // clear() 删除对象存储中的所有记录
        await wrap(store.clear());
    }

    /**
     * 获取最近文件记录的数量
     *
     * @returns 存储在 IndexedDB 中的记录条数
     */
    async count(): Promise<number> {
        const db = await this.db;
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        // count() 返回存储中的记录总数，性能优于 getAll().length
        return wrap(store.count());
    }
}

/** 模块级单例实例 - 全局共享同一个 RecentFiles 实例 */
const recentFiles = new RecentFiles();

export { recentFiles };
