/**
 * splat-cache.ts - Splat 模型数据缓存
 *
 * 本模块使用浏览器 IndexedDB 缓存通过 URL 加载的 splat/ply 等模型原始数据，
 * 避免每次打开同一远程文件时重复下载。
 *
 * 核心功能：
 * 1. get()    - 按文件名查询缓存的二进制数据
 * 2. set()    - 将下载的原始数据写入缓存
 * 3. remove() - 删除指定缓存条目
 * 4. clear()  - 清空全部缓存
 * 5. stats()  - 获取缓存概况（条目数量、总大小）
 *
 * 缓存策略：
 * - 以文件名作为主键，同名文件会覆盖旧缓存
 * - 后续可扩展 hash/etag 等校验字段以支持版本对比
 */

const DB_NAME = 'supersplat-cache';

const DB_VERSION = 1;

const STORE_NAME = 'splat-data';

/**
 * 缓存条目的数据结构
 *
 * name - 文件名（主键）
 * url  - 原始下载地址（供调试/审计用）
 * data - 文件的原始二进制数据
 * size - 文件大小（字节）
 * date - 缓存时间戳（毫秒）
 */
interface CacheEntry {
    name: string;
    url: string;
    data: ArrayBuffer;
    size: number;
    date: number;
}

/**
 * 缓存概况
 */
interface CacheStats {
    count: number;
    totalSize: number;
}

/**
 * 将 IndexedDB 的请求对象包装为 Promise
 */
const wrap = (IDBRequest: IDBRequest): Promise<any> => {
    return new Promise((resolve, reject) => {
        IDBRequest.onsuccess = () => resolve(IDBRequest.result);
        IDBRequest.onerror = () => {
            console.error('SplatCache IndexedDB error', IDBRequest.error);
            reject(IDBRequest.error);
        };
    });
};

/**
 * SplatCache 类 - 管理模型原始数据的 IndexedDB 缓存
 */
class SplatCache {
    db: Promise<IDBDatabase>;

    constructor() {
        const request = indexedDB.open(DB_NAME, DB_VERSION);
        request.onupgradeneeded = (event) => {
            const db = (event.target as IDBOpenDBRequest).result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: 'name' });
            }
        };
        this.db = wrap(request);
    }

    /**
     * 根据文件名获取缓存的原始数据
     *
     * @param name - 文件名
     * @returns 缓存的 ArrayBuffer，未命中时返回 null
     */
    async get(name: string): Promise<ArrayBuffer | null> {
        const db = await this.db;
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);
        const result = await wrap(store.get(name)) as CacheEntry | undefined;

        if (result?.data) {
            console.log(`[SplatCache] 缓存命中: ${name} (${(result.size / 1024 / 1024).toFixed(1)} MB)`);
            return result.data;
        }
        console.log(`[SplatCache] 缓存未命中: ${name}`);
        return null;
    }

    /**
     * 将原始数据写入缓存
     *
     * @param name - 文件名（主键，同名会覆盖）
     * @param url - 原始下载地址
     * @param data - 文件的二进制数据
     */
    async set(name: string, url: string, data: ArrayBuffer): Promise<void> {
        const db = await this.db;
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        await wrap(store.put({
            name,
            url,
            data,
            size: data.byteLength,
            date: Date.now()
        }));

        console.log(`[SplatCache] 已缓存: ${name} (${(data.byteLength / 1024 / 1024).toFixed(1)} MB)`);
    }

    /**
     * 删除指定缓存条目
     *
     * @param name - 文件名
     */
    async remove(name: string): Promise<void> {
        const db = await this.db;
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        await wrap(store.delete(name));
        console.log(`[SplatCache] 已删除缓存: ${name}`);
    }

    /**
     * 清空全部缓存
     */
    async clear(): Promise<void> {
        const db = await this.db;
        const transaction = db.transaction([STORE_NAME], 'readwrite');
        const store = transaction.objectStore(STORE_NAME);
        await wrap(store.clear());
        console.log('[SplatCache] 已清空全部缓存');
    }

    /**
     * 获取缓存概况
     *
     * @returns 条目数量和总大小
     */
    async stats(): Promise<CacheStats> {
        const db = await this.db;
        const transaction = db.transaction([STORE_NAME], 'readonly');
        const store = transaction.objectStore(STORE_NAME);

        const items = await wrap(store.getAll()) as CacheEntry[];
        const totalSize = items.reduce((sum, item) => sum + item.size, 0);

        return {
            count: items.length,
            totalSize
        };
    }
}

/** 模块级单例实例 */
const splatCache = new SplatCache();

export { splatCache };
