/**
 * underlay.ts — 底层辅助叠加元素
 *
 * 在 SuperSplat 编辑器中实现一个屏幕空间的全屏叠加效果层（underlay）。
 * 当轮廓选择模式（outline selection）未启用时，在渲染管线的 gizmo 层
 * 开始前执行一次全屏纹理混合，为最终画面添加底层底色/暗化效果。
 *
 * 核心机制：
 * - 使用自定义着色器（blit-shader）创建一个全屏四边形（ShaderQuad）
 * - 通过 SimpleRenderPass 将相机的工作纹理（workTarget）作为源，
 *   以叠加混合模式绘制到屏幕上
 * - 监听相机的 preRenderLayer 事件，在 gizmo 层渲染前执行
 *
 * 与 scene 中的 overlay/underlay 系统配合使用，控制编辑器辅助元素的渲染层级。
 */
import {
    BLENDEQUATION_ADD,
    BLENDMODE_ONE,
    BLENDMODE_ZERO,
    BlendState,
    Layer
} from 'playcanvas';

import { Element, ElementType } from './element';
import { vertexShader, fragmentShader } from './shaders/blit-shader';
import { ShaderQuad, SimpleRenderPass } from './utils/simple-render-pass';

/**
 * 底层叠加元素类
 *
 * 渲染一个全屏的叠加效果。属于装饰/辅助性质（ElementType.other），
 * 不参与世界坐标变换，完全在屏幕空间工作。
 */
class Underlay extends Element {
    /** 全屏四边形，用于执行全屏着色器效果 */
    shaderQuad: ShaderQuad;
    /** 简单渲染通道，封装了着色器四边形的一次渲染流程 */
    renderPass: SimpleRenderPass;
    /** 是否启用 underlay 效果 */
    enabled = true;

    constructor() {
        // ElementType.other 表示这是一个其他/辅助类型的元素
        super(ElementType.other);
    }

    /**
     * 将 underlay 添加到渲染管线中
     *
     * 创建全屏四边形和渲染通道，注册相机事件监听器。
     * 当轮廓选择模式未启用时，在 gizmo 层渲染开始前执行叠加混合。
     */
    add() {
        const device = this.scene.app.graphicsDevice;

        // 创建全屏四边形着色器：顶点着色器生成覆盖整个屏幕的两个三角形，
        // 片元着色器对输入纹理进行采样和颜色处理
        this.shaderQuad = new ShaderQuad(device, vertexShader, fragmentShader, 'apply-underlay');
        // 创建渲染通道，配置混合状态：
        // RGB：1 * src + 1 * dst（加法混合，点亮画面）
        // Alpha：0 * src + 1 * dst（保持目标 alpha 不变）
        this.renderPass = new SimpleRenderPass(device, this.shaderQuad, {
            blendState: new BlendState(true,
                BLENDEQUATION_ADD, BLENDMODE_ONE, BLENDMODE_ONE,
                BLENDEQUATION_ADD, BLENDMODE_ZERO, BLENDMODE_ONE
            )
        });

        const { camera, events } = this.scene;

        // 监听相机每个渲染层开始前的事件
        camera.camera.on('preRenderLayer', (layer: Layer, transparent: boolean) => {
            // 只在轮廓选择模式未启用时才使用 underlay
            // events.invoke('view.outlineSelection') 查询当前是否处于轮廓选择模式
            if (!this.enabled || events.invoke('view.outlineSelection')) {
                return;
            }

            // 只在 gizmo 层的不透明通道阶段执行（跳过透明通道）
            // 这样 underlay 总是在 gizmo 元素渲染之前先叠加到画面
            if (layer !== this.scene.gizmoLayer || transparent) {
                return;
            }

            // 执行渲染通道：将相机当前的工作纹理（包含场景渲染结果）
            // 以叠加混合的方式绘制回屏幕
            this.renderPass.execute({
                srcTexture: camera.workTarget.colorBuffer
            });
        });
    }

    /**
     * 从渲染管线中移除 underlay
     *
     * 事件监听器在相机销毁时会自动清理，此处无需手动解绑。
     */
    remove() {
        // 相机销毁时 PlayCanvas 会自动移除该相机上的所有事件监听器
    }

    /**
     * 每帧渲染前调用
     *
     * underlay 不需要管理独立的相机（已改为通过事件驱动渲染），
     * 此方法保留为空以满足 Element 接口要求。
     */
    onPreRender() {
        // 无需管理独立相机，渲染已在 preRenderLayer 事件中触发
    }
}

export { Underlay };
