/**
 * 测量工具 (MeasureTool)
 *
 * 核心功能：
 * 1. 在 3D 高斯点云（Splat）上放置两个测量点，计算并显示两点之间的欧几里得距离
 * 2. 使用 SVG 在 2D 画布上绘制测量线和端点圆圈，提供视觉反馈
 * 3. 支持通过 TranslateGizmo 拖拽测量点改变位置（实时更新距离）
 * 4. 允许用户手动输入目标长度值，自动缩放整个 Splat 以匹配目标距离
 *   （即：调整整个 Splat 的 worldTransform 使两点间距离等于用户指定的值）
 *
 * 交互流程：
 * - 激活工具后在 Splat 上点击放置测量点（最多 2 个）
 * - 两个点都放置后显示测量线和距离值
 * - 拖拽数值滑块可调整目标距离（同时自动缩放 Splat）
 * - 点击现有测量点可以选中并拖拽移动（通过 Gizmo）
 * - 按 Delete 键删除选中的测量点
 *
 * 关键设计：
 * - 测量点存储在 splat.measurePoints 数组中（相对于 splat 的局部坐标）
 * - splat.measureSelection 记录当前选中的测量点索引
 * - 缩放 Splat 时以两点中点为锚点，保持中点位置不变
 */

import { Container, Label, NumericInput } from '@playcanvas/pcui';
import { Entity, Mat4, Quat, TranslateGizmo, Vec3 } from 'playcanvas';

import { EntityTransformOp } from '../edit-ops';
import { Events } from '../events';
import { Scene } from '../scene';
import { Splat } from '../splat';
import { Transform } from '../transform';

// ---- 预分配临时数学对象，避免运行时频繁分配导致 GC 压力 ----
// Mat4: 4x4 变换矩阵
const mat = new Mat4();
const mat1 = new Mat4();
const mat2 = new Mat4();
const mat3 = new Mat4();
// Vec3: 三维向量
const p = new Vec3();
const p0 = new Vec3();
const p1 = new Vec3();
// Quat: 四元数（表示旋转）
const r = new Quat();
// Vec3: 缩放向量
const s = new Vec3();

const t = new Transform();

/**
 * 占位变换处理器类
 *
 * 当测量工具激活时，将一个空的变换处理器推入 transformHandler 栈，
 * 阻止其他变换处理器（如 Gizmo 工具本身的处理器）响应变换操作。
 * 这样可以确保测量工具的 Gizmo 操作与其他工具的 Gizmo 操作互不影响。
 */
class MeasureTransformHandler {
    activate() {}
    deactivate() {}
}

class MeasureTool {
    /** 激活工具的回调函数 */
    activate: () => void;
    /** 停用工具的回调函数 */
    deactivate: () => void;

    /**
     * 构造函数：初始化测量工具的所有 UI、SVG 绘制元素和交互逻辑
     *
     * @param events - 全局事件总线
     * @param scene - 场景管理器
     * @param parent - HTML 父元素，SVG 图层和事件监听的载体
     * @param canvasContainer - PCUI Container，工具栏的父容器
     */
    constructor(events: Events, scene: Scene, parent: HTMLElement, canvasContainer: Container) {
        // ============================================================
        // 第一部分：创建 SVG 测量线图层
        // ============================================================

        /**
         * SVG 命名空间 URI。
         * 因为 SVG 元素需要通过 createElementNS 创建（而不是 createElement），
         * 所以需要显式指定命名空间。
         */
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.classList.add('tool-svg', 'hidden');
        svg.id = 'measure-tool-svg';
        parent.appendChild(svg);

        const ns = svg.namespaceURI;

        // 创建 <defs> 元素：存放可复用的 SVG 定义（模板线）
        const defs = document.createElementNS(ns, 'defs');

        /**
         * 创建 SVG 线段模板（定义在 defs 中）
         *
         * 实际渲染时由 lineBottom 和 lineTop 两个 <use> 元素引用此模板，
         * 这样可以减少重复定义，只需修改 line 的属性即可同时更新两处。
         * lineBottom 和 lineTop 分别用于测量线的下半部分和上半部分。
         */
        const line = document.createElementNS(ns, 'line') as SVGLineElement;
        line.id = 'measure-line';
        defs.appendChild(line);

        // 通过 <use> 引用模板，创建两条叠加的线段（可能是为了实现双色/阴影效果）
        const lineBottom = document.createElementNS(ns, 'use') as SVGUseElement;
        lineBottom.id = 'measure-line-bottom';
        lineBottom.setAttribute('href', '#measure-line');

        const lineTop = document.createElementNS(ns, 'use') as SVGUseElement;
        lineTop.id = 'measure-line-top';
        lineTop.setAttribute('href', '#measure-line');

        // 测量线端点：起点和终点的圆形标记
        const lineStart = document.createElementNS(ns, 'circle') as SVGCircleElement;
        lineStart.id = 'measure-line-start';

        const lineEnd = document.createElementNS(ns, 'circle') as SVGCircleElement;
        lineEnd.id = 'measure-line-end';

        // 按正确的 z-order 添加子元素（defs → 线段 → 端点）
        svg.appendChild(defs);
        svg.appendChild(lineBottom);
        svg.appendChild(lineTop);
        svg.appendChild(lineStart);
        svg.appendChild(lineEnd);

        // ============================================================
        // 第二部分：构建工具栏 UI
        // ============================================================

        // 距离标签文本（通过 i18n 本地化翻译）
        const lengthLabel = new Label({
            text: '长度'
        });

        // 距离输入框：显示测量值，也允许用户手动输入目标长度
        const lengthInput = new NumericInput({
            width: 90,
            placeholder: 'm',
            precision: 2,
            min: 0.0001,
            value: 0
        });

        /**
         * suppressUI 计数器：
         * 当代码主动修改 UI 值时，递增此计数器以阻止 'change' 事件触发缩放逻辑。
         * 防止程序化更新 UI 时产生递归调用。
         * 仅在计数器为 0 时允许 change 事件正常处理。
         */
        let suppressUI = 0;

        const selectToolbar = new Container({
            class: 'select-toolbar',
            hidden: true
        });

        // 阻止工具栏上的事件冒泡
        selectToolbar.dom.addEventListener('pointerdown', (e) => {
            e.stopPropagation();
        });

        selectToolbar.append(lengthLabel);
        selectToolbar.append(lengthInput);
        canvasContainer.append(selectToolbar);

        // ============================================================
        // 第三部分：Gizmo 和实体初始化
        // ============================================================

        // 平移 Gizmo，用于拖拽移动选中的测量点
        const gizmo = new TranslateGizmo(scene.camera.camera, scene.gizmoLayer);
        // 创建一个虚拟实体作为 Gizmo 的挂载目标（Gizmo 需要附着在 Entity 上）
        const entity = new Entity('measureGizmoPivot');
        // 空的变换处理器，用于阻止其他工具干扰
        const transformHandler = new MeasureTransformHandler();

        let active = false;
        let splat: Splat;

        // ============================================================
        // 第四部分：坐标转换辅助函数
        // ============================================================

        /**
         * 获取指定索引测量点的世界空间坐标
         *
         * @param index - 测量点数组中的索引
         * @param result - 用于接收结果的 Vec3 对象（复用，避免 GC）
         *
         * 测量点存储为 splat 局部坐标，此函数通过 splat 的世界变换矩阵
         * 将其转换到世界空间。
         */
        const getPoint = (index: number, result: Vec3) => {
            splat.worldTransform.transformPoint(splat.measurePoints[index], result);
        };

        /**
         * 获取指定测量点的屏幕空间 2D 坐标
         *
         * @param index - 测量点索引
         * @param result - 用于接收结果的 Vec3 对象
         *
         * 两步转换：
         * 1. 局部 → 世界（通过 getPoint）
         * 2. 世界 → 屏幕（通过 camera.worldToScreen）
         * 最后乘以画布的像素尺寸得到实际的屏幕像素坐标。
         */
        const getPoint2d = (index: number, result: Vec3) => {
            getPoint(index, result);
            scene.camera.worldToScreen(result, result);
            result.x *= canvasContainer.dom.clientWidth;
            result.y *= canvasContainer.dom.clientHeight;
        };

        /**
         * 更新所有视觉元素（Gizmo 位置、距离显示、测量线）
         *
         * 此函数在以下情况被调用：
         * - 测量点发生变化时（增删、拖拽）
         * - 工具激活/停用时
         * - Splat 选择变化时
         */
        const updateVisuals = () => {
            gizmo.detach();

            // 如果有选中的测量点，将 Gizmo 定位到该点
            if (splat && active && splat.measureSelection >= 0 && splat.measureSelection < splat.measurePoints.length) {
                getPoint(splat.measureSelection, p);
                t.set(p, Quat.IDENTITY, Vec3.ONE);
                events.invoke('pivot').place(t);
                entity.setLocalPosition(p);
                gizmo.attach(entity);
            }

            // 如果恰好有 2 个测量点，计算并显示距离
            if (splat && splat.measurePoints.length === 2) {
                getPoint(0, p0);
                getPoint(1, p1);
                const len = p0.distance(p1);

                // 使用 suppressUI 防止程序化更新触发缩放逻辑
                suppressUI++;
                lengthInput.value = len;
                lengthInput.enabled = true;
                suppressUI--;
            } else {
                // 不足 2 个点时禁用距离输入
                lengthInput.enabled = false;
            }
        };

        // ============================================================
        // 第五部分：Gizmo 事件处理
        // ============================================================

        // Gizmo 渲染更新 → 强制场景重绘
        gizmo.on('render:update', () => {
            scene.forceRender = true;
        });

        // Gizmo 拖拽开始 → 通知 pivot 系统开始变换
        gizmo.on('transform:start', () => {
            events.invoke('pivot').start();
        });

        // Gizmo 拖拽中 → 传递平移、旋转、缩放给 pivot 系统
        gizmo.on('transform:move', () => {
            events.invoke('pivot').moveTRS(entity.getLocalPosition(), entity.getLocalRotation(), entity.getLocalScale());
        });

        // Gizmo 拖拽结束 → 通知 pivot 系统结束变换
        gizmo.on('transform:end', () => {
            events.invoke('pivot').end();
        });

        /**
         * 监听选择变化事件
         * 当用户切换到不同的 Splat 时，自动停用测量工具。
         * 这样设计是为了确保测量工具的 Gizmo 和变换处理器能正确重置。
         */
        events.on('selection.changed', (selection: Splat) => {
            splat = selection;
            if (active) {
                events.fire('tool.deactivate');
            }
        });

        events.on('pivot.started', () => {
            // 预留：pivot 变换开始时的处理（当前为空，可根据需要扩展）
        });

        /**
         * 监听 pivot 移动事件
         * 当用户通过 Gizmo 拖拽测量点时，将 Gizmo 的新位置逆变换回局部坐标，
         * 更新 splat.measurePoints 中对应点的位置。
         *
         * 变换流程：
         * 1. 获取 Gizmo 的世界位置 (p)
         * 2. 计算 splat.worldTransform 的逆矩阵
         * 3. 用逆矩阵将世界坐标 p 变换回局部空间
         * 4. 存入 measurePoints 数组
         */
        events.on('pivot.moved', () => {
            if (active && splat && splat.measureSelection >= 0 && splat.measureSelection < splat.measurePoints.length) {
                const p = events.invoke('pivot').transform.position;
                mat.invert(splat.worldTransform);
                mat.transformPoint(p, splat.measurePoints[splat.measureSelection]);
            }
            scene.forceRender = true;
        });

        // pivot 变换结束时刷新视觉元素
        events.on('pivot.ended', () => {
            if (active && splat && splat.measureSelection >= 0 && splat.measureSelection < splat.measurePoints.length) {
                updateVisuals();
            }
        });

        // ============================================================
        // 第六部分：缩放 Splat 以匹配目标长度的逻辑
        // ============================================================

        // 保存起始状态的临时变量（供撤销/重做系统使用）
        const origTransform = new Mat4();
        const origP = new Vec3();
        const origR = new Quat();
        const origS = new Vec3();
        const mid = new Vec3();
        let startLen = 0;

        /**
         * 开始缩放操作前的准备：
         * 1. 保存当前的 worldTransform、位置、旋转、缩放（用于撤销/重做）
         * 2. 计算两个测量点在世界空间的中点位置
         * 3. 记录当前两点间距作为起始长度
         */
        const startScale = () => {
            if (!splat || splat.measurePoints.length !== 2) {
                return;
            }

            origTransform.copy(splat.worldTransform);
            origP.copy(splat.entity.getLocalPosition());
            origR.copy(splat.entity.getLocalRotation());
            origS.copy(splat.entity.getLocalScale());

            getPoint(0, p0);
            getPoint(1, p1);
            // mid = (p1 - p0) * 0.5 + p0 = 两点连线的中点
            mid.sub2(p1, p0);
            startLen = mid.length();
            mid.mulScalar(0.5).add(p0);
        };

        /**
         * 根据新的长度值缩放 Splat
         *
         * 核心算法：
         * 1. 计算缩放比例 scale = newLength / startLen
         * 2. 以两点中点为锚点构造变换矩阵：
         *    - T1: 平移到原点（-mid）
         *    - S:  应用缩放比例
         *    - T2: 平移回原来的位置（+mid）
         *    - 组合：T2 * S * T1 * origTransform
         * 3. 从组合矩阵中提取平移/旋转/缩放并设置到 entity
         *
         * @param newLength - 用户指定的新长度值
         */
        const applyLength = (newLength: number) => {
            if (!splat || splat.measurePoints.length !== 2 || newLength <= 0) {
                return;
            }

            const scale = newLength / startLen;

            p.copy(mid);

            // 构造以 p 为锚点的缩放变换矩阵
            // T(-p) → S(scale) → T(p)
            mat1.setTranslate(-p.x, -p.y, -p.z);     // 先平移至原点
            mat2.setScale(scale, scale, scale);       // 均匀缩放
            mat3.setTranslate(p.x, p.y, p.z);         // 再平移回去

            // 组合：mat = T(p) * S * T(-p) * origTransform
            mat.mul2(mat1, origTransform);
            mat.mul2(mat2, mat);
            mat.mul2(mat3, mat);

            // 从组合矩阵中提取平移/旋转/缩放分量
            mat.getTranslation(p);
            r.setFromMat4(mat);
            mat.getScale(s);

            // 应用新的变换到 entity
            splat.entity.setLocalPosition(p);
            splat.entity.setLocalRotation(r);
            splat.entity.setLocalScale(s);

            scene.forceRender = true;
        };

        /**
         * 结束缩放操作：创建撤销/重做操作记录
         *
         * EntityTransformOp 记录了变换前后的完整状态，
         * 通过事件总线提交到编辑历史系统，支持撤销（Ctrl+Z）和重做（Ctrl+Y）。
         */
        const endScale = () => {
            const top = new EntityTransformOp({
                splat: splat,
                oldt: new Transform(origP, origR, origS),
                newt: new Transform(splat.entity.getLocalPosition(), splat.entity.getLocalRotation(), splat.entity.getLocalScale())
            });

            events.fire('edit.add', top);
            updateVisuals();
        };

        let dragging = false;

        // ============================================================
        // 第七部分：长度输入框事件处理
        // ============================================================

        // slider:mousedown → 滑块拖拽开始，保存起始状态
        lengthInput.on('slider:mousedown', () => {
            startScale();
            dragging = true;
        });

        /**
         * change 事件处理：
         * - 如果正在拖拽滑块：实时应用长度变化（连续缩放 Splat）
         * - 如果直接输入数值（非拖拽）且 suppressUI 为 0：
         *   执行完整的三步骤：startScale → applyLength → endScale
         */
        lengthInput.on('change', (value) => {
            if (dragging) {
                applyLength(value);
            } else if (!suppressUI) {
                startScale();
                applyLength(value);
                endScale();
            }
        });

        // slider:mouseup → 滑块释放，完成缩放并创建撤销记录
        lengthInput.on('slider:mouseup', () => {
            endScale();
            dragging = false;
        });

        // ============================================================
        // 第八部分：删除测量点
        // ============================================================

        // 监听删除事件（通常由 Delete 键触发）
        events.on('select.delete', () => {
            if (active && splat && splat.measureSelection >= 0 && splat.measureSelection < splat.measurePoints.length) {
                // 从数组中移除选中的测量点
                splat.measurePoints.splice(splat.measureSelection, 1);
                // 选择索引递减，方便用户快速连续删除
                splat.measureSelection--;
                updateVisuals();
            }
        });

        // ============================================================
        // 第九部分：鼠标点击添加/选择测量点
        // ============================================================

        /**
         * 判断指针事件是否为主按钮
         * - 鼠标：button === 0 表示左键
         * - 触摸/触控笔：isPrimary 表示主触摸点
         */
        const isPrimary = (e: PointerEvent) => {
            return e.pointerType === 'mouse' ? e.button === 0 : e.isPrimary;
        };

        /** 标记是否发生了有效的点击（按下后未移动） */
        let clicked = false;

        // pointerdown → 标记为已点击（后续在 pointermove 中区分点击和拖拽）
        const pointerdown = (e: PointerEvent) => {
            if (!clicked && isPrimary(e)) {
                clicked = true;
            }
        };

        // pointermove → 如果鼠标移动了就取消点击标记（是拖拽而非点击）
        const pointermove = (e: PointerEvent) => {
            clicked = false;
        };

        /**
         * pointerup 处理器：在释放点击时处理两个逻辑
         *
         * 1. 检测是否点击了现有测量点（距离 < 8px）→ 选中该点
         * 2. 否则在射线命中位置创建新测量点（最多 2 个）
         *
         * 使用 async/await 是因为 camera.intersect() 可能是异步的（需要等待渲染结果）。
         */
        const pointerup = async (e: PointerEvent) => {
            if (splat && clicked && isPrimary(e)) {
                clicked = false;

                let closestIdx = -1;

                // 遍历所有测量点，检测点击位置是否在某个点的 8px 范围内
                for (let i = 0; i < splat.measurePoints.length; i++) {
                    getPoint2d(i, p);

                    if (Math.abs(p.x - e.offsetX) < 8 && Math.abs(p.y - e.offsetY) < 8) {
                        closestIdx = i;
                        break;
                    }
                }

                // 如果点击了现有测量点 → 选中它
                if (closestIdx >= 0) {
                    splat.measureSelection = closestIdx;
                    updateVisuals();
                    return;
                }

                // 如果尚未放置 2 个点 → 创建新测量点
                if (splat.measurePoints.length < 2) {
                    // 通过 camera.intersect 从点击位置投射射线，获取 3D 命中点
                    const result = await scene.camera.intersect(e.offsetX / canvasContainer.dom.clientWidth, e.offsetY / canvasContainer.dom.clientHeight);
                    if (result) {
                        // 将世界坐标转换到 splat 的局部空间
                        mat.invert(splat.worldTransform);
                        mat.transformPoint(result.position, p);
                        splat.measureSelection = splat.measurePoints.length;
                        splat.measurePoints.push(p.clone());
                        updateVisuals();
                    }
                }

                e.preventDefault();
                e.stopPropagation();
            }
        };

        // ============================================================
        // 第十部分：渲染后更新 SVG 测量线
        // ============================================================

        /**
         * postrender 事件：在每帧渲染结束后更新 SVG 测量线的位置
         *
         * 工作流程：
         * 1. 检查工具是否激活且有 Splat
         * 2. 将测量点从局部坐标转换到屏幕 2D 坐标
         * 3. 更新 SVG 线段的端点属性和圆圈元素的中心属性
         * 4. 根据测量点数量控制元素的可见性
         *
         * 注意：使用 screenToWorld 的反向过程将 3D 世界坐标映射到 2D 屏幕坐标，
         * 确保 SVG 覆盖层与 3D 场景中的测量点精确定位。
         */
        events.on('postrender', () => {
            if (active && splat) {
                // 至少需要 2 个点才显示测量线
                line.setAttribute('visibility', splat.measurePoints.length > 1 ? 'visible' : 'hidden');

                for (let i = 0; i < 2; i++) {
                    if (i < splat.measurePoints.length) {
                        getPoint2d(i, p);

                        const x = p.x.toString();
                        const y = p.y.toString();

                        // 设置线段的两个端点
                        if (i === 0) {
                            line.setAttribute('x1', x);
                            line.setAttribute('y1', y);
                            lineStart.setAttribute('cx', x);
                            lineStart.setAttribute('cy', y);
                            lineStart.setAttribute('visibility', 'visible');
                        } else if (i === 1) {
                            line.setAttribute('x2', x);
                            line.setAttribute('y2', y);
                            lineEnd.setAttribute('cx', x);
                            lineEnd.setAttribute('cy', y);
                            lineEnd.setAttribute('visibility', 'visible');
                        }
                    } else {
                        // 该索引没有测量点 → 隐藏对应的端点圆圈
                        if (i === 0) {
                            lineStart.setAttribute('visibility', 'hidden');
                        } else {
                            lineEnd.setAttribute('visibility', 'hidden');
                        }
                    }
                }
            } else {
                // 工具未激活或无 Splat → 隐藏所有 SVG 元素
                line.setAttribute('visibility', 'hidden');
                lineStart.setAttribute('visibility', 'hidden');
                lineEnd.setAttribute('visibility', 'hidden');
            }
        });

        // ============================================================
        // 第十一部分：Gizmo 尺寸自适应
        // ============================================================

        /**
         * 根据相机模式和画布尺寸动态调整 Gizmo 的大小。
         * 与 Box/Sphere 选择工具相同的逻辑。
         */
        const updateGizmoSize = () => {
            const { camera, canvas } = scene;
            if (camera.ortho) {
                gizmo.size = 1125 / canvas.clientHeight;
            } else {
                gizmo.size = 1200 / Math.max(canvas.clientWidth, canvas.clientHeight);
            }
        };
        updateGizmoSize();
        events.on('camera.resize', updateGizmoSize);
        events.on('camera.ortho', updateGizmoSize);

        // ============================================================
        // 第十二部分：激活/停用函数
        // ============================================================

        /**
         * 激活测量工具
         *
         * 执行的操作：
         * - 设置 active 标志
         * - 更新视觉元素（Gizmo 位置、距离显示）
         * - 注册指针事件监听器（用于点击添加/选择测量点）
         * - 显示工具栏
         * - 显示父元素（让 SVG 图层可见）
         * - 给父元素添加 'noevents' 类（确保 SVG 层不阻挡指针事件穿透到 3D 画布）
         * - 显示测量 SVG 图层
         * - 将空的变换处理器推入栈顶，阻止其他工具干扰
         */
        this.activate = () => {
            active = true;
            updateVisuals();
            canvasContainer.dom.addEventListener('pointerdown', pointerdown);
            canvasContainer.dom.addEventListener('pointermove', pointermove);
            // 第三个参数 true 表示在捕获阶段监听，优先处理
            canvasContainer.dom.addEventListener('pointerup', pointerup, true);
            selectToolbar.hidden = false;
            parent.style.display = 'block';
            parent.classList.add('noevents');
            svg.classList.remove('hidden');

            events.fire('transformHandler.push', transformHandler);
        };

        /**
         * 停用测量工具
         *
         * 与 activate 相反的操作序列：
         * - 清除 active 标志
         * - 清理视觉元素
         * - 移除事件监听器
         * - 隐藏 UI
         * - 从变换栈中弹出处理器
         */
        this.deactivate = () => {
            active = false;
            updateVisuals();
            canvasContainer.dom.removeEventListener('pointerdown', pointerdown);
            canvasContainer.dom.removeEventListener('pointermove', pointermove);
            canvasContainer.dom.removeEventListener('pointerup', pointerup);
            selectToolbar.hidden = true;
            parent.style.display = 'none';
            parent.classList.remove('noevents');
            svg.classList.add('hidden');

            events.fire('transformHandler.pop');
        };
    }
}

export { MeasureTool };
