/**
 * SplatsTransformHandler - 选定 splat 的变换处理器（GPU 调色板模式）
 *
 * 核心功能：
 * - 当用户使用移动/旋转/缩放工具操作选中的 splat 时，实时更新变换
 * - 使用"变换调色板"机制：为选中的 splat 分配新的调色板索引，
 *   在不修改原始顶点数据的情况下叠加额外的变换矩阵
 * - 变换结果存储在 GPU 端的变换调色板中，着色器在渲染时动态查表应用
 *
 * 与 EntityTransformHandler 的区别：
 * - EntityTransformHandler 变换的是整个 splat 实体（所有高斯点统一变换）
 * - SplatsTransformHandler 仅变换选中的高斯点（per-splat 变换，通过调色板）
 *
 * 数据流：
 * 1. pivot.started → start()：为选中的 splat 分配新调色板索引，记录起始状态
 * 2. pivot.moved → update()：实时更新调色板中的变换矩阵
 * 3. pivot.ended → end()：将变换写入编辑历史（undo/redo），触发 GPU 位置回读
 */
import { Mat4, Vec3 } from 'playcanvas';

import { PlacePivotOp, SplatsTransformOp, MultiOp } from './edit-ops';
import { Events } from './events';
import { Pivot } from './pivot';
import { Splat } from './splat';
import { State } from './splat-state';
import { Transform } from './transform';
import { TransformHandler } from './transform-handler';

// 临时变量复用，避免频繁创建
const mat = new Mat4();
const mat2 = new Mat4();
const transform = new Transform();

class SplatsTransformHandler implements TransformHandler {
    events: Events;
    splat: Splat;
    /** 操作开始时轴心点的变换（用于 undo/redo 恢复） */
    pivotStart = new Transform();
    /** 局部空间 → 轴心空间的变换矩阵 */
    localToPivot = new Mat4();
    /** 世界空间 → 局部空间的变换矩阵 */
    worldToLocal = new Mat4();

    /** 当前偏移变换（从轴心移动量计算得到） */
    transform = new Mat4();
    /**
     * 调色板索引映射：oldIdx → newIdx
     * selected splat 使用旧的调色板索引，操作期间分配新的索引
     */
    paletteMap = new Map<number, number>();

    constructor(events: Events) {
        this.events = events;

        // 轴心开始拖拽 → 初始化变换状态
        events.on('pivot.started', (pivot: Pivot) => {
            if (this.splat) {
                this.start();
            }
        });

        // 轴心移动 → 实时更新变换
        events.on('pivot.moved', (pivot: Pivot) => {
            if (this.splat) {
                this.update(pivot.transform);
            }
        });

        // 轴心拖拽结束 → 提交变换到编辑历史
        events.on('pivot.ended', (pivot: Pivot) => {
            if (this.splat) {
                this.end();
            }
        });

        // 选中 splat 变化 → 重新放置轴心
        events.on('selection.changed', (splat) => {
            if (this.splat && splat === this.splat) {
                this.placePivot();
            }
        });

        // 轴心原点模式切换（center/boundCenter）→ 重新放置轴心
        events.on('pivot.origin', (mode: 'center' | 'boundCenter') => {
            if (this.splat) {
                this.placePivot();
            }
        });

        // 用户点击选中 splat 上的点以拾取焦点 → 移动轴心到该点
        events.on('camera.focalPointPicked', (details: { splat: Splat, position: Vec3 }) => {
            if (this.splat && ['move', 'rotate', 'scale'].includes(this.events.invoke('tool.active'))) {
                const pivot = events.invoke('pivot') as Pivot;
                const oldt = pivot.transform.clone();
                const newt = new Transform(details.position, pivot.transform.rotation, pivot.transform.scale);
                const op = new PlacePivotOp({ pivot, oldt, newt });
                events.fire('edit.add', op);
            }
        });
    }

    /** 将轴心放置在当前选中 splat 的适当位置 */
    placePivot() {
        const origin = this.events.invoke('pivot.origin');
        // 根据模式（center 或 boundCenter）获取轴心变换
        // true 表示使用选中 splat 的包围盒（而非全部 splat）
        this.splat.getPivot(origin === 'center' ? 'center' : 'boundCenter', true, transform);
        this.events.invoke('pivot').place(transform);
    }

    /** 激活处理器：获取当前选中的 splat 并放置轴心 */
    activate() {
        this.splat = this.events.invoke('selection') as Splat;
        if (this.splat) {
            this.placePivot();
        }
    }

    deactivate() {
        this.splat = null;
    }

    /**
     * 开始变换操作
     *
     * 核心步骤：
     * 1. 计算轴心空间 ↔ 局部空间的变换关系
     * 2. 为每个选中的 splat 分配新的调色板索引（分离于原始数据）
     * 3. 复制原始变换到新索引（作为编辑前的初始状态）
     * 4. 降低选中高亮透明度 + 禁用轮廓/底衬渲染（减少视觉干扰）
     */
    start() {
        const pivot = this.events.invoke('pivot') as Pivot;
        const { transform } = pivot;
        const { splat } = this;
        const { transformPalette } = splat;

        // 构建轴心的世界变换矩阵
        mat.setTRS(transform.position, transform.rotation, transform.scale);

        // 计算 localToPivot = inv(pivot_matrix) * entity_local
        //   pivot_matrix: 轴心在世界/局部空间中的位置
        //   将局部空间坐标转换为相对于轴心的坐标
        this.localToPivot.invert(mat);
        this.localToPivot.mul2(this.localToPivot, splat.entity.getLocalTransform());

        // 计算 worldToLocal = inv(entity_local)
        //   将世界空间坐标转换为局部空间坐标
        this.worldToLocal.invert(splat.entity.getLocalTransform());

        this.pivotStart.copy(transform);

        // 为每个选中的 splat 分配新的调色板索引
        const state = splat.splatData.getProp('state') as Uint8Array;
        const indices = splat.transformTexture.lock() as Uint16Array;

        const { paletteMap } = this;
        paletteMap.clear();

        // 遍历所有 splat，为已选中的分配新索引
        for (let i = 0; i < state.length; ++i) {
            if (state[i] === State.selected) {
                const oldIdx = indices[i];
                let newIdx;
                if (!paletteMap.has(oldIdx)) {
                    // 第一次遇到此 oldIdx → 在调色板中分配新槽位
                    newIdx = transformPalette.alloc();
                    paletteMap.set(oldIdx, newIdx);
                } else {
                    // 此 oldIdx 已分配过 → 共享同一新槽位（相同旧变换的 splat 仍需同步变换）
                    newIdx = paletteMap.get(oldIdx);
                }

                indices[i] = newIdx;
            }
        }

        splat.transformTexture.unlock();

        // 初始化新分配的调色板槽位（复制原始变换）
        this.paletteMap.forEach((newIdx, oldIdx) => {
            transformPalette.getTransform(oldIdx, mat);
            // 将旧索引的变换复制到新索引
            transformPalette.setTransform(newIdx, mat);
        });

        // 操作期间降低视觉效果以突出拖拽状态
        splat.selectionAlpha = 0;
        splat.scene.outline.enabled = false;
        splat.scene.underlay.enabled = false;
    }

    /**
     * 更新变换（在拖拽过程中每帧调用）
     *
     * 计算链：
     * 1. 从新的轴心变换构建世界矩阵
     * 2. 变换到局部空间：local_mat = worldToLocal * pivot_matrix * localToPivot
     * 3. 将偏移矩阵应用到每个调色板条目的原始变换上
     *
     * @param transform - 轴心当前的位置/旋转/缩放
     */
    update(transform: Transform) {
        // 计算新的轴心 → 世界变换矩阵
        mat.setTRS(transform.position, transform.rotation, transform.scale);
        mat.mul2(mat, this.localToPivot);       // 结果：局部空间的"当前轴心"对应的变换
        mat.mul2(this.worldToLocal, mat);       // 结果：最终需要应用的偏移变换

        this.transform.copy(mat);

        // 将此偏移叠加到每个调色板条目上
        const { transformPalette } = this.splat;
        this.paletteMap.forEach((newIdx, oldIdx) => {
            // 读取旧变换 → 叠加偏移 → 写入新索引
            transformPalette.getTransform(oldIdx, mat2);
            mat2.mul2(mat, mat2);                // new = offset * old（先应用偏移，再应用原有变换）
            transformPalette.setTransform(newIdx, mat2);
        });

        // 更新包围盒（同步调用，不等待 GPU 回读）
        this.splat.updateLocalBounds();
    }

    /**
     * 结束变换操作
     *
     * 步骤：
     * 1. 创建 SplatsTransformOp（记录变换前后调色板索引映射，供 undo 使用）
     * 2. 创建 PlacePivotOp（记录轴心位置变更，供 undo 使用）
     * 3. 记录到编辑历史链
     * 4. 触发 GPU 位置回读（updatePositions），更新排序器中心点
     * 5. 恢复选择高亮和轮廓渲染
     */
    async end() {
        const { splat, transform, paletteMap } = this;

        // 创建 splat 变换操作记录（变换已在 update() 中应用到 GPU）
        const top = new SplatsTransformOp({
            splat,
            transform: transform.clone(),
            paletteMap: new Map(paletteMap)
        });

        // 创建轴心位置变更记录
        const pivot = this.events.invoke('pivot') as Pivot;
        const oldt = this.pivotStart.clone();
        const newt = pivot.transform.clone();
        const pop = new PlacePivotOp({ pivot, newt, oldt });

        // 先将操作记录到编辑历史链中（同步操作）
        // 这确保任何后续的 undo/redo 事件（如用户在 updatePositions 仍在进行时按 Ctrl+Z）
        // 一定位于此操作之后，因此 undo 将回退此变换操作而非之前的选择操作
        this.events.fire('edit.add', new MultiOp([top, pop]), true);

        // 将 GPU 回读加入同一个串行队列，确保后续 undo/redo 操作
        // 等待回读完成再修改 sorter 的 centers 缓冲区
        // TODO: 考虑将此移至 update() 中，使拖拽期间渲染排序能正确反映位置变化（但会更慢）
        await this.events.invoke('edit.queue', () => splat.updatePositions());

        // 恢复正常渲染
        splat.selectionAlpha = 1;
        splat.scene.outline.enabled = true;
        splat.scene.underlay.enabled = true;
    }
}

export { SplatsTransformHandler };
