/**
 * 序列化设置：控制在导出 PLY/SOG/SPLAT/HTML 时的行为
 */
type SerializeSettings = {
    /** 最大球谐带宽数（0=无SH，1=1阶/9系数，2=2阶/24系数，3=3阶/45系数） */
    maxSHBands?: number;
    /** 仅导出选中的高斯点（用于复制/粘贴功能） */
    selected?: boolean;
    /** 过滤掉透明度 <= minOpacity 的高斯点 */
    minOpacity?: number;
    /** 过滤掉包含 NaN 或 Infinity 等无效数据的高斯点 */
    removeInvalid?: boolean;

    // 以下选项仅在 serializePly 中支持（用于保存项目文件 .sup 场景）
    /** 保留 state 数据数组（通常导出 PLY 时应移除内部编辑器状态） */
    keepStateData?: boolean;
    /** 不应用世界变换来解析 splat 变换（保留原始数据中的变换） */
    keepWorldTransform?: boolean;
    /** 不应用颜色色调校正 */
    keepColorTint?: boolean;
};

