/** 生成者标识字符串（写入 PLY 文件头注释） */
const generatedByString = `Generated by SuperSplat ${version}`;

/**
 * Sigmoid 函数：将 PLY 文件中的不透明度值（从 -∞ 到 +∞ 的 logit）转换为 [0,1] 范围的真不透明度
 *
 * 3DGS 使用 logit(α) 存储不透明度（而非直接存储 α），以便在优化时进行无界参数估计
 * 公式: σ(v) = 1 / (1 + e^(-v))
 */
const sigmoid = (v: number) => 1 / (1 + Math.exp(-v));

/**
 * 高斯点过滤器：根据序列化设置筛选哪些高斯点应该被导出
 *
 * 过滤规则：
 * 1. 已删除的 splat 始终排除
 * 2. 根据 selected 选项，可选择仅导出选中的
 * 3. 根据 minOpacity 选项，过滤透明度太低的
 * 4. 根据 removeInvalid 选项，过滤包含 NaN/Infinity 的
 */
class GaussianFilter {
    /** 设置当前正在处理的 splat（初始化数据引用） */
    set: (splat: Splat) => void;
    /** 测试第 i 个高斯点是否应该导出 */
    test: (i: number) => boolean;

    constructor(serializeSettings: SerializeSettings) {
        let splat: Splat = null;
        let state: Uint8Array = null;
        let opacity: Float32Array = null;

        // 切换到新的 splat 时更新数据引用
        this.set = (s: Splat) => {
            splat = s;
            state = splat.splatData.getProp('state') as Uint8Array;
            opacity = splat.splatData.getProp('opacity') as Float32Array;
        };

        const onlySelected = serializeSettings.selected ?? false;
        const minOpacity = serializeSettings.minOpacity ?? 0;
        const removeInvalid = serializeSettings.removeInvalid ?? false;

        // 允许 Infinity 值的属性集合
        // 球谐系数在数值上可能为无穷大，这在数学上是有效的
        const infOk = new Set(['opacity']);
        // 允许负无穷的属性集合：scale 可以为极小值（非常扁的椭球体）
        const negInfOk = new Set(['scale_0', 'scale_1', 'scale_2']);

        this.test = (i: number) => {
            // 规则1：已删除的 splat 始终排除
            if ((state[i] & State.deleted) !== 0) {
                return false;
            }

            // 规则2：仅导出选中的（selected 模式）
            if (onlySelected && (state[i] !== State.selected)) {
                return false;
            }

            // 规则3：透明度过滤
            if (minOpacity > 0 && sigmoid(opacity[i]) < minOpacity) {
                return false;
            }

            // 规则4：无效数据过滤（NaN/Infinity）
            if (removeInvalid) {
                const { splatData } = splat;

                // 检查所有顶点属性值
                const element = splatData.getElement('vertex');
                for (let k = 0; k < element.properties.length; ++k) {
                    const prop = element.properties[k];
                    const { storage, name } = prop;
                    if (storage && !Number.isFinite(storage[i])) {
                        if (storage[i] === -Infinity && (infOk.has(name) || negInfOk.has(name))) continue;
                        if (storage[i] === Infinity && infOk.has(name)) continue;
                        return false;
                    }
                }
            }

            return true;
        };
    }
}

/**
 * 统计所有 splat 中可导出的高斯点总数
 * @param splats - splat 数组
 * @param filter - 过滤器实例
 * @returns 总可导出的高斯点数量
 */
const countGaussians = (splats: Splat[], filter: GaussianFilter) => {
    return splats.reduce((accum, splat) => {
        filter.set(splat);
        for (let i = 0; i < splat.splatData.numSplats; ++i) {
            accum += filter.test(i) ? 1 : 0;
        }
        return accum;
    }, 0);
};

/**
 * 获取 splat 数据中所有有实际数据的 vertex 属性名称集合
 * storage 不为空的属性才是有效属性
 */
const getVertexProperties = (splatData: GSplatData) => {
    return new Set<string>(
        splatData.getElement('vertex')
        .properties.filter((p: any) => p.storage)
        .map((p: any) => p.name)
    );
};

/**
 * 获取所有 splat 共有的属性名称
 *
 * 不同 PLY 文件可能包含不同属性集（例如有些有球谐系数，有些没有），
 * 合并导出时需要取交集（只导出共有属性）
 */
const getCommonPropNames = (splats: Splat[]) => {
    let result: Set<string>;

    for (let i = 0; i < splats.length; ++i) {
        const props = getVertexProperties(splats[i].splatData);
        result = i === 0 ? props : new Set([...result].filter(i => props.has(i)));
    }

    return [...result];
};

/**
 * 获取所有 splat 共有的属性（包含名称和类型）
 *
 * 只有所有 splat 中类型一致的属性才被包含（类型不一致说明不兼容，跳过）
 * 返回 [{name: string, type: string}, ...]
 */
const getCommonProps = (splats: Splat[]) => {
    const result = new Map<string, Set<string>>();  // name -> types 集合

    for (let i = 0; i < splats.length; ++i) {
        const properties = splats[i].splatData.getElement('vertex').properties.filter((p: any) => p.storage);
        properties.forEach((p: any) => {
            if (result.has(p.name)) {
                result.get(p.name).add(p.type);
            } else {
                result.set(p.name, new Set([p.type]));
            }
        });
    }

    // 只保留所有 splat 类型一致的属性
    return [...result].filter(([_, v]) => v.size === 1).map(([name, type]) => {
        return { name, type: type.values().next().value };
    });
};

/** 球谐函数系数属性名称列表（最多 45 个，对应 3 阶球谐 × 3 个颜色通道） */
const shNames = new Array(45).fill('').map((_, i) => `f_rest_${i}`);
/** 各阶球谐系数数量：0阶=0个, 1阶=3个, 2阶=8个(首系数), 3阶=15个(首系数) */
const shBandCoeffs = [0, 3, 8, 15];

/**
 * 根据已有的球谐系数属性名称集合确定球谐带宽数
 *
 * 判断逻辑：
 * - 如果有第 9 个系数 f_rest_8（索引 8），说明至少有 2 阶球谐
 * - 如果有第 24 个系数 f_rest_23（索引 23），说明至少有 3 阶球谐
 * - shNames 中第一个不存在的系数决定了带宽数
 *   索引 0~8 缺少 => 0 阶（无 SH）
 *   索引 9~23 缺少 => 1 阶
 *   索引 24 缺少 => 2 阶
 *   都有 => 3 阶
 *
 * @param data - splat 包含的属性名称集合
 * @returns 球谐带宽数（0/1/2/3）
 */
const calcSHBands = (data: Set<string>) => {
    return { '9': 1, '24': 2, '-1': 3 }[shNames.findIndex(v => !data.has(v))] ?? 0;
};

/** PLY 文件支持的数据类型 */
type DataType = 'char' | 'uchar' | 'short' | 'ushort' | 'int' | 'uint' | 'float' | 'double';

/**
 * 获取数据类型的字节大小
 * 用于计算每个高斯点在 PLY 二进制格式中的存储空间
 */
const DataTypeSize = (dataType: DataType) => {
    return {
        char: 1,
        uchar: 1,
        short: 2,
        ushort: 2,
        int: 4,
        uint: 4,
        float: 4,
        double: 8
    }[dataType];
};

// 临时向量/四元数，复用避免 GC
const v = new Vec3();
const q = new Quat();

/**
 * Splat 变换缓存：缓存每个 splat 的变换矩阵，避免重复计算
 *
 * 使用"调色板索引"来分组管理变换：
 * - 所有应用了相同变换的 splat 共享同一个调色板索引
 * - 缓存按调色板索引组织，而非按 splat 索引
 * - 提供 getMat/getRot/getScale/getSHRot 四个访问器
 */
class SplatTransformCache {
    /** 获取第 index 个 splat 的 4x4 变换矩阵 */
    getMat: (index: number) => Mat4;
    /** 获取第 index 个 splat 的旋转四元数 */
    getRot: (index: number) => Quat;
    /** 获取第 index 个 splat 的缩放向量 */
    getScale: (index: number) => Vec3;
    /** 获取第 index 个 splat 的球谐旋转矩阵 */
    getSHRot: (index: number) => SHRotation;

    /**
     * @param splat - 目标 splat
     * @param keepWorldTransform - true=保留原始数据变换（不应用编辑器世界变换）
     */
    constructor(splat: Splat, keepWorldTransform = false) {
        // 缓存 Map: key=调色板索引, value=变换数据对象
        const transforms = new Map<number, { transformIndex: number, mat: Mat4, rot: Quat, scale: Vec3, shRot: SHRotation }>();
        // 变换纹理数据（Uint16Array），存储每个 splat 的调色板索引
        const indices = splat.transformTexture.getSource() as unknown as Uint32Array;
        const tmpMat = new Mat4();
        const tmpMat3 = new Mat3();
        const tmpQuat = new Quat();

        // 获取或创建指定调色板索引的缓存条目
        const getTransform = (index: number) => {
            const transformIndex = indices?.[index] ?? 0;
            let result = transforms.get(transformIndex);
            if (!result) {
                result = { transformIndex, mat: null, rot: null, scale: null, shRot: null };
                transforms.set(transformIndex, result);
            }
            return result;
        };

        // 获取完整的 4x4 变换矩阵
        this.getMat = (index: number) => {
            const transform = getTransform(index);

            if (!transform.mat) {
                const mat = new Mat4();

                // 如果不需要保留原始变换，则撤销加载时应用的 180° Z 轴旋转
                // （PLY 导入时将点云绕 Z 轴旋转 180° 以适配渲染坐标系）
                if (!keepWorldTransform) {
                    mat.setFromEulerAngles(0, 0, -180);
                    mat.mul2(mat, splat.entity.getWorldTransform());
                }

                // 叠加调色板中存储的 per-splat 变换
                if (transform.transformIndex > 0) {
                    splat.transformPalette.getTransform(transform.transformIndex, tmpMat);
                    mat.mul2(mat, tmpMat);
                }

                transform.mat = mat;
            }

            return transform.mat;
        };

        // 从 4x4 矩阵提取旋转四元数
        this.getRot = (index: number) => {
            const transform = getTransform(index);

            if (!transform.rot) {
                transform.rot = new Quat().setFromMat4(this.getMat(index));
            }

            return transform.rot;
        };

        // 从 4x4 矩阵提取缩放向量
        this.getScale = (index: number) => {
            const transform = getTransform(index);

            if (!transform.scale) {
                const scale = new Vec3();
                this.getMat(index).getScale(scale);
                transform.scale = scale;
            }

            return transform.scale;
        };

        // 生成球谐旋转矩阵（SH Rotation）：当高斯点旋转时，球谐系数也需要相应旋转
        this.getSHRot = (index: number) => {
            const transform = getTransform(index);

            if (!transform.shRot) {
                tmpQuat.setFromMat4(this.getMat(index));
                tmpMat3.setFromQuat(tmpQuat);
                transform.shRot = new SHRotation(tmpMat3);
            }

            return transform.shRot;
        };
    }
}

/**
 * 单 Splat 数据提取器：读取指定高斯点的所有属性值，并应用变换
 *
 * 这是导出流程的核心类：
 * 1. 读取原始 splat 数据（位置、旋转、缩放、颜色、球谐系数等）
 * 2. 应用变换（变换调色板矩阵、世界变换）
 * 3. 应用颜色校正（色调、色温、饱和度等）
 * 4. 处理球谐系数的旋转变换
 */
class SingleSplat {
    /** 提取后的数据对象，key=属性名, value=数值 */
    data: any = {};

    /**
     * 读取函数：从指定 splat 中读取第 i 个高斯点的数据并处理
     * @param splats - splat 对象
     * @param i - 高斯点索引
     */
    read: (splats: Splat, i: number) => void;

    /**
     * @param members - 需要导出的属性名称列表（如 ['x','y','z','f_dc_0', ...]）
     * @param serializeSettings - 序列化设置
     */
    constructor(members: string[], serializeSettings: SerializeSettings) {
        // 初始化输出数据对象，所有值默认为 0
        const data: any = {};
        members.forEach((name) => {
            data[name] = 0;
        });

        // 判断是否需要处理位置、旋转、缩放、颜色、不透明度
        const hasPosition = ['x', 'y', 'z'].every(v => data.hasOwnProperty(v));
        const hasRotation = ['rot_0', 'rot_1', 'rot_2', 'rot_3'].every(v => data.hasOwnProperty(v));
        const hasScale = ['scale_0', 'scale_1', 'scale_2'].every(v => data.hasOwnProperty(v));
        const hasColor = ['f_dc_0', 'f_dc_1', 'f_dc_2'].every(v => data.hasOwnProperty(v));
        const hasOpacity = data.hasOwnProperty('opacity');

        // 目标球谐带宽数和系数数量
        const dstSHBands = calcSHBands(new Set(Object.keys(data)));
        const dstSHCoeffs = shBandCoeffs[dstSHBands];
        const tmpSHData = dstSHBands ? new Float32Array(dstSHCoeffs) : null;

        // 缓存条目类型
        type CacheEntry = {
            splat: Splat;
            transformCache: SplatTransformCache;
            /** 原始属性值数组（按名称索引） */
            srcProps: { [name: string]: Float32Array };
            /** 是否有颜色色调调整 */
            hasTint: boolean;
        };

        // 按 splat 缓存源属性引用，避免每次读取都重新查找
        const cacheMap = new Map<Splat, CacheEntry>();
        let cacheEntry: CacheEntry;

        const read = (splat: Splat, i: number) => {
            // 如果切换了 splat，查找或创建对应的缓存条目
            if (splat !== cacheEntry?.splat) {
                if (!cacheMap.has(splat)) {
                    const transformCache = new SplatTransformCache(splat, serializeSettings.keepWorldTransform);

                    // 获取源 splat 中存在的属性和球谐阶数
                    const srcPropNames = getVertexProperties(splat.splatData);
                    const srcSHBands = calcSHBands(srcPropNames);
                    const srcSHCoeffs = shBandCoeffs[srcSHBands];

                    // 缓存所有需要的属性数组引用
                    const srcProps: { [name: string]: Float32Array } = {};

                    members.forEach((name) => {
                        const shIndex = shNames.indexOf(name);
                        if (shIndex >= 0) {
                            // 球谐系数属性需要做索引映射
                            // 如果源和目标的 SH 阶数不同，需要从源中正确位置读取
                            const a = Math.floor(shIndex / dstSHCoeffs);
                            const b = shIndex % dstSHCoeffs;
                            srcProps[name] = (b < srcSHCoeffs) ? splat.splatData.getProp(shNames[a * srcSHCoeffs + b]) as Float32Array : null;
                        } else {
                            srcProps[name] = splat.splatData.getProp(name) as Float32Array;
                        }
                    });

                    // 判断是否需要应用颜色色调校正
                    const { tintClr, temperature, saturation, brightness, blackPoint, whitePoint } = splat;
                    const hasTint = (!tintClr.equals(Color.WHITE) || temperature !== 0 || saturation !== 1 || brightness !== 1 || blackPoint !== 0 || whitePoint !== 1);

                    cacheEntry = { splat, transformCache, srcProps, hasTint };

                    cacheMap.set(splat, cacheEntry);
                } else {
                    cacheEntry = cacheMap.get(splat);
                }
            }

            const { transformCache, srcProps, hasTint } = cacheEntry;

            // 步骤1：复制原始属性值到输出数据对象
            members.forEach((name) => {
                data[name] = srcProps[name]?.[i] ?? 0;
            });

            // 步骤2：应用变换调色板变换（位置、旋转、缩放）
            const mat = transformCache.getMat(i);

            if (hasPosition) {
                // 位置变换：应用 4x4 矩阵的平移、旋转、缩放
                v.set(data.x, data.y, data.z);
                mat.transformPoint(v, v);
                [data.x, data.y, data.z] = [v.x, v.y, v.z];
            }

            if (hasRotation) {
                // 旋转组合：将 splat 的旋转四元数与变换旋转相乘
                // rot_0 是 w 分量，rot_1/2/3 是 x/y/z 分量（PlayCanvas 使用这种顺序）
                const quat = transformCache.getRot(i);
                q.set(data.rot_1, data.rot_2, data.rot_3, data.rot_0).mul2(quat, q);
                [data.rot_1, data.rot_2, data.rot_3, data.rot_0] = [q.x, q.y, q.z, q.w];
            }

            if (hasScale) {
                // 缩放组合：scale 存储的是 log 尺度，需要先 exp 再乘变换缩放，最后再 log 回去
                const scale = transformCache.getScale(i);
                data.scale_0 = Math.log(Math.exp(data.scale_0) * scale.x);
                data.scale_1 = Math.log(Math.exp(data.scale_1) * scale.y);
                data.scale_2 = Math.log(Math.exp(data.scale_2) * scale.z);
            }

            // 步骤3：应用球谐旋转变换
            // 球谐函数的旋转在数学上更复杂，需要通过 Wigner D-矩阵进行
            if (dstSHBands > 0) {
                for (let c = 0; c < 3; ++c) {
                    for (let d = 0; d < dstSHCoeffs; ++d) {
                        tmpSHData[d] = data[shNames[c * dstSHCoeffs + d]];
                    }

                    transformCache.getSHRot(i).apply(tmpSHData);

                    for (let d = 0; d < dstSHCoeffs; ++d) {
                        data[shNames[c * dstSHCoeffs + d]] = tmpSHData[d];
                    }
                }
            }

            // 步骤4：应用颜色色调校正（如果 splat 有自定义颜色设置且序列化设置允许）
            if (!serializeSettings.keepColorTint && hasColor && hasTint) {
                const { tintClr, temperature, saturation, brightness, blackPoint, whitePoint } = splat;

                // 球谐函数的 DC 分量转换常数：C0 = 1 / sqrt(4π)
                const SH_C0 = 0.28209479177387814;
                // 球谐 DC 系数 <-> 线性 RGB 的转换
                const to = (value: number) => value * SH_C0 + 0.5;
                const from = (value: number) => (value - 0.5) / SH_C0;

                // 颜色变换核心函数：先应用偏移和缩放，再调整饱和度
                const applyTransform = (c: { r: number, g: number, b: number }, s: { r: number, g: number, b: number }, offset: number) => {
                    // 偏移 + 缩放
                    c.r = offset + c.r * s.r;
                    c.g = offset + c.g * s.g;
                    c.b = offset + c.b * s.b;

                    // 饱和度调整（先计算灰度值，然后在灰度和原色之间插值）
                    const grey = c.r * 0.299 + c.g * 0.587 + c.b * 0.114;
                    c.r = grey + (c.r - grey) * saturation;
                    c.g = grey + (c.g - grey) * saturation;
                    c.b = grey + (c.b - grey) * saturation;
                };

                const offset = -blackPoint + brightness;
                const scale = 1 / (whitePoint - blackPoint);

                const s = {
                    r: scale * tintClr.r * (1 + temperature),
                    g: scale * tintClr.g,
                    b: scale * tintClr.b * (1 - temperature)
                };

                // 转换 DC 分量到线性空间 -> 应用颜色校正 -> 转换回 SH 系数空间
                const c = {
                    r: to(data.f_dc_0),
                    g: to(data.f_dc_1),
                    b: to(data.f_dc_2)
                };

                applyTransform(c, s, offset);
                data.f_dc_0 = from(c.r);
                data.f_dc_1 = from(c.g);
                data.f_dc_2 = from(c.b);

                // 同样对球谐系数的更高阶分量应用变换（共享同样的缩放，无偏移）
                // 高阶级数影响光照方向性，不影响基础颜色
                if (dstSHBands > 0) {
                    for (let d = 0; d < dstSHCoeffs; ++d) {
                        c.r = data[shNames[d]];
                        c.g = data[shNames[d + dstSHCoeffs]];
                        c.b = data[shNames[d + dstSHCoeffs * 2]];

                        applyTransform(c, s, 0);
                        data[shNames[d]] = c.r;
                        data[shNames[d + dstSHCoeffs]] = c.g;
                        data[shNames[d + dstSHCoeffs * 2]] = c.b;
                    }
                }
            }

            // 步骤5：应用透明度调整
            const { transparency } = splat;
            if (!serializeSettings.keepColorTint && hasOpacity && transparency !== 1) {
                // invSig 是 sigmoid 的反函数：将透明度从 [0,1] 转换回 logit 空间
                // 边界值用 ±400 代替 ±∞ 避免数值溢出
                const invSig = (value: number) => ((value <= 0) ? -400 : ((value >= 1) ? 400 : -Math.log(1 / value - 1)));
                data.opacity = invSig(sigmoid(data.opacity) * transparency);
            }
        };

        this.data = data;
        this.read = read;
    }
}

/**
 * 导出标准 PLY 文件（未压缩格式）
 *
 * PLY 文件格式：
 * - 文本头：描述顶点属性和数量
 * - 二进制数据：紧跟在 "end_header" 后，小端存储
 *
 * @param splats - 要导出的 splat 数组
 * @param serializeSettings - 序列化设置
 * @param fs - 文件系统抽象（支持浏览器内存或磁盘）
 * @param filename - 输出文件名，默认 'output.ply'
 * @param progress - 进度回调
 */
const serializePly = async (splats: Splat[], serializeSettings: SerializeSettings, fs: FileSystem, filename = 'output.ply', progress?: ProgressFunc): Promise<void> => {
    const { maxSHBands, keepStateData } = serializeSettings;

    // 创建过滤器并统计可导出的高斯点总数
    const filter = new GaussianFilter(serializeSettings);
    const totalGaussians = countGaussians(splats, filter);
    if (totalGaussians === 0) {
        return;
    }

    // 内部属性（state 和 transform 是编辑器内部使用的，导出时应移除）
    const internalProps = keepStateData ? ['transform'] : ['state', 'transform'];

    const props = getCommonProps(splats)
    // 过滤掉内部属性
    .filter(p => !internalProps.includes(p.name))
    // 根据 maxSHBands 过滤高阶级球谐系数
    .filter((p) => {
        if (!p.name.startsWith('f_rest_')) {
            return true;
        }
        const i = parseInt(p.name.slice(7), 10);
        return i < [0, 9, 24, 45][maxSHBands ?? 3];
    });

    // 构建 PLY 文件头
    const headerText = [
        'ply',
        'format binary_little_endian 1.0',
        // FIXME: 暂不添加 comment 行，因为部分工具不支持任意 header
        // `comment ${generatedByString}`,
        `element vertex ${totalGaussians}`,
        props.map(p => `property ${p.type} ${p.name}`),
        'end_header',
        ''
    ].flat().join('\n');

    const singleSplat = new SingleSplat(props.map(p => p.name), serializeSettings);

    // 计算每个高斯点的二进制字节总数
    const gaussianSizeBytes = props.reduce((tot, p) => tot + DataTypeSize(p.type as DataType), 0);

    // 预分配一个环形缓冲区（1024 个高斯点的容量）
    const buf = new Uint8Array(1024 * gaussianSizeBytes);
    const dataView = new DataView(buf.buffer);
    let offset = 0;

    const header = new TextEncoder().encode(headerText);

    // 创建带进度的写入器
    const writer = await fs.createWriter(filename);
    const progressWriter = new ProgressWriter(writer, header.byteLength + totalGaussians * gaussianSizeBytes, progress);

    // 写入文本头
    await progressWriter.write(header);

    // 遍历所有 splat，逐个高斯点提取数据并写入
    for (let e = 0; e < splats.length; ++e) {
        const splat = splats[e];
        const { splatData } = splat;
        filter.set(splat);

        for (let i = 0; i < splatData.numSplats; ++i) {
            if (!filter.test(i)) continue;

            singleSplat.read(splat, i);

            // 将数据按属性顺序写入缓冲区
            for (let j = 0; j < props.length; ++j) {
                if (props[j].type === 'uchar') {
                    dataView.setUint8(offset, singleSplat.data[props[j].name]);
                    offset += 1;
                } else {
                    dataView.setFloat32(offset, singleSplat.data[props[j].name], true);
                    offset += 4;
                }
            }

            // 缓冲区满了，批量写入输出流
            if (offset === buf.byteLength) {
                await progressWriter.write(buf);
                offset = 0;
            }
        }
    }

    // 写入最后剩余的缓冲区数据
    if (offset > 0) {
        await progressWriter.write(new Uint8Array(buf.buffer, 0, offset));
    }

    progressWriter.close();
    await writer.close();
};

/** 压缩导出时的索引结构：记录每个高斯点来自哪个 splat 和该 splat 中的第几个 */
interface CompressedIndex {
    splatIndex: number;
    i: number;
    /** 全局唯一索引（在所有 splat 中的序号） */
    globalIndex: number;
}

/**
 * 压缩数据块：将 256 个高斯点处理为一个压缩块
 *
 * 每个块包含：
 * - 256 个 splat 的属性数据（Float32Array）
 * - 压缩后的位置（11+10+11 bit）
 * - 压缩后的旋转（2+10+10+10 bit 四元数）
 * - 压缩后的缩放（11+10+11 bit）
 * - 压缩后的颜色（8+8+8+8 bit RGBA）
 */
class Chunk {
    /** 参与压缩的基本属性列表 */
    static members = [
        'x', 'y', 'z',
        'scale_0', 'scale_1', 'scale_2',
        'f_dc_0', 'f_dc_1', 'f_dc_2', 'opacity',
        'rot_0', 'rot_1', 'rot_2', 'rot_3'
    ];

    size: number;
    data: any = {};

    // 压缩后的数据（使用 Uint32Array 存储多个 32 位打包值）
    position: Uint32Array;
    rotation: Uint32Array;
    scale: Uint32Array;
    color: Uint32Array;

    constructor(size = 256) {
        this.size = size;
        // 为每个属性分配 size 个元素的 Float32Array
        Chunk.members.forEach((m) => {
            this.data[m] = new Float32Array(size);
        });
        this.position = new Uint32Array(size);
        this.rotation = new Uint32Array(size);
        this.scale = new Uint32Array(size);
        this.color = new Uint32Array(size);
    }

    /**
     * 将单个 splat 的数据填充到块的指定位置
     * @param index - 块内索引（0~255）
     * @param splat - 已提取数据的 SingleSplat 实例
     */
    set(index: number, splat: SingleSplat) {
        Chunk.members.forEach((name) => {
            this.data[name][index] = splat.data[name];
        });
    }

    /**
     * 将块内数据压缩打包为量化格式
     *
     * 压缩策略：
     * - 位置/缩放：计算 min/max，归一化到 [0,1]，量化为 11+10+11 位
     * - 旋转：使用最小分量编码（2 bit 索引 + 3×10 bit 分量），类似 Basis 压缩
     * - 颜色：归一化后量化为 RGBA8
     *
     * @returns 各属性的 min/max 信息（需要随块一起写入文件，供解压使用）
     */
    pack() {
        // 计算数组的最小值和最大值
        const calcMinMax = (data: Float32Array) => {
            let min;
            let max;
            min = max = data[0];
            for (let i = 1; i < data.length; ++i) {
                const v = data[i];
                min = Math.min(min, v);
                max = Math.max(max, v);
            }
            return { min, max };
        };

        // 将值归一化到 [0, 1] 范围
        const normalize = (x: number, min: number, max: number) => {
            if (x <= min) return 0;
            if (x >= max) return 1;
            return (max - min < 0.00001) ? 0 : (x - min) / (max - min);
        };

        const data = this.data;

        const x = data.x;
        const y = data.y;
        const z = data.z;
        const scale_0 = data.scale_0;
        const scale_1 = data.scale_1;
        const scale_2 = data.scale_2;
        const rot_0 = data.rot_0;
        const rot_1 = data.rot_1;
        const rot_2 = data.rot_2;
        const rot_3 = data.rot_3;
        const f_dc_0 = data.f_dc_0;
        const f_dc_1 = data.f_dc_1;
        const f_dc_2 = data.f_dc_2;
        const opacity = data.opacity;

        // 计算各通道的 min/max
        const px = calcMinMax(x);
        const py = calcMinMax(y);
        const pz = calcMinMax(z);

        const sx = calcMinMax(scale_0);
        const sy = calcMinMax(scale_1);
        const sz = calcMinMax(scale_2);

        // 钳制 scale 范围在 [-20, 20] 之间
        // 因为某些异常 splat 的 scale 可能为 ±∞，导致压缩质量下降
        const clamp = (v: number, min: number, max: number) => Math.max(min, Math.min(max, v));
        sx.min = clamp(sx.min, -20, 20);
        sx.max = clamp(sx.max, -20, 20);
        sy.min = clamp(sy.min, -20, 20);
        sy.max = clamp(sy.max, -20, 20);
        sz.min = clamp(sz.min, -20, 20);
        sz.max = clamp(sz.max, -20, 20);

        // 将球谐 DC 系数转换为线性 RGB 颜色（方便压缩时计算 min/max）
        const SH_C0 = 0.28209479177387814;
        for (let i = 0; i < f_dc_0.length; ++i) {
            f_dc_0[i] = f_dc_0[i] * SH_C0 + 0.5;
            f_dc_1[i] = f_dc_1[i] * SH_C0 + 0.5;
            f_dc_2[i] = f_dc_2[i] * SH_C0 + 0.5;
        }

        const cr = calcMinMax(f_dc_0);
        const cg = calcMinMax(f_dc_1);
        const cb = calcMinMax(f_dc_2);

        /**
         * 将 [0,1] 范围的浮点数打包为指定位数的无符号整数
         * @param value - [0,1] 之间的值
         * @param bits - 目标位数
         */
        const packUnorm = (value: number, bits: number) => {
            const t = (1 << bits) - 1;
            return Math.max(0, Math.min(t, Math.floor(value * t + 0.5)));
        };

        /** 打包为 32 位：11+10+11 格式（常用于法线/位置压缩） */
        const pack111011 = (x: number, y: number, z: number) => {
            return packUnorm(x, 11) << 21 |
                   packUnorm(y, 10) << 11 |
                   packUnorm(z, 11);
        };

        /** 打包为 32 位：8+8+8+8 格式（RGBA 颜色） */
        const pack8888 = (x: number, y: number, z: number, w: number) => {
            return packUnorm(x, 8) << 24 |
                   packUnorm(y, 8) << 16 |
                   packUnorm(z, 8) << 8 |
                   packUnorm(w, 8);
        };

        /**
         * 四元数压缩：使用"最小分量编码"方法
         *
         * 由于单位四元数的 4 个分量满足 x²+y²+z²+w²=1，
         * 可以利用这一约束只存储 3 个分量，通过 2 bit 标记哪个分量最大（被省略），
         * 剩余 3 个分量各用 10 bit 量化，总计 32 位
         */
        const packRot = (x: number, y: number, z: number, w: number) => {
            q.set(x, y, z, w).normalize();
            const a = [q.x, q.y, q.z, q.w];
            // 找到绝对值最大的分量
            const largest = a.reduce((curr, v, i) => (Math.abs(v) > Math.abs(a[curr]) ? i : curr), 0);

            // 确保最大分量为正（整个四元数取反不改变旋转）
            if (a[largest] < 0) {
                a[0] = -a[0];
                a[1] = -a[1];
                a[2] = -a[2];
                a[3] = -a[3];
            }

            const norm = Math.sqrt(2) * 0.5;
            let result = largest;
            // 编码其余 3 个分量：映射 [-√2/2, √2/2] 到 [0, 1023]
            for (let i = 0; i < 4; ++i) {
                if (i !== largest) {
                    result = (result << 10) | packUnorm(a[i] * norm + 0.5, 10);
                }
            }

            return result;
        };

        // 对块内每个高斯点执行压缩
        for (let i = 0; i < this.size; ++i) {
            this.position[i] = pack111011(
                normalize(x[i], px.min, px.max),
                normalize(y[i], py.min, py.max),
                normalize(z[i], pz.min, pz.max)
            );

            this.rotation[i] = packRot(rot_0[i], rot_1[i], rot_2[i], rot_3[i]);

            this.scale[i] = pack111011(
                normalize(scale_0[i], sx.min, sx.max),
                normalize(scale_1[i], sy.min, sy.max),
                normalize(scale_2[i], sz.min, sz.max)
            );

            this.color[i] = pack8888(
                normalize(f_dc_0[i], cr.min, cr.max),
                normalize(f_dc_1[i], cg.min, cg.max),
                normalize(f_dc_2[i], cb.min, cb.max),
                1 / (1 + Math.exp(-opacity[i]))
            );
        }

        return { px, py, pz, sx, sy, sz, cr, cg, cb };
    }
}

/**
 * 使用 Morton 码（Z-order 曲线）对高斯点进行空间排序
 *
 * Morton 编码将 3D 空间坐标交错为 1D 顺序，使得空间上邻近的点在排序后也邻近，
 * 这能提高 GPU 渲染时的缓存局部性和排序效率
 *
 * @param splats - 所有 splat
 * @param indices - 压缩索引数组，排序结果直接修改此数组
 */
const sortSplats = (splats: Splat[], indices: CompressedIndex[]) => {
    // 参考：https://fgiesen.wordpress.com/2009/12/13/decoding-morton-codes/
    // Morton 编码器：将 3 个 10 位的坐标交错为 30 位整数
    const encodeMorton3 = (x: number, y: number, z: number) : number => {
        const Part1By2 = (x: number) => {
            x &= 0x000003ff;                    // 取低 10 位
            x = (x ^ (x << 16)) & 0xff0000ff;   // 交错位：将 bit 0..9 展开到 bit 0,3,6,9,12,15,18,21,24,27
            x = (x ^ (x <<  8)) & 0x0300f00f;
            x = (x ^ (x <<  4)) & 0x030c30c3;
            x = (x ^ (x <<  2)) & 0x09249249;
            return x;
        };

        return (Part1By2(z) << 2) + (Part1By2(y) << 1) + Part1By2(x);
    };

    // 计算所有 splat 覆盖的空间范围
    let minx: number;
    let miny: number;
    let minz: number;
    let maxx: number;
    let maxy: number;
    let maxz: number;

    for (let i = 0; i < splats.length; ++i) {
        const splat = splats[i];
        const splatData = splat.splatData;
        const state = splatData.getProp('state') as Uint8Array;
        // 使用排序器维护的 centers（世界空间坐标）
        const { centers } = splat.entity.gsplat.instance.sorter;

        for (let i = 0; i < splatData.numSplats; ++i) {
            if ((state[i] & State.deleted) === 0) {
                const x = centers[i * 3 + 0];
                const y = centers[i * 3 + 1];
                const z = centers[i * 3 + 2];

                if (minx === undefined) {
                    minx = maxx = x;
                    miny = maxy = y;
                    minz = maxz = z;
                } else {
                    if (x < minx) minx = x; else if (x > maxx) maxx = x;
                    if (y < miny) miny = y; else if (y > maxy) maxy = y;
                    if (z < minz) minz = z; else if (z > maxz) maxz = z;
                }
            }
        }
    }

    const xlen = maxx - minx;
    const ylen = maxy - miny;
    const zlen = maxz - minz;

    // 计算每个高斯点的 Morton 码
    const morton = new Uint32Array(indices.length);
    let idx = 0;
    for (let i = 0; i < splats.length; ++i) {
        const splat = splats[i];
        const splatData = splat.splatData;
        const state = splatData.getProp('state') as Uint8Array;
        const { centers } = splat.entity.gsplat.instance.sorter;

        for (let i = 0; i < splatData.numSplats; ++i) {
            if ((state[i] & State.deleted) === 0) {
                const x = centers[i * 3 + 0];
                const y = centers[i * 3 + 1];
                const z = centers[i * 3 + 2];

                // 将坐标归一化到 [0, 1023] 范围（10 位精度）
                const ix = Math.min(1023, Math.floor(1024 * (x - minx) / xlen));
                const iy = Math.min(1023, Math.floor(1024 * (y - miny) / ylen));
                const iz = Math.min(1023, Math.floor(1024 * (z - minz) / zlen));

                morton[idx++] = encodeMorton3(ix, iy, iz);
            }
        }
    }

    // 按 Morton 码排序
    indices.sort((a, b) => morton[a.globalIndex] - morton[b.globalIndex]);
};

/**
 * 导出压缩的 PLY 文件
 *
 * 压缩方案：
 * - 将高斯点分成 256 个一组的块
 * - 每个块记录属性的 min/max，然后在高斯点间归一化量化
 * - 位置/缩放：11+10+11 bit
 * - 旋转：2+10+10+10 bit 四元数编码
 * - 颜色：8+8+8+8 bit RGBA
 * - SH 系数：8 bit 量化
 * - 使用 Morton 排序优化空间局部性
 */
const serializePlyCompressed = async (splats: Splat[], options: SerializeSettings, fs: FileSystem, progress?: ProgressFunc): Promise<void> => {
    const { maxSHBands } = options;

    const filter = new GaussianFilter(options);

    // 构建全局高斯点索引列表
    const indices: CompressedIndex[] = [];
    for (let splatIndex = 0; splatIndex < splats.length; ++splatIndex) {
        const splatData = splats[splatIndex].splatData;
        filter.set(splats[splatIndex]);
        for (let i = 0; i < splatData.numSplats; ++i) {
            if (filter.test(i)) {
                indices.push({ splatIndex, i, globalIndex: indices.length });
            }
        }
    }

    if (indices.length === 0) {
        console.error('nothing to export');
        return;
    }

    const writer = await fs.createWriter('output.compressed.ply');

    const numSplats = indices.length;
    const numChunks = Math.ceil(numSplats / 256);

    // 块级属性：每个块存储 min/max
    const chunkProps = [
        'min_x', 'min_y', 'min_z',
        'max_x', 'max_y', 'max_z',
        'min_scale_x', 'min_scale_y', 'min_scale_z',
        'max_scale_x', 'max_scale_y', 'max_scale_z',
        'min_r', 'min_g', 'min_b',
        'max_r', 'max_g', 'max_b'
    ];

    // 顶点级属性：每个高斯点存储压缩后的打包值
    const vertexProps = [
        'packed_position',
        'packed_rotation',
        'packed_scale',
        'packed_color'
    ];

    // 计算输出球谐带宽数：取所有 splat 的最大带宽与用户选择的最小值
    const outputSHBands = (() => {
        const splatBands = splats.map(s => calcSHBands(getVertexProperties(s.splatData)));
        return Math.min(maxSHBands ?? 3, Math.max(...splatBands));
    })();
    const outputSHCoeffs = shBandCoeffs[outputSHBands];

    // 构建 SH 数据头（如果存在球谐系数）
    const shHeader = outputSHBands ? [
        `element sh ${numSplats}`,
        new Array(outputSHCoeffs * 3).fill('').map((_, i) => `property uchar f_rest_${i}`)
    ].flat() : [];

    // 构建 PLY 文件头
    const headerText = [
        'ply',
        'format binary_little_endian 1.0',
        `comment ${generatedByString}`,
        `element chunk ${numChunks}`,
        chunkProps.map(p => `property float ${p}`),
        `element vertex ${numSplats}`,
        vertexProps.map(p => `property uint ${p}`),
        shHeader,
        'end_header\n'
    ].flat().join('\n');

    // Morton 空间排序（提高渲染时的缓存命中率）
    sortSplats(splats, indices);

    // 创建数据提取器（仅提取压缩所需的属性）
    const singleSplat = new SingleSplat([
        'x', 'y', 'z',
        'scale_0', 'scale_1', 'scale_2',
        'f_dc_0', 'f_dc_1', 'f_dc_2', 'opacity',
        'rot_0', 'rot_1', 'rot_2', 'rot_3'
    ], options);

    /**
     * 将排序后的高斯点填充到块中
     * 最后一个块不足 256 个时，用最后一个有效高斯点的数据填充剩余槽位
     */
    const prepareChunk = (chunk: Chunk, i: number) => {
        const num = Math.min(numSplats, (i + 1) * 256) - i * 256;

        for (let j = 0; j < num; ++j) {
            const index = indices[i * 256 + j];
            singleSplat.read(splats[index.splatIndex], index.i);
            chunk.set(j, singleSplat);
        }

        // 填充剩余槽位（确保块始终有 256 个有效数据，简化量化逻辑）
        if (num < 256) {
            for (let j = num; j < 256; ++j) {
                chunk.set(j, singleSplat);
            }
        }
    };

    const header = new TextEncoder().encode(headerText);

    // 计算总字节数用于进度预估
    const totalBytes =
        header.byteLength +
        numChunks * chunkProps.length * 4 +
        numSplats * vertexProps.length * 4 +
        outputSHCoeffs * 3 * numSplats;

    const progressWriter = new ProgressWriter(writer, totalBytes, progress);

    // 写入文件头
    await progressWriter.write(header);

    const chunk = new Chunk();

    // 写入块数据（min/max 浮点值）
    const chunkData = new Float32Array(18);
    const chunkDataUint8 = new Uint8Array(chunkData.buffer);
    for (let i = 0; i < numChunks; ++i) {
        prepareChunk(chunk, i);

        const result = chunk.pack();

        // 按预定义顺序写入 min/max
        chunkData[0] = result.px.min;
        chunkData[1] = result.py.min;
        chunkData[2] = result.pz.min;
        chunkData[3] = result.px.max;
        chunkData[4] = result.py.max;
        chunkData[5] = result.pz.max;

        chunkData[6] = result.sx.min;
        chunkData[7] = result.sy.min;
        chunkData[8] = result.sz.min;
        chunkData[9] = result.sx.max;
        chunkData[10] = result.sy.max;
        chunkData[11] = result.sz.max;

        chunkData[12] = result.cr.min;
        chunkData[13] = result.cg.min;
        chunkData[14] = result.cb.min;
        chunkData[15] = result.cr.max;
        chunkData[16] = result.cg.max;
        chunkData[17] = result.cb.max;

        await progressWriter.write(chunkDataUint8);
    }

    // 写入顶点压缩数据（位置、旋转、缩放、颜色各 32 位）
    const vertexData = new Uint32Array(256 * 4);
    const vertexDataUint8 = new Uint8Array(vertexData.buffer);
    for (let i = 0; i < numChunks; ++i) {
        const num = Math.min(numSplats, (i + 1) * 256) - i * 256;

        // 需要重新 prepareChunk + pack，因为 vertex 数据在 pack 过程中生成
        prepareChunk(chunk, i);
        chunk.pack();

        for (let j = 0; j < num; ++j) {
            vertexData[j * 4 + 0] = chunk.position[j];
            vertexData[j * 4 + 1] = chunk.rotation[j];
            vertexData[j * 4 + 2] = chunk.scale[j];
            vertexData[j * 4 + 3] = chunk.color[j];
        }

        await progressWriter.write(num === 256 ? vertexDataUint8 : new Uint8Array(vertexData.buffer, 0, num * 4 * 4));
    }

    // 写入球谐系数（8 bit 量化）
    const singleSplatSH = new SingleSplat(shNames.slice(0, outputSHCoeffs * 3), options);

    const shData = new Uint8Array(outputSHCoeffs * 3 * 256);
    for (let i = 0; i < numChunks; ++i) {
        const num = Math.min(numSplats, (i + 1) * 256) - i * 256;

        for (let j = 0; j < num; ++j) {
            const index = indices[i * 256 + j];

            singleSplatSH.read(splats[index.splatIndex], index.i);

            // 量化：将 SH 系数值除以 8 后映射到 [0, 255]
            // 假设 SH 系数通常在 [-4, 4] 范围，/8 后 + 0.5 映射到 [0, 1]
            const offset = j * outputSHCoeffs * 3;
            for (let k = 0; k < outputSHCoeffs * 3; ++k) {
                const nvalue = singleSplatSH.data[shNames[k]] / 8 + 0.5;
                shData[offset + k] = Math.max(0, Math.min(255, Math.trunc(nvalue * 256)));
            }
        }

        await progressWriter.write(num === 256 ? shData : new Uint8Array(shData.buffer, 0, num * outputSHCoeffs * 3));
    }

    progressWriter.close();
    await writer.close();
};

/**
 * 导出 .splat 格式（antimatter15 提出的简化格式）
 *
 * .splat 格式：每个高斯点占用固定 32 字节
 * - 位置 xyz: 3×float32 (12 bytes)
 * - 缩放 xyz: 3×float32 (12 bytes)
 * - 颜色 rgba: 4×uint8 (4 bytes)
 * - 旋转 ijkl: 4×uint8 (4 bytes)
 *
 * 总计 32 字节/点，非常紧凑
 */
const serializeSplat = async (splats: Splat[], options: SerializeSettings, fs: FileSystem): Promise<void> => {
    const writer = await fs.createWriter('output.splat');
    const filter = new GaussianFilter(options);
    const totalGaussians = countGaussians(splats, filter);
    if (totalGaussians === 0) {
        return;
    }

    // 每个高斯点 32 字节
    const result = new Uint8Array(totalGaussians * 32);
    const dataView = new DataView(result.buffer);

    let idx = 0;

    const props = ['x', 'y', 'z', 'opacity', 'rot_0', 'rot_1', 'rot_2', 'rot_3', 'f_dc_0', 'f_dc_1', 'f_dc_2', 'scale_0', 'scale_1', 'scale_2'];
    const singleSplat = new SingleSplat(props, options);
    const { data } = singleSplat;

    // 钳制函数：将浮点数限制在 [0, 255] 范围
    const clamp = (x: number) => Math.max(0, Math.min(255, x));
    const SH_C0 = 0.28209479177387814;

    for (let e = 0; e < splats.length; ++e) {
        const splat = splats[e];
        const { splatData } = splat;
        filter.set(splat);

        for (let i = 0; i < splatData.numSplats; ++i) {
            if (!filter.test(i)) continue;

            singleSplat.read(splat, i);

            const off = idx++ * 32;

            // 位置：float32（小端）
            dataView.setFloat32(off + 0, data.x, true);
            dataView.setFloat32(off + 4, data.y, true);
            dataView.setFloat32(off + 8, data.z, true);

            // 缩放：exp(scale) 后作为 float32
            dataView.setFloat32(off + 12, Math.exp(data.scale_0), true);
            dataView.setFloat32(off + 16, Math.exp(data.scale_1), true);
            dataView.setFloat32(off + 20, Math.exp(data.scale_2), true);

            // 颜色 RGBA：uint8，从 SH DC 系数转换
            dataView.setUint8(off + 24, clamp((0.5 + SH_C0 * data.f_dc_0) * 255));
            dataView.setUint8(off + 25, clamp((0.5 + SH_C0 * data.f_dc_1) * 255));
            dataView.setUint8(off + 26, clamp((0.5 + SH_C0 * data.f_dc_2) * 255));
            dataView.setUint8(off + 27, clamp((1 / (1 + Math.exp(-data.opacity))) * 255));

            // 旋转四元数：uint8，从 [-1, 1] 映射到 [0, 255]
            dataView.setUint8(off + 28, clamp(data.rot_0 * 128 + 128));
            dataView.setUint8(off + 29, clamp(data.rot_1 * 128 + 128));
            dataView.setUint8(off + 30, clamp(data.rot_2 * 128 + 128));
            dataView.setUint8(off + 31, clamp(data.rot_3 * 128 + 128));
        }
    }

    await writer.write(result);
    await writer.close();
};

// 缓存的 WebGPU 设备（用于 SOG 压缩的 GPU 计算）
let cachedGpuDevice: WebgpuGraphicsDevice | null = null;
let cachedBackbuffer: Texture | null = null;

/**
 * 创建或获取缓存的 WebGPU 设备
 *
 * SOG 格式的压缩需要使用 WebGPU 进行 GPU 加速计算，
 * 创建并缓存一个轻量级的 WebGPU 设备以供复用
 */
const createGpuDevice = async (): Promise<WebgpuGraphicsDevice> => {
    if (cachedGpuDevice) {
        return cachedGpuDevice;
    }

    if (!navigator.gpu) {
        throw new Error('WebGPU is not available in this browser');
    }

    // 创建最小的画布用于图形设备
    const canvas = document.createElement('canvas');
    canvas.width = 1024;
    canvas.height = 512;

    const graphicsDevice = new WebgpuGraphicsDevice(canvas, {
        antialias: false,
        depth: false,
        stencil: false
    });

    await graphicsDevice.createDevice();

    // 创建外部后台缓冲区（PlayCanvas 要求有此属性）
    cachedBackbuffer = new Texture(graphicsDevice, {
        width: 1024,
        height: 512,
        name: 'SogComputeBackbuffer',
        mipmaps: false,
        format: PIXELFORMAT_BGRA8
    });

    // @ts-ignore - externalBackbuffer 是 PlayCanvas 的内部属性
    graphicsDevice.externalBackbuffer = cachedBackbuffer;

    cachedGpuDevice = graphicsDevice;
    return graphicsDevice;
};

/**
 * 从 Splat 数组提取数据到 DataTable（供 splat-transform 库使用）
 *
 * DataTable 是 @playcanvas/splat-transform 库的核心数据结构，
 * 用于 SOG 压缩和 HTML 查看器导出
 *
 * @param splats - splat 数组
 * @param settings - 序列化设置
 * @returns 填充好数据的 DataTable 对象
 */
const extractDataTable = (splats: Splat[], settings: SerializeSettings): DataTable => {
    const { maxSHBands = 3 } = settings;

    // 确定需要提取的属性列表
    const shCoeffs = [0, 3, 8, 15][maxSHBands];
    const memberNames = [
        'x', 'y', 'z',
        'scale_0', 'scale_1', 'scale_2',
        'f_dc_0', 'f_dc_1', 'f_dc_2', 'opacity',
        'rot_0', 'rot_1', 'rot_2', 'rot_3',
        ...shNames.slice(0, shCoeffs * 3)
    ];

    const singleSplat = new SingleSplat(memberNames, settings);

    const filter = new GaussianFilter(settings);

    // 统计总数
    let totalCount = 0;
    for (const splat of splats) {
        filter.set(splat);
        for (let i = 0; i < splat.splatData.numSplats; ++i) {
            if (filter.test(i)) {
                totalCount++;
            }
        }
    }

    if (totalCount === 0) {
        throw new Error('No gaussians to export');
    }

    // 创建 DataTable 列。
    // 使用 Transform.PLY 标签标记坐标系：
    //   SingleSplat.read 已经预应用了 PLY 风格的 180° Z 轴翻转（见 SplatTransformCache.getMat），
    //   所以列数据已经处于 PLY 坐标系。
    //   如果不标记此标签，splat-transform 的写入器（writeSog, writeHtml）会重复应用 Z 翻转，
    //   导致输出结果上下颠倒。
    const columns = memberNames.map(name => new Column(name, new Float32Array(totalCount)));
    const dataTable = new DataTable(columns, Transform.PLY);

    // 填充数据
    let idx = 0;
    for (const splat of splats) {
        filter.set(splat);
        for (let i = 0; i < splat.splatData.numSplats; ++i) {
            if (!filter.test(i)) continue;

            singleSplat.read(splat, i);

            for (let j = 0; j < memberNames.length; ++j) {
                (columns[j].data as Float32Array)[idx] = singleSplat.data[memberNames[j]] ?? 0;
            }
            idx++;
        }
    }

    return dataTable;
};

/**
 * 创建进度渲染器：桥接 splat-transform 库的日志事件到 SuperSplat 的事件系统
 *
 * splat-transform 库的日志系统（logger）发出各种进度事件（scope/bar/message），
 * 此函数创建一个适配器将其转换为 SuperSplat 的事件格式，
 * 使得 UI 可以显示导出进度
 */
const createProgressRenderer = (header: string, events?: Events): Renderer => ({
    handle: (event: LogEvent) => {
        switch (event.kind) {
            case 'scopeStart':
                if (event.depth === 0) {
                    events?.fire('progressStart', header);
                } else {
                    events?.fire('progressUpdate', {
                        text: event.index !== undefined && event.total !== undefined ?
                            `Step ${event.index} of ${event.total}: ${event.name}` :
                            event.name,
                        progress: 0
                    });
                }
                break;
            case 'scopeEnd':
                if (event.depth === 0) {
                    events?.fire('progressEnd');
                }
                break;
            case 'barStart':
                events?.fire('progressUpdate', { text: event.name, progress: 0 });
                break;
            case 'barTick':
                events?.fire('progressUpdate', {
                    progress: event.total > 0 ? 100 * event.current / event.total : 0
                });
                break;
            case 'barEnd':
                events?.fire('progressUpdate', { progress: 100 });
                break;
            case 'message':
                if (event.level === 'error') console.error(event.text);
                else if (event.level === 'warn') console.warn(event.text);
                else if (event.level === 'info') console.info(event.text);
                else if (event.level === 'debug') console.debug(event.text);
                break;
            case 'output':
                console.log(event.text);
                break;
        }
    }
});

/**
 * 导出 HTML/ZIP 查看器格式
 *
 * HTML 模式：生成单个自包含的 HTML 文件（内嵌所有数据）
 * ZIP 模式：生成解耦的 HTML + SOG 数据文件打包
 *
 * 两种模式都使用 @playcanvas/splat-transform 库的 writeHtml 函数生成
 */
const serializeViewer = async (splats: Splat[], serializeSettings: SerializeSettings, options: ViewerExportSettings, fs: FileSystem): Promise<void> => {
    const { experienceSettings, events } = options;

    splatTransformLogger.setRenderer(createProgressRenderer('Exporting HTML', events));

    // 提取数据到 DataTable
    const dataTable = extractDataTable(splats, serializeSettings);

    // splat-transform 的写入器在出错时不会关闭其顶层作用域
    //（它们的约定是由调用方来清理），所以我们在这里显式关闭作用域
    // 以确保在显示错误弹窗前触发 progressEnd 并关闭进度对话框
    try {
        if (options.type === 'html') {
            // 捆绑模式：所有数据内嵌在 HTML 中
            await writeHtml({
                filename: 'output.html',
                dataTable,
                viewerSettingsJson: experienceSettings,
                bundle: true,
                iterations: 10,
                createDevice: createGpuDevice
            }, fs);
        } else {
            // ZIP 打包模式：先用内存文件系统生成未捆绑的文件，再压缩为 ZIP
            const memFs = new MemoryFileSystem();
            await writeHtml({
                filename: 'index.html',
                dataTable,
                viewerSettingsJson: experienceSettings,
                bundle: false,
                iterations: 10,
                createDevice: createGpuDevice
            }, memFs);

            // 将内存文件系统的结果写入 ZIP
            const zipWriter = await fs.createWriter('output.zip');
            const zipFs = new ZipFileSystem(zipWriter);
            try {
                for (const [filename, data] of memFs.results.entries()) {
                    const writer = await zipFs.createWriter(filename);
                    await writer.write(data);
                    await writer.close();
                }
            } finally {
                await zipFs.close();
            }
        }
    } catch (err) {
        splatTransformLogger.unwindAll(true);
        throw err;
    }
};

// SOG（Compressed Gaussian Splat）序列化，使用 splat-transform 库

/** SOG 导出设置（继承 SerializeSettings，增加迭代次数） */
type SogSettings = SerializeSettings & {
    /** 压缩迭代次数（越高压缩质量越好，默认 10） */
    iterations: number;
    events?: Events;
};

/**
 * 导出 SOG（SuperSplat Optimized Gaussian）格式
 *
 * SOG 是 SuperSplat 专有的压缩高斯泼溅格式，
 * 使用 GPU 加速的迭代优化算法进行有损压缩
 */
const serializeSog = async (splats: Splat[], settings: SogSettings, fs: FileSystem): Promise<void> => {
    const { iterations = 10, events } = settings;

    splatTransformLogger.setRenderer(createProgressRenderer('Exporting SOG', events));

    const dataTable = extractDataTable(splats, settings);

    // 确保出错时清理 splat-transform 的作用域栈
    try {
        await writeSogInternal({
            filename: 'output.sog',
            dataTable,
            bundle: true,
            iterations,
            createDevice: createGpuDevice
        }, fs);
    } catch (err) {
        splatTransformLogger.unwindAll(true);
        throw err;
    }
};

