/**
 * camera-poses.ts - 相机姿态管理与动画轨道
 *
 * 本文件实现了相机关键帧动画系统，允许用户在时间线上设置相机姿态关键帧，
 * 并在播放时通过样条曲线平滑插值。
 *
 * 核心组件：
 * - Pose 类型：定义单个关键帧的姿态（位置、目标、FOV、帧号）
 * - CameraAnimTrack 类：相机动画轨道，管理关键帧的增删改查和样条插值
 *   - 实现 AnimTrack 接口，可嵌入通用时间线系统
 *   - 完全自包含：内部订阅时间线事件以驱动求值和样条重建
 * - registerCameraPosesEvents()：注册事件处理器，将轨道暴露给外部使用
 *
 * 技术要点：
 * - 使用 CubicSpline（三次样条）进行平滑插值
 * - 支持循环动画（fromPointsLooping）
 * - 支持关键帧移动、复制、快照/恢复等编辑操作
 * - 兼容旧的序列化格式（文档导入/导出）
 */

import { Vec3 } from 'playcanvas';

import { CubicSpline } from './anim/spline';
import { AnimTrack } from './anim-track';
import { Events } from './events';

/**
 * Pose 类型 - 单帧相机姿态。
 *
 * 包含相机在时间线上某一帧的所有参数：
 * - name: 姿态名称（用于 UI 标识）
 * - frame: 时间线帧号
 * - position: 相机世界空间位置
 * - target: 注视目标世界空间位置
 * - fov: 视场角（度数，可选）
 */
type Pose = {
    name: string,
    frame: number,
    position: Vec3,
    target: Vec3,
    fov?: number
};

/**
 * CameraAnimTrack 类 - 相机动画轨道。
 *
 * 实现 AnimTrack 接口，管理与相机动画相关的关键帧和样条插值。
 *
 * 关键帧存储为 Pose 对象数组，当关键帧数量 >= 2 时，
 * 使用 CubicSpline 进行帧间平滑插值，插值结果通过
 * 'camera.setPose' 事件驱动场景相机更新。
 *
 * 设计原则：完全自包含。构造函数内部订阅所有需要的时间线事件，
 * 外部只需创建实例并通过事件系统暴露即可。
 */
class CameraAnimTrack implements AnimTrack {
    /** 关键帧列表 */
    private poses: Pose[] = [];
    private events: Events;
    /** 样条曲线求值回调（重建样条时设置） */
    private onTimelineChange: ((frame: number) => void) | null = null;

    /**
     * @param events - 事件系统，用于订阅时间线事件和触发相机更新
     */
    constructor(events: Events) {
        this.events = events;

        // 时间线播放/拖动时求值当前帧的相机姿态
        events.on('timeline.time', (time: number) => {
            this.evaluate(time);
        });

        events.on('timeline.frame', (frame: number) => {
            this.evaluate(frame);
        });

        // 时间线帧数或平滑度改变时重建样条曲线
        events.on('timeline.frames', () => {
            this.rebuildSpline();
        });

        events.on('timeline.smoothness', () => {
            this.rebuildSpline();
        });

        // 场景清除时重置轨道
        events.on('scene.clear', () => {
            this.clear();
        });
    }

    /**
     * 获取所有关键帧的帧号列表。
     * 实现 AnimTrack 接口。
     */
    get keys(): readonly number[] {
        return this.poses.map(p => p.frame);
    }

    /**
     * 在指定帧添加或更新关键帧。
     *
     * 获取当前相机姿态作为关键帧内容。
     * 如果该帧已有关键帧则替换，否则新增。
     *
     * @param frame - 时间线帧号
     * @returns 成功返回 true
     */
    addKey(frame: number): boolean {
        const pose = this.events.invoke('camera.getPose');
        if (!pose) return false;

        const existingIndex = this.poses.findIndex(p => p.frame === frame);

        // 从事件获取当前相机姿态，复制为新的 Pose 对象
        const newPose: Pose = {
            name: `camera_${this.poses.length}`,
            frame,
            position: new Vec3(pose.position.x, pose.position.y, pose.position.z),
            target: new Vec3(pose.target.x, pose.target.y, pose.target.z),
            fov: pose.fov
        };

        if (existingIndex === -1) {
            // 新帧：添加到列表
            this.poses.push(newPose);
            this.rebuildSpline();
            this.events.fire('track.keyAdded', frame);
        } else {
            // 已存在的帧：替换
            this.poses[existingIndex] = newPose;
            this.rebuildSpline();
            this.events.fire('track.keyUpdated', frame);
        }
        return true;
    }

    /**
     * 移除指定帧的关键帧。
     *
     * @param frame - 要移除的帧号
     * @returns 如果该帧存在关键帧则返回 true
     */
    removeKey(frame: number): boolean {
        const index = this.poses.findIndex(p => p.frame === frame);
        if (index === -1) return false;
        this.poses.splice(index, 1);
        this.rebuildSpline();
        this.events.fire('track.keyRemoved', frame);
        return true;
    }

    /**
     * 将关键帧从一帧移动到另一帧。
     *
     * 如果目标帧已有关键帧，先移除原有帧再移动。
     *
     * @param fromFrame - 源帧号
     * @param toFrame - 目标帧号
     * @returns 成功返回 true
     */
    moveKey(fromFrame: number, toFrame: number): boolean {
        if (fromFrame === toFrame) return false;

        const index = this.poses.findIndex(p => p.frame === fromFrame);
        if (index === -1) return false;

        // 移除目标帧的现有关键帧
        const toIndex = this.poses.findIndex(p => p.frame === toFrame);
        if (toIndex !== -1) {
            this.poses.splice(toIndex, 1);
        }

        // 更新帧号（splice 可能改变了索引，重新查找）
        const movedIndex = this.poses.findIndex(p => p.frame === fromFrame);
        this.poses[movedIndex].frame = toFrame;
        this.rebuildSpline();
        this.events.fire('track.keyMoved', fromFrame, toFrame);
        return true;
    }

    /**
     * 将一帧的关键帧复制到另一帧。
     *
     * 如果目标帧已有关键帧，先移除再复制。
     * 复制会创建新的 Pose 对象（深拷贝位置和目标）。
     *
     * @param fromFrame - 源帧号
     * @param toFrame - 目标帧号
     * @returns 成功返回 true
     */
    copyKey(fromFrame: number, toFrame: number): boolean {
        if (fromFrame === toFrame) return false;

        const source = this.poses.find(p => p.frame === fromFrame);
        if (!source) return false;

        // 移除目标帧的现有关键帧
        const toIndex = this.poses.findIndex(p => p.frame === toFrame);
        if (toIndex !== -1) {
            this.poses.splice(toIndex, 1);
        }

        // 深拷贝姿态数据
        this.poses.push({
            name: `camera_${this.poses.length}`,
            frame: toFrame,
            position: source.position.clone(),
            target: source.target.clone(),
            fov: source.fov
        });

        this.rebuildSpline();
        this.events.fire('track.keyAdded', toFrame);
        return true;
    }

    /**
     * 在当前帧求值相机姿态。
     *
     * 调用样条曲线的 evaluate 计算插值结果，
     * 通过 'camera.setPose' 事件更新场景相机。
     *
     * @param frame - 时间线帧号
     */
    evaluate(frame: number): void {
        this.onTimelineChange?.(frame);
    }

    /**
     * 清除所有关键帧并重置轨道。
     */
    clear(): void {
        this.poses.length = 0;
        this.onTimelineChange = null;
        this.events.fire('track.keysCleared');
    }

    /**
     * 创建当前轨道状态的快照（用于撤销/重做系统）。
     *
     * @returns Pose 数组的深拷贝
     */
    snapshot(): Pose[] {
        return this.poses.map(p => ({
            name: p.name,
            frame: p.frame,
            position: p.position.clone(),
            target: p.target.clone(),
            fov: p.fov
        }));
    }

    /**
     * 从快照恢复轨道状态。
     *
     * @param snapshot - 由 snapshot() 创建的快照数据
     */
    restore(snapshot: unknown): void {
        this.poses = (snapshot as Pose[]).map(p => ({
            name: p.name,
            frame: p.frame,
            position: p.position.clone(),
            target: p.target.clone(),
            fov: p.fov
        }));
        this.rebuildSpline();
        this.events.fire('track.keysLoaded');
    }

    /**
     * 直接添加一个 Pose 对象（用于反序列化和旧格式导入）。
     *
     * @param pose - 要添加的 Pose 对象
     */
    addPose(pose: Pose): void {
        if (pose.frame === undefined) {
            return;
        }

        // 确保 FOV 有默认值
        pose.fov ??= this.events.invoke('camera.fov') ?? 60;

        const idx = this.poses.findIndex(p => p.frame === pose.frame);
        if (idx !== -1) {
            this.poses[idx] = pose;
            this.rebuildSpline();
            this.events.fire('track.keyUpdated', pose.frame);
        } else {
            this.poses.push(pose);
            this.rebuildSpline();
            this.events.fire('track.keyAdded', pose.frame);
        }
    }

    /**
     * 获取所有 Pose 对象（用于序列化和旧版本兼容）。
     *
     * @returns 只读的 Pose 数组
     */
    getPoses(): readonly Pose[] {
        return this.poses;
    }

    /**
     * 从序列化数据加载所有 Pose。
     *
     * @param posesData - Pose 对象数组
     */
    loadPoses(posesData: Pose[]): void {
        this.poses.length = 0;
        posesData.forEach((pose) => {
            this.poses.push(pose);
        });
        this.rebuildSpline();
        this.events.fire('track.keysLoaded');
    }

    /**
     * 重建样条曲线。
     *
     * 当关键帧列表、时间线帧数或平滑度改变时调用。
     *
     * 工作流程：
     * 1. 获取当前时间线的总帧数和平滑度参数
     * 2. 按帧号排序关键帧，过滤超出范围的帧
     * 3. 将 Pose 数据展平为数值数组（7 个值/帧：pos.xyz, target.xyz, fov）
     * 4. 创建循环 CubicSpline 并设置 onTimelineChange 回调
     * 5. 立即在当前帧求值以更新相机
     */
    private rebuildSpline(): void {
        const duration = this.events.invoke('timeline.frames');
        const smoothness = this.events.invoke('timeline.smoothness');

        // 按帧号排序，过滤超出时间线范围的帧
        const orderedPoses = this.poses.slice()
        .filter(a => a.frame < duration)
        .sort((a, b) => a.frame - b.frame);

        const times = orderedPoses.map(p => p.frame);
        // 将关键帧展开为连续数值数组：
        // [pos.x, pos.y, pos.z, target.x, target.y, target.z, fov, ...]
        const points: number[] = [];
        for (let i = 0; i < orderedPoses.length; ++i) {
            const p = orderedPoses[i];
            points.push(p.position.x, p.position.y, p.position.z);
            points.push(p.target.x, p.target.y, p.target.z);
            points.push(p.fov);
        }

        if (orderedPoses.length > 1) {
            // 至少两个关键帧：创建循环样条曲线
            // fromPointsLooping 确保动画可以无缝循环
            const spline = CubicSpline.fromPointsLooping(duration, times, points, smoothness);
            const result: number[] = [];
            const pose = { position: new Vec3(), target: new Vec3(), fov: 0 };

            // 设置求值回调：每帧被调用时计算插值结果
            this.onTimelineChange = (frame: number) => {
                spline.evaluate(frame, result);
                // result 是 [px, py, pz, tx, ty, tz, fov] 格式
                pose.position.set(result[0], result[1], result[2]);
                pose.target.set(result[3], result[4], result[5]);
                pose.fov = result[6];
                // 通过事件驱动相机更新
                this.events.fire('camera.setPose', pose, 0);
            };
        } else {
            // 少于两个关键帧：禁用插值
            this.onTimelineChange = null;
        }

        // 立即在当前帧求值，使相机立即更新到正确位置
        this.evaluate(this.events.invoke('timeline.frame'));
    }
}

/**
 * 注册相机姿态相关的事件处理器。
 *
 * 此函数创建 CameraAnimTrack 实例，并通过 events 系统暴露：
 * - 'camera.animTrack': 获取动画轨道实例
 * - 'camera.poses': 获取所有关键帧（旧 API 兼容）
 * - 'camera.addPose': 直接添加姿态（旧 API 兼容）
 * - 'docSerialize.poseSets': 序列化姿态数据
 * - 'docDeserialize.poseSets': 从文档数据反序列化姿态
 *
 * 轨道完全自包含（内部订阅时间线事件），此函数只负责创建和暴露。
 *
 * @param events - 全局事件系统
 */
const registerCameraPosesEvents = (events: Events) => {
    const track = new CameraAnimTrack(events);

    // 暴露相机动画轨道
    events.function('camera.animTrack', () => {
        return track;
    });

    // 旧 API 兼容：暴露关键帧列表
    events.function('camera.poses', () => {
        return track.getPoses();
    });

    // 旧 API 兼容：直接添加姿态
    events.on('camera.addPose', (pose: Pose) => {
        track.addPose(pose);
    });

    /**
     * 序列化姿态集合（文档保存时调用）。
     *
     * 将 Pose 数组转换为可序列化的格式：
     * [{ name: 'set0', poses: [{ name, frame, position: [x,y,z], target: [x,y,z], fov }] }]
     *
     * 使用 poseSets 数组包装以兼容未来多轨道扩展。
     *
     * @returns 序列化后的姿态集合数组
     */
    events.function('docSerialize.poseSets', (): any[] => {
        const pack3 = (v: Vec3) => [v.x, v.y, v.z];
        const poses = track.getPoses();

        if (poses.length === 0) {
            return [];
        }

        return [{
            name: 'set0',
            poses: poses.map((pose) => {
                return {
                    name: pose.name,
                    frame: pose.frame,
                    position: pack3(pose.position),
                    target: pack3(pose.target),
                    fov: pose.fov
                };
            })
        }];
    });

    /**
     * 反序列化姿态集合（文档加载时调用）。
     *
     * 从文档数据恢复相机关键帧，处理以下兼容逻辑：
     * - 如果 frame 未定义，使用 (index * fps) 作为默认帧号
     * - 如果 fov 未定义，使用文档预置或当前相机 FOV 作为默认值
     *
     * @param poseSets - 文档中的姿态集合数组
     * @param documentCameraFov - 文档中预设的相机 FOV（旧格式兼容）
     */
    events.function('docDeserialize.poseSets', (poseSets: any[], documentCameraFov?: number) => {
        if (!poseSets || poseSets.length === 0) {
            return;
        }

        const fps = events.invoke('timeline.frameRate');

        // 默认 FOV：优先用文档预置，其次当前相机 FOV，最后回退到 60
        const defaultFov = documentCameraFov ?? events.invoke('camera.fov') ?? 60;

        const loadedPoses: Pose[] = poseSets[0].poses.map((docPose: any, index: number) => {
            return {
                name: docPose.name,
                // 旧格式可能没有 frame，使用索引 * FPS 估算
                frame: docPose.frame ?? (index * fps),
                position: new Vec3(docPose.position),
                target: new Vec3(docPose.target),
                fov: docPose.fov ?? defaultFov
            };
        });

        track.loadPoses(loadedPoses);
    });
};

export { registerCameraPosesEvents, CameraAnimTrack, Pose };
