/**
 * 球体选择工具 (SphereSelection)
 *
 * 核心功能：
 * 1. 在场景中放置一个可拖拽的半透明球体 (SphereShape)，用于可视化球形选择范围
 * 2. 通过 TranslateGizmo（位移操纵器）拖拽球体改变其位置
 * 3. 在工具栏中提供"设置/添加/移除"三个按钮，对球体范围内的高斯点云执行相应操作
 * 4. 支持通过数值输入框精确调整球体的半径尺寸
 *
 * 整体流程：
 * - activate() 激活工具 → 显示球体和工具栏 → 监听相机焦点拾取事件
 * - 用户通过 Gizmo 拖拽球体定位 → 点击 Set/Add/Remove 按钮选择范围内的 splat
 * - deactivate() 关闭工具 → 移除球体和工具栏
 *
 * 与 BoxSelection 的区别：
 * - BoxSelection 使用长方体 (BoxShape)，选择区域为轴对齐立方体
 * - SphereSelection 使用球体 (SphereShape)，选择区域为球体
 * - SphereSelection 传给 'select.bySphere' 的参包含球心坐标 + 半径，而非长宽高
 *
 * 事件通信：
 * - 监听 'camera.focalPointPicked' → 将球体移动到点击位置
 * - 触发 'select.bySphere' → 通知选择系统在球形范围内执行选择/添加/移除
 */

import { Button, Container, NumericInput } from '@playcanvas/pcui';
import { TranslateGizmo, Vec3 } from 'playcanvas';

import { Events } from '../events';
import { Scene } from '../scene';
import { SphereShape } from '../sphere-shape';
import { Splat } from '../splat';

class SphereSelection {
    /** 激活工具的回调函数，在 ToolManager 注册时绑定 */
    activate: () => void;
    /** 停用工具的回调函数，在 ToolManager 注册时绑定 */
    deactivate: () => void;

    /** 当前工具是否处于激活状态 */
    active = false;

    /**
     * 构造函数：初始化球体选择工具所需的所有 UI 和交互逻辑
     *
     * @param events - 全局事件总线，用于各子系统间的通信
     * @param scene - 场景管理器，提供相机、画布、渲染层等引用
     * @param canvasContainer - PCUI 的 Container 组件，作为 UI 工具栏的父容器
     */
    constructor(events: Events, scene: Scene, canvasContainer: Container) {
        // ---- 创建可视化球体（选择范围的视觉表示） ----
        const sphere = new SphereShape();

        // ---- 创建平移操纵器 (Gizmo)，允许用户拖拽移动球体 ----
        const gizmo = new TranslateGizmo(scene.camera.camera, scene.gizmoLayer);

        // Gizmo 渲染更新时触发 → 强制场景重绘
        gizmo.on('render:update', () => {
            scene.forceRender = true;
        });

        // Gizmo 拖拽移动时 → 通知 SphereShape 更新内部状态
        gizmo.on('transform:move', () => {
            sphere.moved();
        });

        // ---- 构建工具栏 UI ----
        const selectToolbar = new Container({
            class: 'select-toolbar',
            hidden: true        // 默认隐藏，仅在工具激活时显示
        });

        // 阻止工具栏上的指针事件冒泡
        selectToolbar.dom.addEventListener('pointerdown', (e) => {
            e.stopPropagation();
        });

        // 操作按钮：设置/添加/移除
        const setButton = new Button({ text: 'Set', class: 'select-toolbar-button' });
        const addButton = new Button({ text: 'Add', class: 'select-toolbar-button' });
        const removeButton = new Button({ text: 'Remove', class: 'select-toolbar-button' });

        // 球体半径输入框（精度 2 位小数，最小值 0.01，确保球体不会消失）
        const radius = new NumericInput({
            precision: 2,
            value: sphere.radius,
            placeholder: 'Radius',
            width: 80,
            min: 0.01
        });

        // 将所有 UI 元素添加到工具栏容器
        selectToolbar.append(setButton);
        selectToolbar.append(addButton);
        selectToolbar.append(removeButton);
        selectToolbar.append(radius);

        canvasContainer.append(selectToolbar);

        /**
         * 执行选择操作的通用函数
         *
         * @param op - 操作类型：'set'（替换选择）、'add'（添加到选择）、'remove'（从选择中移除）
         *
         * 通过事件总线触发 'select.bySphere' 事件，将球心坐标和半径传递给选择系统。
         * 选择系统根据球心与每个 splat 的距离判断其是否在球体范围内。
         */
        const apply = (op: 'set' | 'add' | 'remove') => {
            const p = sphere.pivot.getPosition();
            events.fire('select.bySphere', op, [p.x, p.y, p.z, sphere.radius]);
        };

        // 按钮点击事件，阻止冒泡后执行对应操作
        setButton.dom.addEventListener('pointerdown', (e) => {
            e.stopPropagation(); apply('set');
        });
        addButton.dom.addEventListener('pointerdown', (e) => {
            e.stopPropagation(); apply('add');
        });
        removeButton.dom.addEventListener('pointerdown', (e) => {
            e.stopPropagation(); apply('remove');
        });

        // 半径输入框值变化时 → 同步更新球体半径
        radius.on('change', () => {
            sphere.radius = radius.value;
        });

        // ---- 相机焦点拾取事件 ----
        // 当用户在 3D 场景中点击选中某个 splat 时，将球体移动到该位置
        events.on('camera.focalPointPicked', (details: { splat: Splat, position: Vec3 }) => {
            if (this.active) {
                sphere.pivot.setPosition(details.position);
                gizmo.attach([sphere.pivot]);
            }
        });

        /**
         * 根据当前相机模式和画布尺寸动态计算 Gizmo 的大小。
         * 保证操纵器在不同分辨率下保持一致的交互体验。
         */
        const updateGizmoSize = () => {
            const { camera, canvas } = scene;
            if (camera.ortho) {
                // 正交相机：与画布高度成反比
                gizmo.size = 1125 / canvas.clientHeight;
            } else {
                // 透视相机：与画布长边最大值成反比
                gizmo.size = 1200 / Math.max(canvas.clientWidth, canvas.clientHeight);
            }
        };
        updateGizmoSize();
        events.on('camera.resize', updateGizmoSize);
        events.on('camera.ortho', updateGizmoSize);

        /**
         * 激活工具：
         * - 将球体添加到场景中显示
         * - 将 Gizmo 附加到球体，允许拖拽操作
         * - 显示工具栏
         */
        this.activate = () => {
            this.active = true;
            scene.add(sphere);
            gizmo.attach([sphere.pivot]);
            selectToolbar.hidden = false;
        };

        /**
         * 停用工具：
         * - 隐藏工具栏
         * - 分离 Gizmo
         * - 从场景中移除球体
         */
        this.deactivate = () => {
            selectToolbar.hidden = true;
            gizmo.detach();
            scene.remove(sphere);
            this.active = false;
        };
    }
}

export { SphereSelection };
