/**
 * 判断一组文件名是否为 PLY 序列
 * PLY 序列的特征：所有文件共享相同的前缀，后跟数字帧号
 * 例如：frame0001.ply, frame0002.ply, frame0003.ply
 *
 * @param filenames - 文件名数组
 * @returns 如果是 PLY 序列返回 true，否则返回 false
 */
// determine if all files share a common filename prefix followed by
// a frame number, e.g. "frame0001.ply", "frame0002.ply", etc.
const isPlySequence = (filenames: string[]) => {
    // 至少需要2个文件才能构成序列
    if (filenames.length < 2) {
        return false;
    }


    // 正则匹配：前缀 + 数字 + 可选 .compressed + .ply
    // 捕获组1 = 前缀，捕获组2 = 帧编号
    const regex = /(.*?)(\d+)(?:\.compressed)?\.ply$/;
    const baseMatch = filenames[0].match(regex);
    if (!baseMatch) {
        return false;
    }

    // 检查所有文件名是否与第一个文件共享相同前缀
    for (let i = 1; i < filenames.length; i++) {
        const thisMatch = filenames[i].match(regex);
        if (!thisMatch || thisMatch[1] !== baseMatch[1]) {
            return false;
        }
    }

    return true;
};

/**
 * 判断文件组是否为 SOG 格式
 * SOG 格式由一个 meta.json 文件和零个或多个 .webp 文件组成
 *
 * @param filenames - 文件名数组
 * @returns 如果是 SOG 格式返回 true
 */
// sog comprises a single meta.json file and zero or more .webp files
const isSog = (filenames: string[]) => {
    // 统计特定扩展名的文件数量
    const count = (extension: string) => filenames.reduce((sum, f) => sum + (f.endsWith(extension) ? 1 : 0), 0);
    return count('meta.json') === 1;
};

/**
 * 判断文件组是否为 LCC 格式
 * LCC 格式包含 meta.lcc、index.bin、data.bin 和可选的 shcoef.bin
 *
 * @param filenames - 文件名数组
 * @returns 如果是 LCC 格式返回 true
 */
// The LCC file contains meta.lcc, index.bin, data.bin and shcoef.bin (optional)
const isLcc = (filenames: string[]) => {
    // 统计特定扩展名的文件数量
    const count = (extension: string) => filenames.reduce((sum, f) => sum + (f.endsWith(extension) ? 1 : 0), 0);
    return count('.lcc') === 1;
};

/**
 * 导入文件的描述结构
 * @param filename - 文件名
 * @param url - 文件 URL（用于远程文件）
 * @param contents - 文件内容对象（File API）
 * @param handle - 文件系统句柄（File System Access API）
 */
type ImportFile = {
    filename: string;
    url?: string;
    contents?: File;
    handle?: FileSystemFileHandle;
};

// 临时向量，避免频繁分配内存
const vec = new Vec3();

/**
 * 加载 INRIA 格式的相机位姿 JSON 文件
 * INRIA 数据集使用 JSON 格式存储相机位姿（position 和 rotation 矩阵）
 *
 * 算法思路：
 * 1. 从 JSON 中读取相机的 position 和 rotation 矩阵
 * 2. 从 rotation 矩阵中提取 Z 轴方向作为视线方向
 * 3. 根据相机内参（fx, fy, width, height）计算 FOV
 * 4. 将位姿转换到 SuperSplat 的坐标系
 *
 * @param file - 导入文件描述
 * @param events - 事件系统，用于触发 camera.addPose 事件
 */
// load inria camera poses from json file
const loadCameraPoses = async (file: ImportFile, events: Events) => {
    const response = new Response(file.contents);
    const json = await response.json();

    if (json.length > 0) {
        // 按帧编号排序：优先使用 id 字段，其次从 img_name 末尾提取数字
        // sort entries by trailing number if it exists
        const sorter = (a: any, b: any) => {
            const avalue = a.id ?? a.img_name?.match(/\d*$/)?.[0];
            const bvalue = b.id ?? b.img_name?.match(/\d*$/)?.[0];
            return (avalue && bvalue) ? parseInt(avalue, 10) - parseInt(bvalue, 10) : 0;
        };

        json.sort(sorter).forEach((pose: any, i: number) => {
            // 只处理同时包含 position 和 rotation 的位姿
            if (pose.hasOwnProperty('position') && pose.hasOwnProperty('rotation')) {
                const p = new Vec3(pose.position);
                // rotation 是 3x3 矩阵，取第三列作为 Z 轴方向（视线方向）
                const z = new Vec3(pose.rotation[0][2], pose.rotation[1][2], pose.rotation[2][2]);

                // 沿 Z 轴方向偏移10个单位，得到目标点位置
                // Use fixed offset along Z-axis direction instead of variable dot product
                vec.copy(z).mulScalar(10).add(p);

                // 根据相机内参计算视场角（FOV）
                // 取水平和垂直 FOV 中较大的一个
                // compute max FOV from intrinsics (vertical or horizontal, whichever is larger)
                let fov = 60;
                if (pose.fx && pose.fy && pose.width && pose.height) {
                    const fovX = 2 * Math.atan(pose.width / (2 * pose.fx)) * (180 / Math.PI);
                    const fovY = 2 * Math.atan(pose.height / (2 * pose.fy)) * (180 / Math.PI);
                    fov = Math.max(fovX, fovY);
                }

                // 触发添加位姿事件，注意 SuperSplat 使用不同的坐标系约定
                events.fire('camera.addPose', {
                    name: pose.img_name ?? `${file.filename}_${i}`,
                    frame: i,
                    position: new Vec3(-p.x, -p.y, p.z),
                    target: new Vec3(-vec.x, -vec.y, vec.z),
                    fov
                });
            }
        });
    }
};

/**
 * 从文件名中移除扩展名
 * @param filename - 完整文件名（含扩展名）
 * @returns 不含扩展名的文件名
 */
const removeExtension = (filename: string) => {
    return filename.substring(0, filename.length - path.getExtension(filename).length);
};

/**
 * 加载 COLMAP 格式的 images.txt 文件
 *
 * COLMAP images.txt 格式说明：
 * - 每两行描述一张图像
 * - 第一行：IMAGE_ID QW QX QY QZ TX TY TZ CAMERA_ID NAME
 *   - 四元数 (QW, QX, QY, QZ) 表示相机旋转
 *   - (TX, TY, TZ) 表示相机平移（世界坐标）
 * - 第二行：2D 点观测数据（这里忽略）
 *
 * 参考：https://colmap.github.io/format.html#images-txt
 *
 * 算法思路：
 * 1. 解析文件，每2行取1行（跳过2D观测数据行）
 * 2. 从四元数和位移恢复相机位姿
 * 3. 转换到 SuperSplat 坐标系
 *
 * @param file - 导入文件描述
 * @param events - 事件系统
 */
// https://colmap.github.io/format.html#images-txt
const loadImagesTxt = async (file: ImportFile, events: Events) => {
    const response = new Response(file.contents);
    const text = await response.text();

    // 按行分割，去除注释和空行，每两行取一行（跳过2D观测数据）
    // split into lines, remove comments and empty lines
    const poses = text.split('\n')
    .map(line => line.trim())
    .filter(line => !line.startsWith('#'))      // 移除注释行（以#开头）
    .filter((_, i) => i % 2 === 0)              // 每隔一行取一行（跳过2D观测行）
    .map((line, i) => {
        const parts = line.split(' ');
        // images.txt 每行应有10个字段
        if (parts.length !== 10) {
            return null;
        }
        const name = parts[9];
        // 尝试从文件名末尾提取数字用于排序
        const order = parseInt(removeExtension(name).match(/\d+$/)?.[0], 10);
        return {
            w: parseFloat(parts[1]),  // 四元数 W 分量
            x: parseFloat(parts[2]),  // 四元数 X 分量
            y: parseFloat(parts[3]),  // 四元数 Y 分量
            z: parseFloat(parts[4]),  // 四元数 Z 分量
            tx: parseFloat(parts[5]), // X 轴平移
            ty: parseFloat(parts[6]), // Y 轴平移
            tz: parseFloat(parts[7]), // Z 轴平移
            name: name ?? `${file.filename}_${i}`,
            order: isFinite(order) ? order : i
        };
    })
    .filter(entry => !!entry)
    .sort((a, b) => (a.order < b.order ? -1 : 1));

    const q = new Quat();
    const t = new Vec3();

    // 处理每个位姿：将 COLMAP 坐标系转换到 SuperSplat 坐标系
    poses.forEach((pose, i) => {
        const { w, x, y, z, tx, ty, tz } = pose;

        // COLMAP 四元数表示世界到相机的旋转，取反并归一化得到相机到世界的旋转
        q.set(x, y, z, w).normalize().invert();
        // 取反平移向量
        t.set(-tx, -ty, -tz);
        // 应用旋转到平移向量
        q.transformVector(t, t);

        // 计算目标点：从相机位置沿视线方向偏移10个单位
        q.transformVector(Vec3.BACK, vec);
        vec.mulScalar(10).add(t);

        // 触发添加位姿事件，坐标系转换：X/Y 取反
        events.fire('camera.addPose', {
            name: pose.name,
            frame: i,
            position: new Vec3(-t.x, -t.y, t.z),
            target: new Vec3(-vec.x, -vec.y, vec.z)
        });
    });
};

/**
 * 初始化文件处理器
 *
 * 这是 file-handler 模块的核心函数，注册所有与文件操作相关的事件处理器：
 * - import：导入单个或多个文件
 * - scene.import：打开文件选择对话框导入
 * - scene.export：导出为指定格式
 * - scene.write：执行实际的序列化写入
 * - scene.openAnimation：打开文件夹作为动画序列
 * - scene.splats / scene.allSplats / scene.empty：场景状态查询
 *
 * @param scene - 场景对象
 * @param events - 事件系统
 * @param dropTarget - 文件拖放目标 DOM 元素
 */
// initialize file handler events
const initFileHandler = (scene: Scene, events: Events, dropTarget: HTMLElement) => {

    /**
     * 显示加载错误弹窗
     * @param message - 错误消息
     * @param filename - 出错的文件名
     */
    const showLoadError = async (message: string, filename: string) => {
        await events.invoke('showPopup', {
            type: 'error',
            header: '加载文件错误',
            message: `${message} while loading '${filename}'`
        });
    };

    /**
     * 导入单个 Splat 模型
     *
     * 处理流程：
     * 1. 确定主文件（SOG 的 meta.json、LCC 的 .lcc 文件、或单文件）
     * 2. 构建文件系统（MappedReadFileSystem），合并本地文件和 URL 引用
     * 3. 通过 assetLoader 加载并添加到场景
     *
     * @param files - 要导入的文件列表
     * @param animationFrame - 是否为动画帧加载（跳过排序优化）
     * @returns 加载的 Splat 模型，失败时返回 undefined
     */
    // import splat model(s) - handles single files, SOG, and LCC formats
    const importSplatModel = async (files: ImportFile[], animationFrame: boolean) => {
        try {
            const filenames = files.map(f => f.filename.toLowerCase());

            // 根据格式确定主文件索引
            // Determine the main file based on format
            let mainIndex: number;
            if (filenames.some(f => f === 'meta.json')) {
                mainIndex = filenames.findIndex(f => f === 'meta.json');
            } else if (filenames.some(f => f.endsWith('.lcc'))) {
                mainIndex = filenames.findIndex(f => f.endsWith('.lcc'));
            } else {
                mainIndex = 0;  // 单文件情况
            }

            const mainFile = files[mainIndex];
            // 计算基础 URL（用于解析相对路径引用）
            const baseUrl = mainFile.url ? new URL('.', new URL(mainFile.url, window.location.href)).href : undefined;

            // 创建文件系统，优先使用本地文件内容，否则通过 URL 加载
            // Create file system with all local files, falling back to URL loading
            const fileSystem = new MappedReadFileSystem(baseUrl);

            // 处理所有文件：本地文件直接添加，URL 文件查缓存后添加
            for (const f of files) {
                if (f.contents) {
                    fileSystem.addFile(f.filename, f.contents);
                } else if (f.url) {
                    let cached = await splatCache.get(f.filename);
                    if (!cached) {
                        const response = await fetch(f.url);
                        if (!response.ok) {
                            throw new Error(`下载失败: HTTP ${response.status} ${response.statusText}`);
                        }
                        cached = await response.arrayBuffer();
                        try {
                            await splatCache.set(f.filename, f.url, cached);
                        } catch (err) {
                            console.warn(`[SplatCache] 缓存写入失败，继续使用下载数据: ${f.filename}`, err);
                        }
                    }
                    fileSystem.addFile(f.filename, new Blob([cached]));
                }
            }

            // 确定显示用的文件名：URL 单文件用完整 URL，否则用本地文件名
            // For URL-only single file, use full URL as filename
            const filename = (files.length === 1 && !mainFile.contents && mainFile.url) ?
                mainFile.url :
                mainFile.filename;

            const model = await scene.assetLoader.load(filename, fileSystem, animationFrame);
            await scene.add(model);
            return model;
        } catch (error) {
            const displayName = files[0]?.filename ?? 'unknown';
            await showLoadError(error.message ?? error, displayName);
        }
    };

    /**
     * 导入文件的主入口函数
     *
     * 根据文件类型分发到不同的处理逻辑：
     * - PLY 序列 → 设置为动画帧序列
     * - SOG/LCC 场景 → 作为多文件场景加载
     * - 单文件 PLY/SPLAT/SOG/KSplat/SPZ → 加载为单个高斯泼溅模型
     * - images.txt → 加载 COLMAP 相机位姿
     * - .json → 加载 INRIA 相机位姿
     * - .ssproj → 加载项目文档
     *
     * @param files - 导入的文件列表
     * @param animationFrame - 是否为动画帧
     * @returns 导入的 Splat 模型数组
     */
    // figure out what the set of files are (ply sequence, document, sog set, ply) and then import them
    const importFiles = async (files: ImportFile[], animationFrame = false) => {
        const filenames = files.map(f => f.filename.toLowerCase());

        const result: Splat[] = [];

        if (isPlySequence(filenames)) {
            // 处理 PLY 序列：设置为时间轴动画帧
            // handle ply sequence
            events.fire('plysequence.setFrames', files.map(f => f.contents));
            events.fire('timeline.frame', 0);
        } else if (isSog(filenames) || isLcc(filenames)) {
            // 处理多文件场景格式（SOG 或 LCC）
            if (isLcc(filenames)) {
                // LCC 格式需要用户确认上传
                const response = await events.invoke('showPopup', {
                    type: 'okcancel',
                    header: 'LCC',
                    message: '为了更好地发布到 superspl.at，请通过上传页面直接上传您的 LCC 文件。',
                    link: `${window.location.origin}/upload`
                });
                if (response.action === 'cancel') {
                    return result;
                }
            }
            const model = await importSplatModel(files, animationFrame);
            if (model) result.push(model);
        } else {
            // 处理其他单文件类型
            // 先检查是否有无法识别的文件类型
            // check for unrecognized file types
            for (let i = 0; i < filenames.length; i++) {
                const filename = filenames[i].toLowerCase();
                if (['.ssproj', '.ply', '.splat', '.sog', '.webp', 'images.txt', '.json', '.ksplat', '.spz', '.las', '.laz'].every(ext => !filename.endsWith(ext))) {
                    await showLoadError('Unrecognized file type', filename);
                    return;
                }
            }

            // 逐个处理文件
            // handle multiple files as independent imports
            for (let i = 0; i < files.length; i++) {
                const filename = filenames[i].toLowerCase();

                if (filename.endsWith('.ssproj')) {
                    // 加载 SuperSplat 项目文档 (.ssproj)
                    // load ssproj document
                    await events.invoke('doc.load', files[i].contents ?? (await fetch(files[i].url)).arrayBuffer(), files[i].handle);
                } else if (filename.endsWith('.las') || filename.endsWith('.laz')) {
                    // 加载 LAS/LAZ 点云文件（解码直写 GPU，零中间对象）
                    const displayName = files[i].filename;
                    events.fire('progressStart', `加载点云: ${displayName}`);
                    try {
                        let blob: Blob;
                        if (files[i].contents) {
                            blob = files[i].contents as unknown as Blob;
                        } else if (files[i].url) {
                            const cacheKey = files[i].filename;
                            const cached = await splatCache.get(cacheKey);
                            if (cached) {
                                blob = new Blob([cached]);
                            } else {
                                events.fire('progressUpdate', { text: '下载中...' });
                                const response = await fetch(files[i].url);
                                if (!response.ok) {
                                    throw new Error(`下载失败: HTTP ${response.status}`);
                                }
                                const arrayBuf = await response.arrayBuffer();
                                if (arrayBuf.byteLength <= 500 * 1024 * 1024) {
                                    try {
                                        await splatCache.set(cacheKey, files[i].url, arrayBuf);
                                    } catch (err) {
                                        console.warn(`[SplatCache] 缓存写入失败: ${cacheKey}`, err);
                                    }
                                }
                                blob = new Blob([arrayBuf]);
                            }
                        } else {
                            continue;
                        }
                        const pc = await PointCloud.fromLasFile(blob, scene.app.graphicsDevice, scene.gizmoLayer.id, (pct, current, total) => {
                            events.fire('progressUpdate', { progress: pct * 100, text: `解码: ${current.toLocaleString()} / ${total.toLocaleString()} 点` });
                        });
                        await scene.add(pc);
                        const bound = pc.boundStorage;
                        const radius = bound.halfExtents.length();
                        scene.camera.focus({
                            focalPoint: bound.center.clone(),
                            radius,
                            speed: 0
                        });
                        console.log(`[LAS] ${files[i].filename}: ${pc.numPoints.toLocaleString()} 个点已加载`);
                    } catch (err) {
                        console.error(`加载 LAS 失败: ${files[i].filename}`, err);
                        await showLoadError(err.message ?? err, files[i].filename);
                    } finally {
                        events.fire('progressEnd');
                    }
                } else if (['.ply', '.splat', '.sog', '.ksplat', '.spz'].some(ext => filename.endsWith(ext))) {
                    // 加载高斯泼溅模型（支持多种格式）
                    // load gaussian splat model
                    const model = await importSplatModel([files[i]], animationFrame);
                    if (model) result.push(model);
                } else if (filename.endsWith('images.txt')) {
                    // 加载 COLMAP 相机位姿
                    // load colmap frames
                    await loadImagesTxt(files[i], events);
                } else if (filename.endsWith('.json')) {
                    // 加载 INRIA 相机位姿
                    // load inria camera poses
                    await loadCameraPoses(files[i], events);
                }
            }
        }

        return result;
    };

    // 注册 import 函数到事件系统，供其他模块调用
    events.function('import', (files: ImportFile[], animationFrame = false) => {
        return importFiles(files, animationFrame);
    });

    /**
     * 创建降级文件选择器（当 showOpenFilePicker 不可用时）
     * 使用传统的 <input type="file"> 元素作为替代方案
     */
    // create a file selector element as fallback when showOpenFilePicker isn't available
    let fileSelector: HTMLInputElement;
    if (!window.showOpenFilePicker) {
        fileSelector = document.createElement('input');
        fileSelector.setAttribute('id', 'file-selector');
        fileSelector.setAttribute('type', 'file');
        // 设置接受的文件类型列表（包含所有支持的格式）
        fileSelector.setAttribute('accept', '.ply,.splat,meta.json,.json,.webp,.ssproj,.sog,.lcc,.bin,.txt,.ksplat,.spz');
        fileSelector.setAttribute('multiple', 'true');

        fileSelector.onchange = () => {
            const files = [];
            for (let i = 0; i < fileSelector.files.length; i++) {
                const file = fileSelector.files[i];
                files.push({
                    filename: file.name,
                    contents: file
                });
            }
            importFiles(files).catch(err => console.error('文件加载失败:', err));
            fileSelector.value = '';
        };
        document.body.append(fileSelector);
    }

    /**
     * 创建文件拖放处理器
     * 将拖入的文件转换为 ImportFile 格式后调用 importFiles
     */
    // create the file drag & drop handler
    CreateDropHandler(dropTarget, (entries, shift) => {
        importFiles(entries.map((e) => {
            return {
                filename: e.filename,
                contents: e.file,
                handle: e.handle
            };
        })).catch(err => console.error('拖放文件加载失败:', err));
    });

    /**
     * 获取场景中所有可见且包含高斯点的 Splat 元素
     * 用于导出功能——只导出用户可见的有效 splat
     */
    // get the list of visible splats containing gaussians
    const getSplats = () => {
        return (scene.getElementsByType(ElementType.splat) as Splat[])
        .filter(splat => splat.visible)
        .filter(splat => splat.numSplats > 0);
    };

    // 注册场景查询函数：获取所有 Splat（包括不可见的）
    events.function('scene.allSplats', () => {
        return (scene.getElementsByType(ElementType.splat) as Splat[]);
    });

    // 注册场景查询函数：获取可见的 Splat
    events.function('scene.splats', () => {
        return getSplats();
    });

    // 注册场景查询函数：判断场景是否为空
    events.function('scene.empty', () => {
        return getSplats().length === 0;
    });

    /**
     * 场景导入命令：打开文件选择对话框
     * 优先使用 File System Access API，降级到传统文件选择器
     */
    events.function('scene.import', async () => {
        if (fileSelector) {
            // 使用降级的 <input> 文件选择器
            fileSelector.click();
        } else {
            try {
                // 使用现代 File System Access API
                const handles = await window.showOpenFilePicker({
                    id: 'SuperSplatFileImport',
                    multiple: true,
                    excludeAcceptAllOption: false,
                    types: [
                        allImportTypes,           // 所有支持的文件
                        filePickerTypes.ply,
                        filePickerTypes.compressedPly,
                        filePickerTypes.splat,
                        filePickerTypes.sog,
                        filePickerTypes.lcc,
                        filePickerTypes.ksplat,
                        filePickerTypes.spz,
                        filePickerTypes.indexTxt
                    ]
                });

                const files = [];
                for (let i = 0; i < handles.length; i++) {
                    files.push({
                        filename: handles[i].name,
                        contents: await handles[i].getFile()
                    });
                }

                await importFiles(files);

            } catch (error) {
                // AbortError 是用户取消选择，不需要处理
                if (error.name !== 'AbortError') {
                    console.error(error);
                }
            }
        }
    });

    /**
     * 打开文件夹作为动画序列
     * 使用 showDirectoryPicker API 选择包含 PLY 帧的文件夹
     * 自动过滤出所有 .ply 文件并按帧加载
     */
    // open a folder
    events.function('scene.openAnimation', async () => {
        try {
            const handle = await window.showDirectoryPicker({
                id: 'SuperSplatFileOpenAnimation',
                mode: 'readwrite'
            });

            if (handle) {
                const files = [];
                // 遍历文件夹中的所有条目，收集 .ply 文件
                for await (const value of handle.values()) {
                    if (value.kind === 'file') {
                        const file = await value.getFile();
                        if (file.name.toLowerCase().endsWith('.ply')) {
                            files.push(file);
                        }
                    }
                }
                // 设置为 PLY 序列并跳转到第0帧
                events.fire('plysequence.setFrames', files);
                events.fire('timeline.frame', 0);
            }
        } catch (error) {
            if (error.name !== 'AbortError') {
                console.error(error);
            }
        }
    });

    /**
     * 场景导出命令：弹出导出设置对话框，然后执行实际导出
     *
     * 流程：
     * 1. 获取当前可见的 splat 列表
     * 2. 显示导出设置弹窗，让用户选择导出选项
     * 3. 根据选择生成对应的文件
     *
     * @param exportType - 导出格式类型
     */
    events.function('scene.export', async (exportType: ExportType) => {
        const splats = getSplats();

        const hasFilePicker = !!window.showSaveFilePicker;

        // 显示导出设置弹窗，收集用户的导出选项
        // show viewer export options
        const options = await events.invoke('show.exportPopup', exportType, splats.map(s => s.name), !hasFilePicker) as SceneExportOptions;

        // 用户取消导出
        // return if user cancelled
        if (!options) {
            return;
        }

        // 根据导出类型和用户选项确定内部文件类型标识
        const fileType: FileType =
            (exportType === 'viewer') ? (options.viewerExportSettings!.type === 'zip' ? 'packageViewer' : 'htmlViewer') :
                (exportType === 'ply') ? (options.compressedPly ? 'compressedPly' : 'ply') :
                    (exportType === 'sog') ? 'sog' : 'splat';

        if (hasFilePicker) {
            try {
                // 使用 File System Access API 的保存对话框
                const fileHandle = await window.showSaveFilePicker({
                    id: 'SuperSplatFileExport',
                    types: [filePickerTypes[fileType]],
                    suggestedName: options.filename
                });
                // 通过可写流写入文件
                await events.invoke('scene.write', fileType, options, await fileHandle.createWritable());
            } catch (error) {
                if (error.name !== 'AbortError') {
                    console.error(error);
                }
            }
        } else {
            // 降级方案：不使用 File System Access API，通过浏览器下载
            await events.invoke('scene.write', fileType, options);
        }
    });

    /**
     * 执行文件写入操作
     *
     * 根据 fileType 选择不同的序列化方法：
     * - ply / compressedPly → serializePly / serializePlyCompressed
     * - splat → serializeSplat（优化的二进制格式）
     * - sog → serializeSog（需要多次迭代优化）
     * - htmlViewer / packageViewer → serializeViewer（独立查看器）
     *
     * @param fileType - 文件类型
     * @param options - 导出选项
     * @param stream - 可写文件流（File System Access API），不提供时使用浏览器下载
     */
    events.function('scene.write', async (fileType: FileType, options: SceneExportOptions, stream?: FileSystemWritableFileStream) => {
        // SOG 和 viewer 导出有自己的进度 UI，其他格式使用加载旋转器
        // SOG and viewer exports have their own progress UI, other formats use spinner
        const useSpinner = fileType !== 'sog' && fileType !== 'htmlViewer' && fileType !== 'packageViewer';

        if (useSpinner) {
            events.fire('startSpinner');
        }

        try {
            // setTimeout 让 UI（旋转器/进度条）有机会激活显示
            // setTimeout so spinner/progress has a chance to activate
            await new Promise<void>((resolve) => {
                setTimeout(resolve);
            });

            const { filename, splatIdx, serializeSettings, viewerExportSettings } = options;

            // 创建浏览器文件系统用于输出（支持可写流或回退到下载）
            // Create FileSystem for output
            const fs = new BrowserFileSystem(filename, stream);

            // 确定要导出的 splat 列表
            const splats = splatIdx === 'all' ? getSplats() : [getSplats()[splatIdx]];

            switch (fileType) {
                case 'ply':
                    // 标准 PLY 格式导出
                    await serializePly(splats, serializeSettings, fs);
                    break;
                case 'compressedPly':
                    // 压缩 PLY：设置最小不透明度阈值，移除无效高斯点
                    serializeSettings.minOpacity = 1 / 255;
                    serializeSettings.removeInvalid = true;
                    await serializePlyCompressed(splats, serializeSettings, fs);
                    break;
                case 'splat':
                    // 优化的 .splat 二进制格式
                    await serializeSplat(splats, serializeSettings, fs);
                    break;
                case 'sog': {
                    // SOG 格式：需要进行迭代优化
                    const sogSettings: SogSettings = {
                        ...serializeSettings,
                        minOpacity: 1 / 255,
                        removeInvalid: true,
                        iterations: options.sogIterations ?? 10,
                        events
                    };
                    await serializeSog(splats, sogSettings, fs);
                    break;
                }
                case 'htmlViewer':
                case 'packageViewer':
                    // 独立查看器（HTML 或 ZIP 包）
                    await serializeViewer(splats, serializeSettings, { ...viewerExportSettings!, events }, fs);
                    break;
            }

        } catch (error) {
            await events.invoke('showPopup', {
                type: 'error',
                header: '加载文件错误',
                message: `${error.message ?? error} while saving file`
            });
        } finally {
            if (useSpinner) {
                events.fire('stopSpinner');
            }
        }
    });

    /**
     * URL 导入 LAS 点云
     */
    const importUrl = async () => {
        const url = prompt('输入 LAS/LAZ 文件地址：');
        if (!url) return;

        const filename = url.split('/').pop() || 'imported.las';
        events.fire('progressStart', `加载点云: ${filename}`);
        events.fire('startSpinner');
        try {

            let arrayBuf: ArrayBuffer;
            const cached = await splatCache.get(filename);
            if (cached) {
                arrayBuf = cached;
            } else {
                events.fire('progressUpdate', { text: '下载中...' });
                const response = await fetch(url);
                if (!response.ok) throw new Error(`HTTP ${response.status}`);
                arrayBuf = await response.arrayBuffer();
                try {
                    await splatCache.set(filename, url, arrayBuf);
                } catch (err) {
                    console.warn(`[SplatCache] 缓存写入失败，继续使用下载数据: ${filename}`, err);
                }
            }

            const blob = new Blob([arrayBuf]);
            const pc = await PointCloud.fromLasFile(blob, scene.app.graphicsDevice, scene.gizmoLayer.id, (pct, current, total) => {
                events.fire('progressUpdate', { progress: pct * 100, text: `解码: ${current.toLocaleString()} / ${total.toLocaleString()} 点` });
            });
            await scene.add(pc);
            const bound = pc.boundStorage;
            const radius = bound.halfExtents.length();
            scene.camera.focus({ focalPoint: bound.center.clone(), radius, speed: 0 });
            console.log(`[LAS] ${filename}: ${pc.numPoints.toLocaleString()} 个点已加载`);
        } catch (err) {
            await events.invoke('showPopup', {
                type: 'error',
                header: 'LAS 导入失败',
                message: (err as Error).message || String(err)
            });
        } finally {
            events.fire('progressEnd');
            events.fire('stopSpinner');
        }
    };

    events.function('scene.importUrl', importUrl);
    events.on('scene.importUrl', importUrl);
};

export { initFileHandler, ExportType, SceneExportOptions };
