import { Color, Vec3 } from 'playcanvas';

import { Scene } from '../scene';
import { Splat } from '../splat';
import { State } from '../splat-state';

// ============================================================
// 持久化标注（切换工具后矩形不消失）
// ============================================================

interface PersistentAnnotation {
  rect: Rect;
}

const persistentAnnotations: PersistentAnnotation[] = [];
let _persistentScene: Scene | null = null;

function ensurePersistentRendering(scene: Scene) {
    if (_persistentScene) return;
    _persistentScene = scene;
    scene.app.on('prerender', () => {
        for (const anno of persistentAnnotations) {
            const { corners, center, normal, uAxis, vAxis, halfWidth, halfHeight } =
        anno.rect;

            // 实线边框
            const outline = [
                corners[0],
                corners[1],
                corners[1],
                corners[2],
                corners[2],
                corners[3],
                corners[3],
                corners[0]
            ];
            scene.app.drawLines(outline, Color.GREEN, true, scene.worldLayer);

            // 半透明填充（平行线排线模拟）
            const fillColor = new Color(0, 0.85, 0, 0.12);
            const hatchSpacing = 0.04;
            const tempA = new Vec3();
            const tempB = new Vec3();
            for (let u = -halfWidth; u <= halfWidth + 0.001; u += hatchSpacing) {
                tempA
                .copy(center)
                .addScaled(uAxis, Math.min(u, halfWidth))
                .addScaled(vAxis, -halfHeight);
                tempB
                .copy(center)
                .addScaled(uAxis, Math.min(u, halfWidth))
                .addScaled(vAxis, halfHeight);
                scene.app.drawLines([tempA, tempB], fillColor, true, scene.worldLayer);
            }
        }
    });
}

// ============================================================
// 数据结构定义
// ============================================================

/**
 * 单个邻域高斯点的信息
 * 代表命中点附近的一个高斯椭球体，包含位置、缩放、透明度等属性
 */
interface NearPoint {
  /** splatData 中的原始索引（用于后续回溯到具体的高斯点） */
  index: number;
  /** 世界空间坐标（经 entity.worldTransform 变换后的最终位置） */
  worldPos: Vec3;
  /** 局部空间坐标（PLY 文件中存储的原始 x, y, z 值） */
  localPos: Vec3;
  /** 平均缩放值 = (exp(scale_0) + exp(scale_1) + exp(scale_2)) / 3 */
  scale: number;
  /** 不透明度 0~1（经 sigmoid 函数转换后的值） */
  opacity: number;
  /** 到命中点的欧氏距离（米） */
  distanceToHit: number;
  /** Gaussian normal direction (world-space), from rotation quat + min scale axis */
  normal?: Vec3;
}

/**
 * 采样结果
 * 包含邻域点数组和本次采样的统计信息
 */
interface SampleResult {
  /** 按距离升序排列的邻域点数组（最多 maxPoints 个） */
  nearPoints: NearPoint[];
  /** 命中点的世界坐标（射线与高斯模型的交点） */
  hitWorldPos: Vec3;
  /** 当前 splat 中高斯点的总数量 */
  totalSplats: number;
  /** 最终使用的搜索半径（可能经过自适应翻倍） */
  searchRadius: number;
  /** 采样统计信息 */
  sampleStats: {
    /** 半径内的原始命中数量（截断前） */
    rawCount: number;
    /** 截断后的最终点数 */
    finalCount: number;
    /** 稀疏度判定：dense(>100点) / normal(10~100点) / sparse(<10点) */
    sparsityLevel: 'dense' | 'normal' | 'sparse';
    /** 是否触发了半径翻倍重试 */
    radiusRetried: boolean;
  };
}

/**
 * 采样器配置参数
 */
interface HitSamplerConfig {
  /** 初始搜索半径（米），默认 0.3 */
  initialRadius: number;
  /** 最少采样点数，低于此值会触发半径翻倍，默认 10 */
  minPoints: number;
  /** 最多保留的采样点数，超出则截断，默认 500 */
  maxPoints: number;
  /** 半径翻倍的最大重试次数，默认 2（即最大半径 = initialRadius * 4） */
  maxRadiusRetries: number;
  /** 不透明度过滤阈值，低于此值的高斯点被忽略，默认 0.05 */
  opacityThreshold: number;
}

/**
 * 拟合平面
 * 由法向量、中心点、平面常量 d 定义，满足 normal·P + d = 0
 */
interface Plane {
  /** 单位法向量（指向平面的法向方向） */
  normal: Vec3;
  /** 质心点（邻域点的几何中心，位于平面上） */
  center: Vec3;
  /** 平面方程常量，满足 normal·P + d = 0，即 d = -normal·center */
  d: number;
}

/**
 * 平面估计结果
 */
interface PlaneEstimationResult {
  /** 拟合的平面 */
  plane: Plane;
  /** 平均残差 —— 所有点到拟合平面的平均距离，越小越好 */
  averageResidual: number;
  /** 最大残差 —— 到平面最远的点的距离 */
  maxResidual: number;
  /** 参与计算的点数量 */
  pointCount: number;
}

/**
 * 拟合矩形
 * 在平面上根据点的分布范围推算出的最优有向包围盒
 */
interface Rect {
  /** 矩形中心点（在拟合平面上） */
  center: Vec3;
  /** 法向量（与平面法向一致） */
  normal: Vec3;
  /** U 轴方向（长边方向，单位向量） */
  uAxis: Vec3;
  /** V 轴方向（短边方向，单位向量，正交于 uAxis 和 normal） */
  vAxis: Vec3;
  /** 沿 U 轴方向的半宽 */
  halfWidth: number;
  /** 沿 V 轴方向的半宽 */
  halfHeight: number;
  /** 四个角点 [左下, 右下, 右上, 左上]（按 U-V 象限排列） */
  corners: Vec3[];
}

// ============================================================
// 默认配置
// ============================================================

const defaultConfig: HitSamplerConfig = {
    initialRadius: 0.3,
    minPoints: 10,
    maxPoints: 500,
    maxRadiusRetries: 2,
    opacityThreshold: 0.05
};

// ============================================================
// 工具函数
// ============================================================

/**
 * sigmoid 激活函数
 * PLY 文件中的 opacity 以 logit 形式存储（sigmoid 的逆），
 * 需要经过 sigmoid 转换才能得到 0~1 范围的真实不透明度
 */
const sigmoid = (x: number) => 1 / (1 + Math.exp(-x));

// ============================================================
// 核心采样函数
// ============================================================

/**
 * 命中采样器：以命中点为中心，搜索半径 R 内的所有高斯点
 *
 * 算法流程：
 * 1. 读取 splatData 中的各属性数组（x/y/z/scale/opacity/state）
 * 2. 遍历所有高斯点，跳过已删除/锁定/过于透明的点
 * 3. 将每个点的局部坐标通过 worldTransform 变换为世界坐标
 * 4. 计算到命中点的距离平方（避免开根号，提升性能）
 * 5. 距离在半径 R 内的点加入结果集
 * 6. 若点数不足 minPoints，半径翻倍重试（最多 maxRadiusRetries 次）
 * 7. 按距离升序排序，截断到 maxPoints 个
 *
 * @param splat - 被命中的 Splat 对象
 * @param hitWorldPos - 命中点的世界坐标（来自 camera.intersect）
 * @param config - 可选的配置参数覆盖
 * @returns 采样结果，包含邻域点数组和统计信息；数据无效时返回 null
 */
function sample(
    splat: Splat,
    hitWorldPos: Vec3,
    config: Partial<HitSamplerConfig> = {}
): SampleResult | null {
    // 合并用户配置与默认配置
    const cfg = { ...defaultConfig, ...config };

    const splatData = splat.splatData;
    const N = splatData.numSplats;
    if (N === 0) return null;

    // ---- 获取属性数组 ----
    // state: 每个高斯点的状态标记（selected=1, locked=2, deleted=4）
    const state = splatData.getProp('state') as Uint8Array | undefined;
    // opacity: sigmoid 前的原始值（logit 空间）
    const opacityData = splatData.getProp('opacity') as Float32Array | undefined;
    // scale_0/1/2: 对数空间的缩放值，需要 exp() 转换为实际缩放
    const sx = splatData.getProp('scale_0') as Float32Array | undefined;
    const sy = splatData.getProp('scale_1') as Float32Array | undefined;
    const sz = splatData.getProp('scale_2') as Float32Array | undefined;
    const rot0 = splatData.getProp('rot_0') as Float32Array | undefined;
    const rot1 = splatData.getProp('rot_1') as Float32Array | undefined;
    const rot2 = splatData.getProp('rot_2') as Float32Array | undefined;
    const rot3 = splatData.getProp('rot_3') as Float32Array | undefined;
    // x/y/z: 高斯点在局部空间的位置坐标
    const xArr = splatData.getProp('x') as Float32Array;
    const yArr = splatData.getProp('y') as Float32Array;
    const zArr = splatData.getProp('z') as Float32Array;

    // x/y/z 是必需属性，缺失则无法计算
    if (!xArr || !yArr || !zArr) return null;

    // 获取实体的世界变换矩阵（用于将局部坐标转为世界坐标）
    const worldTransform = splat.worldTransform;
    // 临时向量，避免在循环中反复 new（性能优化）
    const tempLocal = new Vec3();
    const tempWorld = new Vec3();

    let points: NearPoint[] = [];
    let R = cfg.initialRadius;
    let retries = 0;
    let radiusRetried = false;

    // ---- 自适应半径搜索循环 ----
    // 如果当前半径内找到的点不足 minPoints，则将半径翻倍重试
    while (true) {
        points = [];
        const RSq = R * R; // 预计算半径平方，避免在距离比较时开根号

        for (let i = 0; i < N; i++) {
            // 跳过已删除或已锁定的高斯点
            if (state && state[i] & (State.deleted | State.locked)) continue;

            // 跳过不透明度过低的高斯点（几乎透明，对平面拟合无贡献）
            if (opacityData) {
                const op = sigmoid(opacityData[i]);
                if (op < cfg.opacityThreshold) continue;
            }

            // 将局部坐标转换为世界坐标
            tempLocal.set(xArr[i], yArr[i], zArr[i]);
            worldTransform.transformPoint(tempLocal, tempWorld);

            // 计算到命中点的距离平方（欧氏距离的平方，避免 sqrt 开销）
            const dx = tempWorld.x - hitWorldPos.x;
            const dy = tempWorld.y - hitWorldPos.y;
            const dz = tempWorld.z - hitWorldPos.z;
            const distSq = dx * dx + dy * dy + dz * dz;

            // 距离平方比较：distSq <= R² 等价于 dist <= R
            if (distSq <= RSq) {
                const dist = Math.sqrt(distSq);
                // 计算平均缩放值：scale 存储在对数空间，需要 exp 转换
                const avgScale =
          sx && sy && sz ?
              (Math.exp(sx[i]) + Math.exp(sy[i]) + Math.exp(sz[i])) / 3 :
              1.0;
                const opacity = opacityData ? sigmoid(opacityData[i]) : 1.0;

                
                // Compute Gaussian local normal from rotation quat + smallest scale axis
                var _lclN = new Vec3(0, 0, 1);
                if (rot0 && rot1 && rot2 && rot3 && sx && sy && sz) {
                    var qx = rot0[i], qy = rot1[i], qz = rot2[i], qw = rot3[i];
                    var c0x = 1 - 2*(qy*qy + qz*qz), c0y = 2*(qx*qy + qw*qz), c0z = 2*(qx*qz - qw*qy);
                    var c1x = 2*(qx*qy - qw*qz), c1y = 1 - 2*(qx*qx + qz*qz), c1z = 2*(qy*qz + qw*qx);
                    var c2x = 2*(qx*qz + qw*qy), c2y = 2*(qy*qz - qw*qx), c2z = 1 - 2*(qx*qx + qy*qy);
                    var _s0 = Math.exp(sx[i]), _s1 = Math.exp(sy[i]), _s2 = Math.exp(sz[i]);
                    if (_s0 <= _s1 && _s0 <= _s2)      _lclN.set(c0x, c0y, c0z);
                    else if (_s1 <= _s0 && _s1 <= _s2) _lclN.set(c1x, c1y, c1z);
                    else                               _lclN.set(c2x, c2y, c2z);
                }
                // Transform to world space (rotation only, no translation)
                var worldNormal = new Vec3();
                worldTransform.transformVector(_lclN, worldNormal);
                worldNormal.normalize();
                points.push({
                    index: i,
                    worldPos: tempWorld.clone(),
                    localPos: tempLocal.clone(),
                    scale: avgScale,
                    opacity: opacity,
                    distanceToHit: dist,
                    normal: worldNormal
                });
            }
        }

        // 点数满足最低要求，退出搜索循环
        if (points.length >= cfg.minPoints) break;
        // 已达最大重试次数，退出（可能是极稀疏区域）
        if (retries >= cfg.maxRadiusRetries) break;
        // 半径翻倍，继续搜索
        R *= 2;
        retries++;
        radiusRetried = true;
    }

    // ---- 排序 + 截断 ----
    // 按到命中点的距离升序排列，确保最近的点排在前面
    points.sort((a, b) => a.distanceToHit - b.distanceToHit);
    const rawCount = points.length;
    // 超过最大点数限制时，只保留最近的 maxPoints 个
    if (points.length > cfg.maxPoints) {
        points = points.slice(0, cfg.maxPoints);
    }

    // ---- 稀疏度判定 ----
    let sparsityLevel: 'dense' | 'normal' | 'sparse';
    if (points.length < cfg.minPoints) sparsityLevel = 'sparse';
    else if (points.length > 100) sparsityLevel = 'dense';
    else sparsityLevel = 'normal';

    return {
        nearPoints: points,
        hitWorldPos: hitWorldPos.clone(),
        totalSplats: N,
        searchRadius: R,
        sampleStats: {
            rawCount,
            finalCount: points.length,
            sparsityLevel,
            radiusRetried
        }
    };
}

// ============================================================
// 3×3 对称矩阵特征值分解（Cardano 闭式解）
// ============================================================

/**
 * 3×3 对称矩阵的特征值分解结果
 */
interface EigenDecomposition {
  /** 三个特征值，从大到小排序 */
  eigenvalues: number[];
  /** 三个特征向量，按列排列，一一对应特征值 */
  eigenvectors: Vec3[];
}

/**
 * 求解 3×3 实对称矩阵的特征值与特征向量
 *
 * 实对称矩阵保证有三个实特征值，可通过 Cardano 公式直接解三次特征方程，
 * 无需迭代算法（如 Jacobi / QR）。对于 3×3 这种小规模问题，
 * 闭式解比迭代法更快、更稳定。
 *
 * 算法流程：
 *   1. 构造特征方程 det(M - λI) = 0 → λ³ + a₂λ² + a₁λ + a₀ = 0
 *   2. 通过变量替换 λ = t - a₂/3 化为亏缺三次方程 t³ + pt + q = 0
 *   3. 用三角函数法（Vieta 公式）求解三个实根
 *   4. 对每个特征值，解 (M - λI)v = 0 得到特征向量，正交化后归一化
 *
 * @param m - 3×3 对称矩阵，以 9 元素数组 [(0,0),(0,1),(0,2), (1,0)...] 行主序传入
 * @returns 特征值分解结果
 */
function eigendecomposeSymmetric3x3(m: number[]): EigenDecomposition {
    // ======== 第 1 步：计算特征多项式系数 ========
    // 矩阵形式: [m0 m1 m2; m1 m3 m4; m2 m4 m5]
    const [m00, m01, m02, m11, m12, m22] = [m[0], m[1], m[2], m[4], m[5], m[8]];

    // 特征多项式: λ³ + a₂λ² + a₁λ + a₀ = 0
    // a₂ = -trace(M)
    const a2 = -(m00 + m11 + m22);
    // a₁ = Σ 二阶主子式（对角线上的 2×2 子矩阵行列式之和）
    const a1 =
    m00 * m11 - m01 * m01 + (m00 * m22 - m02 * m02) + (m11 * m22 - m12 * m12);
    // a₀ = -det(M)
    const a0 = -(
        m00 * (m11 * m22 - m12 * m12) -
    m01 * (m01 * m22 - m12 * m02) +
    m02 * (m01 * m12 - m11 * m02)
    );

    // ======== 第 2 步：化为亏缺三次方程 t³ + p·t + q = 0 ========
    const a2Over3 = a2 / 3;
    // p = a₁ - a₂²/3
    const p = a1 - a2 * a2Over3;
    // q = a₀ - a₁·a₂/3 + 2·a₂³/27
    const q = a0 - a1 * a2Over3 + 2 * a2Over3 * a2Over3 * a2Over3;

    // ======== 第 3 步：三角函数法求解三个实根 ========
    // 当 p >= 0 时矩阵退化为零协方差等情况，三个特征值相同
    const eps = 1e-12;
    let eigenvalues: number[];

    if (Math.abs(p) < eps) {
    // 三重根：λ = -a₂/3（即 -q^(1/3) - a₂/3）
        const root = -a2Over3;
        eigenvalues = [root, root, root];
    } else {
    // p < 0 时使用三角函数解
    // 根据 Vieta 公式：t_k = 2√(−p/3) · cos((φ + 2kπ) / 3),  k = 0,1,2
        const sqrtP3 = Math.sqrt(-p / 3);
        const phiArg = q / (2 * sqrtP3 * sqrtP3 * sqrtP3);
        const phi = Math.acos(Math.max(-1, Math.min(1, phiArg))) / 3;

        eigenvalues = [
            2 * sqrtP3 * Math.cos(phi) - a2Over3,
            2 * sqrtP3 * Math.cos(phi + (2 * Math.PI) / 3) - a2Over3,
            2 * sqrtP3 * Math.cos(phi + (4 * Math.PI) / 3) - a2Over3
        ];
    }

    // ======== 第 4 步：对每个特征值求特征向量 ========
    const eigenvectors: Vec3[] = [];

    for (let k = 0; k < 3; k++) {
        const λ = eigenvalues[k];

        const a = m00 - λ;
        const b = m11 - λ;
        const c = m22 - λ;

        const row0 = new Vec3(a, m01, m02);
        const row1 = new Vec3(m01, b, m12);
        const row2 = new Vec3(m02, m12, c);

        const cross01 = new Vec3().cross(row0, row1);
        const cross02 = new Vec3().cross(row0, row2);
        const cross12 = new Vec3().cross(row1, row2);

        let best = cross01;
        const l01 = cross01.lengthSq();
        const l02 = cross02.lengthSq();
        const l12 = cross12.lengthSq();
        if (l02 > l01 && l02 > l12) best = cross02;
        else if (l12 > l01) best = cross12;

        if (best.lengthSq() < eps) {
            // 退化情况：M - λI 的所有行线性相关（如等特征值情况）
            // 直接给一个单位向量，后续正交化会修正
            best.set(k === 0 ? 1 : 0, k === 1 ? 1 : 0, k === 2 ? 1 : 0);
        } else {
            best.normalize();
        }
        eigenvectors.push(best);
    }

    // ======== 第 5 步：特征值与特征向量配对排序 ========
    // 按特征值从大到小，特征向量同步重排
    const pairs = eigenvalues.map((v, i) => ({
        value: v,
        vector: eigenvectors[i]
    }));
    pairs.sort((a, b) => b.value - a.value);

    const sortedEigenvalues = pairs.map(p => p.value);
    const sortedEigenvectors = pairs.map(p => p.vector);

    // ======== 第 6 步：正交化（修正数值误差） ========
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < i; j++) {
            const dot = sortedEigenvectors[i].dot(sortedEigenvectors[j]);
            const tmp = sortedEigenvectors[j].clone().mulScalar(dot);
            sortedEigenvectors[i].sub(tmp);
        }
        const len = sortedEigenvectors[i].length();
        if (len > eps) {
            sortedEigenvectors[i].mulScalar(1 / len);
        }
    }

    return { eigenvalues: sortedEigenvalues, eigenvectors: sortedEigenvectors };
}

// ============================================================
// 平面估计器
// ============================================================

/**
 * 从邻域点云中通过 PCA（主成分分析）估计最佳拟合平面
 *
 * 核心直觉：
 *   点云沿平面法向方向的分布最"薄"（方差最小），
 *   协方差矩阵的最小特征值对应的特征向量即为平面法向。
 *
 * 算法步骤：
 *   1. 计算所有点的质心（算术平均）
 *   2. 构建 3×3 协方差矩阵 cov[j][k] = Σ(p[i][j]-c[j])(p[i][k]-c[k]) / n
 *   3. 对协方差矩阵做特征值分解
 *   4. 取最小特征值对应的特征向量作为法向 N
 *   5. 计算平面方程：d = -N·center
 *   6. 统计残差（各点到平面的平均距离 / 最大距离）
 *
 * @param nearPoints - 邻域点数组（来自 HitSampler.sample）
 * @returns 平面估计结果；点数不足 3 时返回 null
 */
function estimatePlane(nearPoints: NearPoint[]): PlaneEstimationResult | null {
    const n = nearPoints.length;
    if (n < 3) return null;

    // ---- 第 1 步：计算质心 ----
    const center = new Vec3(0, 0, 0);
    for (let i = 0; i < n; i++) {
        center.add(nearPoints[i].worldPos);
    }
    center.mulScalar(1 / n);

    // ---- 第 2 步：构建 3×3 协方差矩阵 ----
    // 协方差矩阵是对称矩阵，只需存 6 个独立分量
    // cov = [c00 c01 c02; c01 c11 c12; c02 c12 c22]
    let c00 = 0,
        c01 = 0,
        c02 = 0,
        c11 = 0,
        c12 = 0,
        c22 = 0;

    const temp = new Vec3();
    for (let i = 0; i < n; i++) {
    // 去质心后的偏移量
        temp.copy(nearPoints[i].worldPos).sub(center);
        const dx = temp.x;
        const dy = temp.y;
        const dz = temp.z;

        c00 += dx * dx;
        c01 += dx * dy;
        c02 += dx * dz;
        c11 += dy * dy;
        c12 += dy * dz;
        c22 += dz * dz;
    }

    // 除以 n 得到协方差
    c00 /= n;
    c01 /= n;
    c02 /= n;
    c11 /= n;
    c12 /= n;
    c22 /= n;

    // ---- 第 3 步：特征值分解 ----
    const covMat = [c00, c01, c02, c01, c11, c12, c02, c12, c22];
    const { eigenvalues, eigenvectors } = eigendecomposeSymmetric3x3(covMat);

    // ---- 第 4 步：最小特征值 → 法向 ----
    const normal = eigenvectors[2]; // 特征值升序 → 第 3 个（索引 2）是最小的

    // ---- 第 5 步：计算平面方程 d = -normal·center ----
    const d = -normal.dot(center);

    // ---- 第 6 步：统计残差 ----
    let totalResidual = 0;
    let maxResidual = 0;
    for (let i = 0; i < n; i++) {
    // 点到平面的符号距离 = normal·P + d
        const r = Math.abs(normal.dot(nearPoints[i].worldPos) + d);
        totalResidual += r;
        if (r > maxResidual) maxResidual = r;
    }
    const averageResidual = totalResidual / n;

    return {
        plane: {
            normal: normal.clone(),
            center: center.clone(),
            d
        },
        averageResidual,
        maxResidual,
        pointCount: n
    };
}

/**
 * 通过 RANSAC（随机采样一致性）鲁棒估计最佳拟合平面
 *
 * 与 PCA 的区别：PCA 对所有点一视同仁，离群点会拉偏平面；
 * RANSAC 通过随机采样投票，天然排除不在主平面上的离群点。
 *
 * 算法：
 *   1. 随机取 3 个点，用叉积计算平面法向
 *   2. 统计到平面距离 < threshold 的内点数
 *   3. 重复 maxIterations 次，保留内点最多的平面
 *   4. 用最终内点集做一次加权 PCA 精化
 *
 * @param nearPoints - 邻域点数组
 * @param maxIterations - 最大迭代次数，默认 150
 * @param distanceThreshold - 内点判定距离阈值（米），默认 0.02
 * @returns 平面估计结果；点数不足 3 时返回 null
 */
function estimatePlaneRANSAC(
    nearPoints: NearPoint[],
    maxIterations: number = 150,
    distanceThreshold: number = 0.02
): PlaneEstimationResult | null {
    const n = nearPoints.length;
    if (n < 3) return null;

    const weights = new Float64Array(n);
    const scales: number[] = [];
    for (let i = 0; i < n; i++) {
        scales.push(nearPoints[i].scale);
        weights[i] = 1.0;
    }
    scales.sort((a, b) => a - b);
    const medianScale = scales[Math.floor(n / 2)];

    for (let i = 0; i < n; i++) {
        const { scale, opacity } = nearPoints[i];
        if (opacity < 0.1) {
            weights[i] = 0;
        } else if (scale > medianScale * 3 || scale < medianScale / 3) {
            weights[i] = 0.1;
        }
    }

    let bestInlierMask: boolean[] = [];
    let bestPlaneD = 0;
    let bestInlierCount = 0;
    const bestPlaneNormal = new Vec3();

    const p1 = new Vec3();
    const p2 = new Vec3();
    const p3 = new Vec3();
    const v1 = new Vec3();
    const v2 = new Vec3();
    const normal = new Vec3();

    for (let iter = 0; iter < maxIterations; iter++) {
        const i1 = Math.floor(Math.random() * n);
        let i2 = Math.floor(Math.random() * n);
        while (i2 === i1) i2 = Math.floor(Math.random() * n);
        let i3 = Math.floor(Math.random() * n);
        while (i3 === i1 || i3 === i2) i3 = Math.floor(Math.random() * n);

        p1.copy(nearPoints[i1].worldPos);
        p2.copy(nearPoints[i2].worldPos);
        p3.copy(nearPoints[i3].worldPos);
        v1.copy(p2).sub(p1);
        v2.copy(p3).sub(p1);
        normal.cross(v1, v2);

        if (normal.lengthSq() < 1e-12) continue;
        normal.normalize();

        const pd = -normal.dot(p1);

        let inlierCount = 0;
        const inlierMask: boolean[] = [];
        for (let i = 0; i < n; i++) {
            const dist = Math.abs(normal.dot(nearPoints[i].worldPos) + pd);
            if (dist < distanceThreshold) {
                inlierMask[i] = true;
                // Normal-weighted voting: points with similar normals get higher weight
                if (nearPoints[i].normal) {
                    var ns = Math.abs(nearPoints[i].normal.dot(normal));
                    inlierCount += weights[i] * (0.3 + 0.7 * ns);
                } else {
                    inlierCount += weights[i];
                }
            } else {
                inlierMask[i] = false;
            }
        }

        if (inlierCount > bestInlierCount) {
            bestInlierCount = inlierCount;
            bestInlierMask = inlierMask;
            bestPlaneNormal.copy(normal);
            bestPlaneD = pd;
        }
    }

    const inlierPoints: NearPoint[] = [];
    for (let i = 0; i < n; i++) {
        if (bestInlierMask[i]) {
            inlierPoints.push(nearPoints[i]);
        }
    }

    if (inlierPoints.length < 3) return null;

    const result = estimatePlane(inlierPoints);
    if (!result) return null;

    console.log(
        `[RANSAC] 内点=${inlierPoints.length}/${n} ` +
      `(加权分=${bestInlierCount.toFixed(1)}) ` +
      `残差=${result.averageResidual.toFixed(4)}`
    );

    return result;
}

/**
 * 合并多次采样的邻域点，去重并按距离排序
 * 用于多点矫正流程：将不同点击位置的采样结果合并为一个统一邻域点集
 *
 * @param samples - 多次采样的结果数组
 * @returns 去重合并后的邻域点数组，最多 1500 个
 */
function mergeSamples(samples: SampleResult[]): NearPoint[] {
    const allPoints: NearPoint[] = [];
    for (const s of samples) {
        for (const p of s.nearPoints) {
            allPoints.push(p);
        }
    }
    allPoints.sort((a, b) => a.distanceToHit - b.distanceToHit);
    const seen = new Set<number>();
    const merged: NearPoint[] = [];
    for (const p of allPoints) {
        if (!seen.has(p.index)) {
            seen.add(p.index);
            merged.push(p);
        }
    }
    return merged.slice(0, 1500);
}

// ============================================================
// 矩形拟合器
// ============================================================

/**
 * 从整个 splat 中收集与给定平面共面且靠近命中点的点
 *
 * 遍历所有高斯点，收集到平面距离 < threshold 的内点，
 * 最后按距命中点距离排序，取最近的 maxPoints 个。
 *
 * @param splat - 被命中的 Splat 对象
 * @param plane - 已拟合的平面
 * @param hitWorldPos - 命中点世界坐标（用于空间排序）
 * @param maxPoints - 最多收集的内点数，默认 5000
 * @param distanceThreshold - 到平面的距离阈值（米），默认 0.05
 * @returns 共面内点数组（按距命中点升序）
 */
function collectPlaneInliers(
    splat: Splat,
    plane: Plane,
    hitWorldPos: Vec3,
    maxPoints: number = 5000,
    distanceThreshold: number = 0.02,
    anchorPoints?: Vec3[],
    maxSpan?: number,
    normalSimilarityThreshold: number = 0.5): NearPoint[] {
    const splatData = splat.splatData;
    const N = splatData.numSplats;

    const xArr = splatData.getProp('x') as Float32Array;
    const yArr = splatData.getProp('y') as Float32Array;
    const zArr = splatData.getProp('z') as Float32Array;
    if (!xArr || !yArr || !zArr) return [];

    const state = splatData.getProp('state') as Uint8Array | undefined;
    const rot0 = splatData.getProp('rot_0') as Float32Array | undefined;
    const rot1 = splatData.getProp('rot_1') as Float32Array | undefined;
    const rot2 = splatData.getProp('rot_2') as Float32Array | undefined;
    const rot3 = splatData.getProp('rot_3') as Float32Array | undefined;
    const sx = splatData.getProp('scale_0') as Float32Array | undefined;
    const sy = splatData.getProp('scale_1') as Float32Array | undefined;
    const sz = splatData.getProp('scale_2') as Float32Array | undefined;
    const worldTransform = splat.worldTransform;
    const tempLocal = new Vec3();
    const tempWorld = new Vec3();

    const { normal, d } = plane;
    const threshSq = distanceThreshold * distanceThreshold;
    const raw: Array<{ point: NearPoint; hitDistSq: number }> = [];

    for (let i = 0; i < N; i++) {
        if (state && state[i] & (State.deleted | State.locked)) continue;

        tempLocal.set(xArr[i], yArr[i], zArr[i]);
        worldTransform.transformPoint(tempLocal, tempWorld);

        const distToPlane = normal.dot(tempWorld) + d;
        if (distToPlane * distToPlane <= threshSq) {
            // 锚点距离过滤：只保留距任意点击点 maxSpan 以内的点
            if (anchorPoints && maxSpan) {
                const spanSq = maxSpan * maxSpan;
                let minAnchorDistSq = Infinity;
                for (const anchor of anchorPoints) {
                    const adx = tempWorld.x - anchor.x;
                    const ady = tempWorld.y - anchor.y;
                    const adz = tempWorld.z - anchor.z;
                    const ad = adx * adx + ady * ady + adz * adz;
                    if (ad < minAnchorDistSq) minAnchorDistSq = ad;
                }
                if (minAnchorDistSq > spanSq) continue;
            }
            
            // Normal consistency filter: skip Gaussians whose normal differs too much from plane normal
            if (normalSimilarityThreshold > 0 && rot0 && rot1 && rot2 && rot3 && sx && sy && sz) {
                const qx = rot0[i], qy = rot1[i], qz = rot2[i], qw = rot3[i];
                const c0x = 1 - 2*(qy*qy + qz*qz), c0y = 2*(qx*qy + qw*qz), c0z = 2*(qx*qz - qw*qy);
                const c1x = 2*(qx*qy - qw*qz), c1y = 1 - 2*(qx*qx + qz*qz), c1z = 2*(qy*qz + qw*qx);
                const c2x = 2*(qx*qz + qw*qy), c2y = 2*(qy*qz - qw*qx), c2z = 1 - 2*(qx*qx + qy*qy);
                const _s0 = Math.exp(sx[i]), _s1 = Math.exp(sy[i]), _s2 = Math.exp(sz[i]);
                let _lnx = c2x, _lny = c2y, _lnz = c2z;
                if (_s0 <= _s1 && _s0 <= _s2)      { _lnx = c0x; _lny = c0y; _lnz = c0z; }
                else if (_s1 <= _s0 && _s1 <= _s2) { _lnx = c1x; _lny = c1y; _lnz = c1z; }
                const _ln = new Vec3(_lnx, _lny, _lnz);
                worldTransform.transformVector(_ln, _ln);
                _ln.normalize();
                const sim = Math.abs(_ln.dot(normal));
                if (sim < normalSimilarityThreshold) continue;
            }
const dx = tempWorld.x - hitWorldPos.x;
            const dy = tempWorld.y - hitWorldPos.y;
            const dz = tempWorld.z - hitWorldPos.z;
            const hitDistSq = dx * dx + dy * dy + dz * dz;

            raw.push({
                point: {
                    index: i,
                    worldPos: tempWorld.clone(),
                    localPos: tempLocal.clone(),
                    scale: 1,
                    opacity: 1,
                    distanceToHit: Math.abs(distToPlane)
                },
                hitDistSq
            });
        }
    }

    // 按距命中点距离升序排列，取最近的一批
    raw.sort((a, b) => a.hitDistSq - b.hitDistSq);
    return raw.slice(0, maxPoints).map(r => r.point);
}

/**
 * 通过连通域扩张推算矩形边界
 *
 * 核心思路：将共面内点投影到 2D 网格后，从命中格出发做 BFS 四邻域洪水填充，
 * 所有连通的格子构成一个连通块，取其包围盒即为面的矩形边界。
 *
 * 与之前单线扩张的区别：单线扩张只沿十字线走，一列没点就停；
 * BFS 会填满整个连通区域，天然跳过不相连的平行面，同时容忍面内的小空隙。
 *
 * 算法步骤：
 *   1. 建立平面局部坐标系 (U, V)
 *   2. 将所有内点的世界坐标投影到 UV，建立空间哈希网格
 *   3. 投影命中点到 UV → 种子格
 *   4. BFS：从种子格出发，向四邻域扩散，收集所有连通的格子
 *   5. 取所有收集格子的包围盒 → UV 边界
 *   6. 将 UV 边界反算回 3D 四角点
 *
 * @param plane - 已拟合的平面
 * @param inliers - 共面内点数组
 * @param hitWorldPos - 命中点的世界坐标（扩张原点）
 * @returns 拟合矩形；内点不足 3 时返回 null
 */
function fitRect(
    plane: Plane,
    inliers: NearPoint[],
    hitWorldPos: Vec3
): Rect | null {
    const n = inliers.length;
    if (n < 3) return null;

    const { normal, center } = plane;

    // ---- 第 1 步：建立局部 2D 坐标系 (U, V) ----
    const ref = Math.abs(normal.dot(Vec3.UP)) > 0.99 ? Vec3.RIGHT : Vec3.UP;
    const uAxis = new Vec3().cross(ref, normal).normalize();
    const vAxis = new Vec3().cross(normal, uAxis).normalize();

    // ---- 第 2 步：计算网格单元大小 ----
    // 取平均最近邻距离的 2 倍，确保相邻点群自然落在相邻格内
    const pointSpacing = estimateCellSize(inliers);
    if (pointSpacing <= 0) return null;
    const cellSize = pointSpacing * 2;

    // ---- 第 3 步：构建空间哈希网格 ----
    const grid = new Map<string, number>();
    const temp = new Vec3();
    const toGrid = (worldPos: Vec3) => {
        temp.copy(worldPos).sub(center);
        return {
            u: Math.floor(temp.dot(uAxis) / cellSize),
            v: Math.floor(temp.dot(vAxis) / cellSize)
        };
    };

    for (let i = 0; i < n; i++) {
        const { u: gu, v: gv } = toGrid(inliers[i].worldPos);
        const key = `${gu},${gv}`;
        grid.set(key, (grid.get(key) || 0) + 1);
    }

    // ---- 第 4 步：找最近共面点做种子 ----
    let seedU = 0,
        seedV = 0;
    let bestDist = Infinity;
    for (let i = 0; i < n && i < 2000; i++) {
        const p = inliers[i].worldPos;
        const dx = p.x - hitWorldPos.x;
        const dy = p.y - hitWorldPos.y;
        const dz = p.z - hitWorldPos.z;
        const d = dx * dx + dy * dy + dz * dz;
        if (d < bestDist) {
            bestDist = d;
            const { u, v } = toGrid(inliers[i].worldPos);
            seedU = u;
            seedV = v;
        }
    }

    // ---- 第 5 步：根据网格点密度计算最少点数门槛 ----
    const cellCounts = Array.from(grid.values());
    cellCounts.sort((a, b) => a - b);
    const medianCellPoints = cellCounts[Math.floor(cellCounts.length / 2)] || 1;
    const minCellPoints = Math.max(2, Math.ceil(medianCellPoints * 0.3));

    // ---- 第 6 步：4 邻域 BFS 连通域扩张 ----
    // 4 邻域（不含对角）配合密度门槛，防止稀疏噪点撑大矩形
    const NEIGHBORS4: [number, number][] = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1]
    ];

    const visited = new Set<string>();
    const queue: [number, number][] = [];
    const seedKey = `${seedU},${seedV}`;

    if ((grid.get(seedKey) || 0) >= minCellPoints) {
        visited.add(seedKey);
        queue.push([seedU, seedV]);
    }

    // 边界初始化为种子格
    let minU = seedU,
        maxU = seedU;
    let minV = seedV,
        maxV = seedV;

    let _head = 0;
    while (_head < queue.length) {
        const [gu, gv] = queue[_head++];

        // 更新包围盒边界
        if (gu < minU) minU = gu;
        if (gu > maxU) maxU = gu;
        if (gv < minV) minV = gv;
        if (gv > maxV) maxV = gv;

        // 4 邻域发散
        for (let k = 0; k < 4; k++) {
            const [du, dv] = NEIGHBORS4[k];
            const [nu, nv] = [gu + du, gv + dv];
            const nKey = `${nu},${nv}`;
            if ((grid.get(nKey) || 0) >= minCellPoints && !visited.has(nKey)) {
                visited.add(nKey);
                queue.push([nu, nv]);
            }
        }
    }

    // ---- 调试：打印网格快照（以连通区域为中心） ----
    {
        const viewW = Math.min(Math.max(maxU - minU + 1, 10), 40);
        const viewH = Math.min(Math.max(maxV - minV + 1, 6), 25);
        const viewPad = 3;
        const vMin = minV - viewPad;
        const vMax = maxV + viewPad;
        const uMin = minU - viewPad;
        const uMax = maxU + viewPad;
        const rows: string[] = [];

        for (let v = vMin; v <= vMax; v++) {
            let row = '';
            for (let u = uMin; u <= uMax; u++) {
                const key = `${u},${v}`;
                if (u === seedU && v === seedV) {
                    row += '★';
                } else if (visited.has(key)) {
                    row += '█';
                } else if (grid.has(key)) {
                    row += '□';
                } else {
                    row += '·';
                }
            }
            rows.push(row);
        }

        console.log(
            `[RectFitting] 网格调试
  内点总数=${inliers.length} 点间距=${pointSpacing.toFixed(
    4
)}m 网格单元=${cellSize.toFixed(4)}m 格子总数=${grid.size}
  种子格=(${seedU},${seedV})
  连通区域 U=[${minU},${maxU}] V=[${minV},${maxV}]
  连通格子=${visited.size} 未连通格子=${
    grid.size - visited.size
} 密度门槛=${minCellPoints}点/格 (${(
    (visited.size / Math.max(grid.size, 1)) *
        100
).toFixed(0)}%)
  ★=种子 █=已连通 □=未连通 ·=空格
${rows.join('\n')}`
        );
    }

    const halfWidth = ((maxU - minU) / 2) * cellSize;
    const halfHeight = ((maxV - minV) / 2) * cellSize;
    const midU = ((maxU + minU) / 2) * cellSize;
    const midV = ((maxV + minV) / 2) * cellSize;

    // ---- 第 6 步：反算四角点到 3D 空间 ----
    const rectCenter = center
    .clone()
    .addScaled(uAxis, midU)
    .addScaled(vAxis, midV);

    const corners: Vec3[] = [
        rectCenter
        .clone()
        .addScaled(uAxis, -halfWidth)
        .addScaled(vAxis, -halfHeight),
        rectCenter
        .clone()
        .addScaled(uAxis, halfWidth)
        .addScaled(vAxis, -halfHeight),
        rectCenter.clone().addScaled(uAxis, halfWidth).addScaled(vAxis, halfHeight),
        rectCenter
        .clone()
        .addScaled(uAxis, -halfWidth)
        .addScaled(vAxis, halfHeight)
    ];

    return {
        center: rectCenter,
        normal: normal.clone(),
        uAxis: uAxis.clone(),
        vAxis: vAxis.clone(),
        halfWidth,
        halfHeight,
        corners
    };
}

/**
 * 多种子 BFS 投票拟合矩形
 *
 * 与单种子 fitRect 的区别：从多个种子点分别做 BFS 连通域扩张，
 * 对每个网格单元格按种子投票，只有被多数种子共同触达的格子才纳入最终区域。
 * 投票机制天然过滤单种子独有的边缘噪点格，显著提升边界准确性。
 *
 * @param plane - 已拟合的平面
 * @param inliers - 共面内点数组
 * @param seeds - 多个种子点的世界坐标（通常为用户多次点击位置）
 * @returns 拟合矩形；内点不足 3 时返回 null
 */
function fitRectMultiSeed(
    plane: Plane,
    inliers: NearPoint[],
    seeds: Vec3[]
): Rect | null {
    const n = inliers.length;
    if (n < 3 || seeds.length === 0) return null;

    const { normal, center } = plane;

    const ref = Math.abs(normal.dot(Vec3.UP)) > 0.99 ? Vec3.RIGHT : Vec3.UP;
    const uAxis = new Vec3().cross(ref, normal).normalize();
    const vAxis = new Vec3().cross(normal, uAxis).normalize();

    const pointSpacing = estimateCellSize(inliers);
    if (pointSpacing <= 0) return null;
    const cellSize = pointSpacing * 2;

    // ---- 构建空间哈希网格 ----
    const grid = new Map<string, number>();
    const temp = new Vec3();
    const toGrid = (worldPos: Vec3) => {
        temp.copy(worldPos).sub(center);
        return {
            u: Math.floor(temp.dot(uAxis) / cellSize),
            v: Math.floor(temp.dot(vAxis) / cellSize)
        };
    };

    for (let i = 0; i < n; i++) {
        const { u: gu, v: gv } = toGrid(inliers[i].worldPos);
        const key = `${gu},${gv}`;
        grid.set(key, (grid.get(key) || 0) + 1);
    }

    // ---- 密度门槛 ----
    const cellCounts = Array.from(grid.values());
    cellCounts.sort((a, b) => a - b);
    const medianCellPoints = cellCounts[Math.floor(cellCounts.length / 2)] || 1;
    const minCellPoints = Math.max(2, Math.ceil(medianCellPoints * 0.3));

    // ---- 计算各种子的网格坐标 ----
    const seedCells: [number, number][] = [];
    for (const seed of seeds) {
        const { u, v } = toGrid(seed);
        seedCells.push([u, v]);
    }

    // ---- 从每个种子独立 BFS，记录每个格子被哪些种子触达 ----
    const cellVotes = new Map<string, Set<number>>();
    const NEIGHBORS4: [number, number][] = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1]
    ];

    for (let si = 0; si < seedCells.length; si++) {
        let [su, sv] = seedCells[si];
        let seedKey = `${su},${sv}`;

        // 若种子格不在网格中（或密度不足），在 3x3 范围内找最近的有资格格
        if ((grid.get(seedKey) || 0) < minCellPoints) {
            let bestDist = Infinity;
            let bestU = su,
                bestV = sv;
            for (let du = -3; du <= 3; du++) {
                for (let dv = -3; dv <= 3; dv++) {
                    const nKey = `${su + du},${sv + dv}`;
                    if ((grid.get(nKey) || 0) >= minCellPoints) {
                        const nd = du * du + dv * dv;
                        if (nd < bestDist) {
                            bestDist = nd;
                            bestU = su + du;
                            bestV = sv + dv;
                        }
                    }
                }
            }
            if (bestDist === Infinity) continue; // 附近无合格格
            su = bestU;
            sv = bestV;
            seedKey = `${su},${sv}`;
        }

        const visited = new Set<string>();
        const queue: [number, number][] = [[su, sv]];
        visited.add(seedKey);

        let _head2 = 0;
        while (_head2 < queue.length) {
            const [gu, gv] = queue[_head2++];
            const key = `${gu},${gv}`;

            if (!cellVotes.has(key)) cellVotes.set(key, new Set());
      cellVotes.get(key)!.add(si);

      for (const [du, dv] of NEIGHBORS4) {
          const nu = gu + du,
              nv = gv + dv;
          const nKey = `${nu},${nv}`;
          if ((grid.get(nKey) || 0) >= minCellPoints && !visited.has(nKey)) {
              visited.add(nKey);
              queue.push([nu, nv]);
          }
      }
        }
    }

    if (cellVotes.size === 0) return null;

    // ---- 并集：取所有种子 BFS 区域的并集（而非交集投票）----
    // 交集投票在种子间距较大时会因连通域不重叠而失败，
    // 并集确保每个种子覆盖的区域都纳入最终矩形
    const unionCells: [number, number][] = [];
    for (const [key] of cellVotes) {
        const [u, v] = key.split(',').map(Number);
        unionCells.push([u, v]);
    }

    if (unionCells.length === 0) return null;

    // ---- 取并集格子的包围盒 ----
    let minU = Infinity,
        maxU = -Infinity;
    let minV = Infinity,
        maxV = -Infinity;
    for (const [u, v] of unionCells) {
        if (u < minU) minU = u;
        if (u > maxU) maxU = u;
        if (v < minV) minV = v;
        if (v > maxV) maxV = v;
    }

    const halfWidth = ((maxU - minU) / 2) * cellSize;
    const halfHeight = ((maxV - minV) / 2) * cellSize;
    const midU = ((maxU + minU) / 2) * cellSize;
    const midV = ((maxV + minV) / 2) * cellSize;

    const rectCenter = center
    .clone()
    .addScaled(uAxis, midU)
    .addScaled(vAxis, midV);
    const corners: Vec3[] = [
        rectCenter
        .clone()
        .addScaled(uAxis, -halfWidth)
        .addScaled(vAxis, -halfHeight),
        rectCenter
        .clone()
        .addScaled(uAxis, halfWidth)
        .addScaled(vAxis, -halfHeight),
        rectCenter.clone().addScaled(uAxis, halfWidth).addScaled(vAxis, halfHeight),
        rectCenter
        .clone()
        .addScaled(uAxis, -halfWidth)
        .addScaled(vAxis, halfHeight)
    ];

    console.log(
        `[MultiSeed] 种子=${seeds.length} 并集=${unionCells.length}格
        半宽/半高=${halfWidth.toFixed(2)}/${halfHeight.toFixed(2)}`
    );

    return {
        center: rectCenter,
        normal: normal.clone(),
        uAxis: uAxis.clone(),
        vAxis: vAxis.clone(),
        halfWidth,
        halfHeight,
        corners
    };
}

/**
 * 估算点云的平均最近邻距离，用作扩张网格单元尺寸
 *
 * 采样部分点（最多 200 个）计算最近邻距离，取中位数。
 * 网格单元太大 → 无法分辨间隙；太小 → 误判断崖。
 *
 * @param points - 内点数组
 * @returns 网格单元尺寸（米）
 */
function estimateCellSize(points: NearPoint[]): number {
    const sampleSize = Math.min(points.length, 200);
    const step = Math.max(1, Math.floor(points.length / sampleSize));
    const dists: number[] = [];

    for (let i = 0; i < points.length; i += step) {
        let minDist = Infinity;
        const p = points[i].worldPos;
        for (let j = 0; j < points.length; j += step) {
            if (i === j) continue;
            const q = points[j].worldPos;
            const dx = p.x - q.x;
            const dy = p.y - q.y;
            const dz = p.z - q.z;
            const d = Math.sqrt(dx * dx + dy * dy + dz * dz);
            if (d < minDist) minDist = d;
        }
        if (minDist < Infinity) dists.push(minDist);
    }

    if (dists.length === 0) return 0;
    dists.sort((a, b) => a - b);
    return dists[Math.floor(dists.length / 2)];
}

/**
 * 将矩形沿 U/V 轴向外扩展指定的 padding 量
 *
 * 用于修正 OBB 拟合时因点云边缘稀疏导致的边界收缩。
 * padding 会同时向 U 轴正负方向和 V 轴正负方向各扩展。
 *
 * @param rect - 原矩形
 * @param padding - 沿各轴向外的扩展量（米）
 * @returns 扩展后的新矩形
 */
function expandRect(rect: Rect, padding: number): Rect {
    const hw = rect.halfWidth + padding;
    const hh = rect.halfHeight + padding;

    return {
        center: rect.center.clone(),
        normal: rect.normal.clone(),
        uAxis: rect.uAxis.clone(),
        vAxis: rect.vAxis.clone(),
        halfWidth: hw,
        halfHeight: hh,
        corners: [
            rect.center.clone().addScaled(rect.uAxis, -hw).addScaled(rect.vAxis, -hh),
            rect.center.clone().addScaled(rect.uAxis, hw).addScaled(rect.vAxis, -hh),
            rect.center.clone().addScaled(rect.uAxis, hw).addScaled(rect.vAxis, hh),
            rect.center.clone().addScaled(rect.uAxis, -hw).addScaled(rect.vAxis, hh)
        ]
    };
}

