/**
 * EntityTransformHandler - 实体级别的变换处理器
 *
 * 核心功能：
 * - 当用户移动/旋转/缩放整个 splat 实体时（而非单个高斯点），使用此处理器
 * - 直接修改实体的局部变换（位置、旋转、缩放），并通过 move() 方法同步更新世界包围盒
 * - 支持 undo/redo 操作
 *
 * 与 SplatsTransformHandler 的区别：
 * - EntityTransformHandler 操作的是整个 splat 实体（所有高斯点一起变换）
 * - SplatsTransformHandler 仅操作选中的高斯点（通过调色板 per-splat 变换）
 *
 * 适用场景：
 * - 选中了 splat 但没有选中任何具体高斯点时
 * - 对整个点云进行位置/旋转/缩放调整
 */
import { Mat4, Quat, Vec3 } from 'playcanvas';

import { PlacePivotOp, EntityTransformOp, MultiOp } from './edit-ops';
import { Events } from './events';
import { Pivot } from './pivot';
import { Splat } from './splat';
import { Transform } from './transform';
import { TransformHandler } from './transform-handler';

// 临时变量复用
const mat = new Mat4();
const quat = new Quat();
const transform = new Transform();

class EntityTransformHandler implements TransformHandler {
    events: Events;
    splat: Splat;
    /** 实体变换操作记录（用于 undo/redo） */
    top: EntityTransformOp;
    /** 轴心点位置变更记录（用于 undo/redo） */
    pop: PlacePivotOp;
    /**
     * 绑定矩阵：用于将轴心空间的变换转换回实体局部空间
     * bindMat = inv(pivot_world_transform) * entity_local_transform
     */
    bindMat = new Mat4();

    constructor(events: Events) {
        this.events = events;

        // 轴心开始拖拽 → 记录初始状态
        events.on('pivot.started', (pivot: Pivot) => {
            if (this.splat) {
                this.start();
            }
        });

        // 轴心拖拽移动 → 更新实体变换
        events.on('pivot.moved', (pivot: Pivot) => {
            if (this.splat) {
                this.update(pivot.transform);
            }
        });

        // 轴心拖拽结束 → 提交 undo/redo 记录
        events.on('pivot.ended', (pivot: Pivot) => {
            if (this.splat) {
                this.end();
            }
        });

        // 轴心原点模式切换
        events.on('pivot.origin', (mode: 'center' | 'boundCenter') => {
            if (this.splat) {
                this.placePivot();
            }
        });

        // 焦点拾取：将轴心移动到用户点击的位置
        events.on('camera.focalPointPicked', (details: { splat: Splat, position: Vec3 }) => {
            if (this.splat && ['move', 'rotate', 'scale'].includes(this.events.invoke('tool.active'))) {
                const pivot = events.invoke('pivot') as Pivot;
                const newt = new Transform(details.position, pivot.transform.rotation, pivot.transform.scale);
                const op = new PlacePivotOp({ pivot, oldt: pivot.transform.clone(), newt });
                events.fire('edit.add', op);
            }
        });
    }

    /**
     * 放置初始轴心点
     *
     * 根据当前原点模式（'center' 或 'boundCenter'）获取轴心位置
     * 第二个参数 false 表示使用全部 splat 的包围盒（而非仅选中 splat）
     */
    placePivot() {
        const origin = this.events.invoke('pivot.origin');
        this.splat.getPivot(origin === 'center' ? 'center' : 'boundCenter', false, transform);
        this.events.invoke('pivot').place(transform);
    }

    activate() {
        this.splat = this.events.invoke('selection') as Splat;
        if (this.splat) {
            this.placePivot();
        }
    }

    deactivate() {
        this.splat = null;
    }

    /**
     * 开始变换操作
     *
     * 记录：
     * 1. bindMat: 将后续轴心空间的变化转换为实体局部空间的偏移
     * 2. 创建 EntityTransformOp（记录 oldt/newt，初始时两者相同）
     * 3. 创建 PlacePivotOp（记录轴心位置变更）
     *
     * 矩阵绑定原理：
     * bindMat = inv(pivot_world) * entity_local
     * 则在拖拽中：new_entity_local = pivot_new * bindMat
     */
    start() {
        const pivot = this.events.invoke('pivot') as Pivot;
        const { transform } = pivot;
        const { entity } = this.splat;

        // 计算绑定矩阵
        this.bindMat.setTRS(transform.position, transform.rotation, transform.scale);
        this.bindMat.invert();
        this.bindMat.mul2(this.bindMat, entity.getLocalTransform());

        const p = entity.getLocalPosition();
        const r = entity.getLocalRotation();
        const s = entity.getLocalScale();

        // 创建操作记录（初始时 oldt 和 newt 相同）
        this.top = new EntityTransformOp({
            splat: this.splat,
            oldt: new Transform(p, r, s),
            newt: new Transform(p, r, s)
        });

        this.pop = new PlacePivotOp({
            pivot,
            oldt: transform.clone(),
            newt: transform.clone()
        });
    }

    /**
     * 更新实体变换
     *
     * 计算流程：
     * 1. 从轴心新变换构建矩阵: mat = TRS(pivot.position, pivot.rotation, pivot.scale)
     * 2. 应用绑定矩阵得到实体局部变换: new_mat = mat * bindMat
     * 3. 从 new_mat 提取位置、旋转（四元数）、缩放
     * 4. 调用 splat.move() 应用新变换
     * 5. 更新操作记录中的 newt
     *
     * @param transform - 轴心当前的变换值
     */
    update(transform: Transform) {
        // 构建轴心世界变换矩阵
        mat.setTRS(transform.position, transform.rotation, transform.scale);
        // 应用绑定：entity_local = pivot * bindMat
        mat.mul2(mat, this.bindMat);
        quat.setFromMat4(mat);

        const t = mat.getTranslation();  // 提取平移分量
        const r = quat;                   // 提取旋转分量
        const s = mat.getScale();         // 提取缩放分量

        this.splat.move(t, r, s);
        this.top.newt.set(t, r, s);
        this.pop.newt.copy(transform);
    }

    /**
     * 结束变换操作
     *
     * 仅当旧变换和新变换不同时才记录到编辑历史（避免空操作）
     */
    end() {
        const { oldt, newt } = this.top;

        // 如果确实发生了变换，才记录操作
        if (!oldt.equals(newt)) {
            this.events.fire('edit.add', new MultiOp([this.top, this.pop]));
        }

        this.top = null;
        this.pop = null;
    }
}

export { EntityTransformHandler };
