import { Vec3 } from 'playcanvas';

import { Scene } from '../scene';
import {
    sample,
    estimatePlane,
    estimatePlaneRANSAC,
    mergeSamples,
    collectPlaneInliers,
    fitRectMultiSeed,
    Rect,
    NearPoint
} from './surface-annotate-common';

// ============================================================
// 智能拟合模式的上下文接口
// ============================================================

interface AutoAnnotateContext {
    scene: Scene;
    state: {
        clicks: Array<{ worldPos: Vec3; splat: import('../splat').Splat; sampleResult: import('./surface-annotate-common').SampleResult }>;
        currentRect: Rect | null;
        lastNormal: Vec3 | null;
        finalized: boolean;
    };
    MAX_CLICKS?: number;
    onUpdateUI?: (msg?: string) => void;
    onFinish?: () => void;
}

// ============================================================
// 智能拟合 - handleAutoClick
// ============================================================

async function handleAutoClick(
    event: PointerEvent,
    ctx: AutoAnnotateContext,
    parent: HTMLElement
): Promise<void> {
        const s = ctx.state;
    const MAX_CLICKS = ctx.MAX_CLICKS ?? 3;
    if (s.clicks.length >= MAX_CLICKS) {
        if (!s.finalized) ctx.onFinish?.();
        return;
    }
    event.preventDefault();
    event.stopPropagation();
    const nRect = parent.getBoundingClientRect();
    const nX = (event.clientX - nRect.left) / nRect.width;
    const nY = (event.clientY - nRect.top) / nRect.height;
    ctx.onUpdateUI?.('正在检测...');
    const result = await ctx.scene.camera.intersect(nX, nY);
    if (!result) { ctx.onUpdateUI?.('未命中模型，请重试'); setTimeout(() => ctx.onUpdateUI?.(), 1500); return; }
    ctx.onUpdateUI?.('正在采样...');
    const sampleResult = sample(result.splat, result.position);
    if (!sampleResult) { ctx.onUpdateUI?.('采样失败，请换位置重试'); setTimeout(() => ctx.onUpdateUI?.(), 1500); return; }
    if (s.clicks.length > 0 && result.splat !== s.clicks[0].splat) {
        ctx.onUpdateUI?.('请在同一模型上操作'); setTimeout(() => ctx.onUpdateUI?.(), 1500); return;
    }
    s.clicks.push({ worldPos: result.position.clone(), splat: result.splat, sampleResult });
    ctx.onUpdateUI?.('正在拟合...');
    doFit(ctx);
    ctx.onUpdateUI?.();
    if (s.clicks.length >= MAX_CLICKS) ctx.onFinish?.();
}

// ============================================================
// 智能拟合 - doFit（核心拟合管线）
// ============================================================

function doFit(ctx: AutoAnnotateContext): void {
    const { scene, state: s } = ctx;
    if (s.clicks.length === 0) return;

    const pts = s.clicks.map(c => c.worldPos);
    const anchorWorldPos = pts;

    // 自适应锚点半径：根据点击点散布动态计算
    const span = (() => {
        let maxD = 0;
        for (let i = 0; i < pts.length; i++) {
            for (let j = i + 1; j < pts.length; j++) {
                const dx = pts[i].x - pts[j].x;
                const dy = pts[i].y - pts[j].y;
                const dz = pts[i].z - pts[j].z;
                const d = dx * dx + dy * dy + dz * dz;
                if (d > maxD) maxD = d;
            }
        }
        return Math.max(Math.sqrt(maxD) * 1.3, 0.5);
    })();

    // 合并所有采样的邻域点 → PCA 拟合平面
    const allNearPoints = mergeSamples(s.clicks.map(c => c.sampleResult));
    if (allNearPoints.length < 3) return;

    let planeResult = estimatePlane(allNearPoints);
    let planeMethod = 'PCA';
    if (planeResult && planeResult.averageResidual > 0.02) {
        const ransacResult = estimatePlaneRANSAC(allNearPoints);
        if (ransacResult) {
            planeResult = ransacResult;
            planeMethod = 'RANSAC';
        }
    }
    if (!planeResult) return;

    s.lastNormal = planeResult.plane.normal.clone();

    // 收集内点（锚点约束：自适应半径）
    let inliers = collectPlaneInliers(
        s.clicks[0].splat,
        planeResult.plane,
        pts[0],
        5000,
        0.02,
        anchorWorldPos,
        span,
        0.4
    );

    // 用内点重估平面
    if (inliers.length >= 3) {
        const refinedPlane = estimatePlane(inliers);
        if (refinedPlane && refinedPlane.averageResidual < planeResult.averageResidual * 3) {
            planeResult = refinedPlane;
            planeMethod += '+精化';
            inliers = collectPlaneInliers(
                s.clicks[0].splat,
                planeResult.plane,
                pts[0],
                5000,
                0.02,
                anchorWorldPos,
                span,
                0.4
            );
        }
    }

    // 多种子 BFS 拟合矩形
    const rect = fitRectMultiSeed(planeResult.plane, inliers, pts);
    if (!rect) return;

    s.currentRect = rect;
    scene.forceRender = true;

    const status = s.finalized ? '已锁定' : `点击${s.clicks.length}/${ctx.MAX_CLICKS ?? 3}`;
    console.log(
        `[标注] ${status} | ${planeMethod} | 残差=${planeResult.averageResidual.toFixed(4)} |` +
        ` 内点=${inliers.length} | 采样=${allNearPoints.length}点 |` +
        ` 半宽/半高=${rect.halfWidth.toFixed(2)}/${rect.halfHeight.toFixed(2)}`
    );
}

export { handleAutoClick, doFit, AutoAnnotateContext };
