/**
 * 工具管理器 - SuperSplat 工具系统的核心管理器
 *
 * 核心功能：
 * 1. 工具注册与查找：通过 register() 注册工具，get() 获取工具实例
 * 2. 工具激活/停用：管理当前活跃工具，同一时间只有一个工具处于活跃状态
 * 3. 坐标空间管理：支持在世界坐标(world)和本地坐标(local)之间切换
 * 4. 事件集成：通过全局事件总线与 UI 和其他子系统通信
 *
 * 设计说明：
 * - 再次点击当前活跃工具会将其停用（toggle 行为）
 * - 激活新工具前会自动停用旧工具，确保互斥性
 * - 坐标空间默认为 'world'（世界坐标）
 */
import { Events } from '../events';

/** 工具接口 - 所有工具必须实现 activate（激活）和 deactivate（停用）方法 */
interface Tool {
    activate: () => void;
    deactivate: () => void;
}

/**
 * 工具管理器类
 *
 * 负责管理 SuperSplat 中所有编辑工具的注册、激活和停用。
 * 通过全局事件总线 events 与 UI 面板、快捷键等子系统进行交互。
 */
class ToolManager {
    /** 工具注册表：key 为工具名称字符串，value 为工具实例 */
    tools = new Map<string, Tool>();
    events: Events;
    /** 当前活跃工具的名称，null 表示没有工具处于活跃状态 */
    active: string | null = null;

    /**
     * @param events - 全局事件总线实例，用于工具相关事件的监听和触发
     */
    constructor(events: Events) {
        this.events = events;

        // 监听 tool.deactivate 事件：当用户请求停用工具时，将 active 设为 null
        this.events.on('tool.deactivate', () => {
            this.activate(null);
        });

        // 注册 tool.active 查询函数：供其他子系统查询当前活跃工具名称
        this.events.function('tool.active', () => {
            return this.active;
        });

        // 坐标空间：'local' 表示本地坐标系，'world' 表示世界坐标系
        let coordSpace: 'local' | 'world' = 'world';

        // 设置坐标空间，仅在值发生变化时才触发事件，避免不必要的事件广播
        const setCoordSpace = (space: 'local' | 'world') => {
            if (space !== coordSpace) {
                coordSpace = space;
                events.fire('tool.coordSpace', coordSpace);
            }
        };

        // 注册 tool.coordSpace 查询函数：供其他子系统查询当前坐标空间
        events.function('tool.coordSpace', () => {
            return coordSpace;
        });

        // 监听 tool.setCoordSpace 事件：直接设置为指定的坐标空间
        events.on('tool.setCoordSpace', (value: 'local' | 'world') => {
            setCoordSpace(value);
        });

        // 监听 tool.toggleCoordSpace 事件：在世界坐标和本地坐标之间切换
        events.on('tool.toggleCoordSpace', () => {
            setCoordSpace(coordSpace === 'local' ? 'world' : 'local');
        });
    }

    /**
     * 注册一个工具到管理器中
     *
     * 注册后会自动监听 `tool.<name>` 事件，当该事件触发时自动激活对应工具。
     * 这种设计使得 UI 按钮只需触发事件即可激活工具，无需直接调用 activate()。
     *
     * @param name - 工具的唯一标识名称（如 'move'、'rotate'、'scale'）
     * @param tool - 工具实例，必须实现 Tool 接口（activate/deactivate 方法）
     */
    register(name: string, tool: Tool) {
        this.tools.set(name, tool);

        this.events.on(`tool.${name}`, () => {
            this.activate(name);
        });
    }

    /**
     * 根据名称获取工具实例
     *
     * @param toolName - 工具名称
     * @returns 工具实例，如果名称为空字符串/未注册则返回 null
     */
    get(toolName: string) {
        return (toolName && this.tools.get(toolName)) ?? null;
    }

    /**
     * 激活指定名称的工具
     *
     * 激活逻辑：
     * 1. 如果工具名与当前活跃工具相同 → 触发 toggle 行为，停用该工具
     * 2. 如果工具名不同 → 先停用旧工具，再激活新工具
     * 3. 停用和激活时分别触发相应的 deactivated/activated 事件
     *
     * @param toolName - 要激活的工具名称，传入 null 表示停用所有工具
     */
    activate(toolName: string | null) {
        if (toolName === this.active) {
            // 再次点击已激活的工具 → 切换为停用状态（toggle 行为）
            if (toolName) {
                this.activate(null);
            }
        } else {
            // 先停用旧工具
            if (this.active) {
                const tool = this.tools.get(this.active);
                tool.deactivate();
                // 触发特定工具的停用事件（如 'tool.move.deactivated'）
                this.events.fire(`tool.${this.active}.deactivated`);
                // 触发通用停用事件，传递被停用的工具名称
                this.events.fire('tool.deactivated', this.active);
            }

            this.active = toolName;

            // 激活新工具
            if (this.active) {
                const tool = this.tools.get(this.active);
                tool.activate();
            }

            // 触发特定工具的激活事件（如 'tool.move.activated'）
            this.events.fire(`tool.${toolName}.activated`);
            // 触发通用激活事件，传递被激活的工具名称
            this.events.fire('tool.activated', toolName);
        }
    }
}

export { ToolManager };
