import { Color, Vec3 } from 'playcanvas';

import { Events } from '../events';
import { Scene } from '../scene';
import { Splat } from '../splat';
import {
    SampleResult,
    Rect,
    persistentAnnotations,
    ensurePersistentRendering
} from './surface-annotate-common';
import { handleAutoClick, doFit } from './surface-annotate-auto';

// ============================================================
// 工具内部共享可变状态
// ============================================================

interface ToolState {
    lastNormal: Vec3 | null;
    currentRect: Rect | null;
    clicks: { worldPos: Vec3; splat: Splat; sampleResult: SampleResult }[];
    finalized: boolean;
}

// ============================================================
// 表面标注工具 - 智能拟合模式
// ============================================================

class SurfaceAnnotateTool {
    activate: () => void;
    deactivate: () => void;

    constructor(events: Events, scene: Scene, parent: HTMLElement) {
        const MAX_CLICKS = 3;

        const state: ToolState = {
            lastNormal: null,
            currentRect: null,
            clicks: [],
            finalized: false
        };

        let uiBar: HTMLDivElement | null = null;
        let uiStatus: HTMLSpanElement | null = null;
        let uiUndoBtn: HTMLButtonElement | null = null;
        const tempTip = new Vec3();

        const onPreRender = () => {
            const { currentRect, finalized, clicks } = state;
            if (!currentRect) return;
            try {
                const color = finalized ? Color.GREEN : new Color(1, 1, 0);
                const { corners, center, normal } = currentRect;
                const positions = [
                    corners[0], corners[1],
                    corners[1], corners[2],
                    corners[2], corners[3],
                    corners[3], corners[0],
                    center,
                    tempTip.copy(center).addScaled(normal, 0.2)
                ];
                scene.app.drawLines(positions, color, true, scene.worldLayer);

                for (const click of clicks) {
                    const p = click.worldPos;
                    const s = 0.03;
                    scene.app.drawLines([
                        new Vec3(p.x - s, p.y, p.z),
                        new Vec3(p.x + s, p.y, p.z),
                        new Vec3(p.x, p.y - s, p.z),
                        new Vec3(p.x, p.y + s, p.z),
                        new Vec3(p.x, p.y, p.z - s),
                        new Vec3(p.x, p.y, p.z + s)
                    ], Color.RED, false, scene.worldLayer);
                }
            } catch (e) {
                console.error('[onPreRender]', e);
            }
        };

        const updateUI = (msg?: string) => {
            if (!uiBar) return;
            if (msg) { uiStatus.textContent = msg; uiUndoBtn.disabled = true; return; }
            const count = state.clicks.length;
            if (state.finalized) { uiStatus.textContent = `已锁定 - ${count}次点击 | 可撤销`; uiUndoBtn.disabled = false; }
            else if (count === 0) { uiStatus.textContent = '点击面上任意位置开始'; uiUndoBtn.disabled = true; }
            else { uiStatus.textContent = `点击 ${count}/${MAX_CLICKS} | 右键=完成 退格=撤销`; uiUndoBtn.disabled = false; }
        };

        const finish = () => {
            if (state.finalized) return;
            if (state.clicks.length === 0) return;
            state.finalized = true;
            scene.forceRender = true;
            if (state.currentRect) {
                persistentAnnotations.push({ rect: state.currentRect });
                ensurePersistentRendering(scene);
            }
            updateUI();
        };

        const undoLastClick = () => {
            if (state.clicks.length === 0) return;
            if (state.finalized) { state.finalized = false; persistentAnnotations.pop(); }
            state.clicks.pop();
            if (state.clicks.length === 0) { state.currentRect = null; state.lastNormal = null; }
            else { doFit({ scene, state, onUpdateUI: updateUI, onFinish: finish }); }
            scene.forceRender = true;
            updateUI();
        };

        const clearAll = () => {
            persistentAnnotations.splice(0, persistentAnnotations.length);
            state.currentRect = null;
            state.clicks = [];
            state.lastNormal = null;
            state.finalized = false;
            scene.forceRender = true;
            updateUI();
        };

        const onKeyDown = (e: KeyboardEvent) => {
            if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;
            if ((e.key === 'z' || e.key === 'Z') && (e.ctrlKey || e.metaKey)) { e.preventDefault(); undoLastClick(); return; }
            if (e.key === 'Escape') { finish(); return; }
            if (e.key === 'Backspace') { e.preventDefault(); undoLastClick(); }
        };

        const onContextMenu = (e: Event) => e.preventDefault();

        const pointerdown = async (event: PointerEvent) => {
            if (event.button === 2) { event.preventDefault(); finish(); return; }
            if (event.button !== 0) return;
            await handleAutoClick(event, { scene, state, MAX_CLICKS, onUpdateUI: updateUI, onFinish: finish }, parent);
        };

        this.activate = () => {
            parent.style.display = 'block';
            parent.addEventListener('pointerdown', pointerdown);
            parent.addEventListener('contextmenu', onContextMenu);
            window.addEventListener('keydown', onKeyDown);
            scene.app.on('prerender', onPreRender);

            uiBar = document.createElement('div');
            Object.assign(uiBar.style, {
                position: 'absolute', bottom: '14px', left: '50%',
                transform: 'translateX(-50%)', background: 'rgba(20,20,20,0.85)',
                color: '#ddd', padding: '5px 12px', borderRadius: '8px',
                fontSize: '12px', fontFamily: 'monospace', display: 'flex',
                gap: '10px', alignItems: 'center', zIndex: '1000',
                pointerEvents: 'auto', userSelect: 'none'
            });
            uiBar.addEventListener('pointerdown', (e) => { e.stopPropagation(); });
            uiBar.addEventListener('click', (e) => { e.stopPropagation(); });

            uiStatus = document.createElement('span');
            uiStatus.textContent = '点击面上任意位置开始';

            const btnStyle = 'padding:2px 8px;border:1px solid #555;border-radius:4px;background:#333;color:#ddd;cursor:pointer;font-size:11px;font-family:monospace;';

            uiUndoBtn = document.createElement('button');
            uiUndoBtn.textContent = '撤销';
            uiUndoBtn.style.cssText = btnStyle;
            uiUndoBtn.disabled = true;
            uiUndoBtn.onclick = (e) => { e.stopPropagation(); e.preventDefault(); undoLastClick(); };

            const doneBtn = document.createElement('button');
            doneBtn.textContent = '完成';
            doneBtn.style.cssText = `${btnStyle}border-color:#4a4;background:#2a2;color:#fff;`;
            doneBtn.onclick = (e) => { e.stopPropagation(); e.preventDefault(); finish(); };

            const clearBtn = document.createElement('button');
            clearBtn.textContent = '清除';
            clearBtn.style.cssText = `${btnStyle}border-color:#844;background:#422;color:#faa;`;
            clearBtn.title = '清除所有标注';
            clearBtn.onclick = (e) => { e.stopPropagation(); e.preventDefault(); clearAll(); };

            uiBar.append(uiStatus, uiUndoBtn, doneBtn, clearBtn);
            parent.appendChild(uiBar);
            updateUI();
        };

        this.deactivate = () => {
            parent.style.display = 'none';
            parent.removeEventListener('pointerdown', pointerdown);
            parent.removeEventListener('contextmenu', onContextMenu);
            window.removeEventListener('keydown', onKeyDown);
            scene.app.off('prerender', onPreRender);
            if (uiBar) { uiBar.remove(); uiBar = null; }
            state.currentRect = null;
            state.clicks = [];
            state.finalized = false;
            state.lastNormal = null;
        };
    }
}

export { SurfaceAnnotateTool };
