/**
 * iframe-api.ts - iframe 嵌入模式 API
 *
 * 本模块负责处理 SuperSplat 编辑器在 iframe 中嵌入运行时的通信协议。
 *
 * 核心功能：
 * 1. 监听宿主窗口（父页面）通过 window.postMessage 发来的查询消息
 * 2. 当父页面询问"场景是否已修改(scene dirty)"时，通过事件系统查询结果并回复
 *
 * 设计思路：
 * - 使用 TypeScript 类型守卫（Type Guard）安全地判断消息类型
 * - 通过 Events 事件系统解耦，不直接访问场景状态
 * - 双向通信：父页面发送查询（Query）→ iframe 返回响应（Response）
 *
 * 通信协议：
 * - 消息类型标识: 'supersplat:is-scene-dirty'
 * - 请求: { type: 'supersplat:is-scene-dirty' }
 * - 响应: { type: 'supersplat:is-scene-dirty', result: boolean }
 */

import { Events } from './events';

/**
 * 消息类型常量 - 用于标识"场景是否脏"的查询/响应
 * 使用命名空间前缀 'supersplat:' 避免与其他 iframe 消息冲突
 */
const IS_SCENE_DIRTY = 'supersplat:is-scene-dirty';

/**
 * 查询接口 - 父页面发来的询问消息结构
 * type 字段用于区分不同种类的跨窗口消息
 */
interface IsSceneDirtyQuery {
    type: typeof IS_SCENE_DIRTY;
}

/**
 * 响应接口 - iframe 返回给父页面的应答消息结构
 * result 字段表示场景是否已被修改（true = 有未保存更改）
 */
interface IsSceneDirtyResponse {
    type: typeof IS_SCENE_DIRTY;
    result: boolean;
}

/**
 * 类型守卫函数 - 判断 postMessage 收到的 data 是否为合法的场景脏状态查询
 *
 * 为什么要用类型守卫：
 * window.postMessage 的 data 字段是 any 类型，任何来源都可以发送消息。
 * 使用类型守卫可以安全地过滤出我们关心的消息，忽略无关的 postMessage 调用。
 *
 * @param data - postMessage 事件的 data 属性，类型为 any
 * @returns 如果 data 是 IsSceneDirtyQuery 类型则返回 true，否则 false
 */
const isSceneDirtyQuery = (data: any): data is IsSceneDirtyQuery => {
    return (
        data &&
        typeof data === 'object' &&
        data.type === IS_SCENE_DIRTY
    );
};

/**
 * 注册 iframe API - 启动跨窗口消息监听
 *
 * 在应用初始化时调用，为 iframe 嵌入模式建立通信通道。
 * 监听来自宿主窗口的 message 事件，处理场景脏状态查询。
 *
 * 工作流程：
 * 1. 父页面通过 source.postMessage(query, origin) 发送查询
 * 2. 本函数监听到 message 事件后，用类型守卫判断是否为我们的查询
 * 3. 通过 events.invoke('scene.dirty') 获取场景当前是否被修改
 * 4. 使用 event.source.postMessage(response, event.origin) 将结果回传给父页面
 *
 * @param events - 全局事件系统实例，用于查询场景状态
 */
const registerIframeApi = (events: Events) => {
    window.addEventListener('message', (event: MessageEvent) => {
        // 获取消息来源窗口对象（即发送消息的父页面）
        const source = event.source as Window | null;
        if (!source) {
            return;
        }

        // 使用类型守卫判断是否是我们的查询消息
        if (isSceneDirtyQuery(event.data)) {
            // 构造响应：通过事件系统获取场景脏状态
            const response: IsSceneDirtyResponse = {
                type: IS_SCENE_DIRTY,
                result: events.invoke('scene.dirty') as boolean
            };
            // 向父页面回传结果（使用原始事件的 origin 作为目标源，安全地限制接收方）
            source.postMessage(response, event.origin);
        }
    });
};

export { registerIframeApi };
