/**
 * shortcut-manager.ts - 快捷键管理器
 *
 * @file 管理 SuperSplat 编辑器的所有快捷键绑定定义和格式化显示。
 * 提供快捷键的注册、查询和格式化功能，是快捷键系统的配置中心。
 *
 * 核心职责：
 *   1. 定义默认快捷键绑定（defaultShortcuts 对象）
 *   2. 在构造时注册所有快捷键到 Shortcuts 实例（实际的键盘事件处理器）
 *   3. 提供 get(id) 查询特定快捷方式的绑定配置
 *   4. 提供 formatShortcut(id) 生成人类可读的快捷键显示文本
 *      - 自动适配 Mac/Windows 的修饰键符号（⌘ vs Ctrl, ⌥ vs Alt）
 *
 * 快捷键绑定属性说明（ShortcutBinding）：
 *   - keys:        按键的值列表（基于 KeyboardEvent.key），如 ['f']、[' ']
 *   - codes:       物理键位码列表（基于 KeyboardEvent.code），如 ['KeyW']
 *                  code 用于 WASD 飞行键，因为它在非 QWERTY 键盘布局下不变
 *   - ctrl/shift/alt: 修饰键状态要求（'required'/'forbidden'/'optional'）
 *   - held:        是否持续按住生效（用于 WASD 飞行、Shift+WASD 加速等）
 *   - repeat:      是否响应键盘重复事件（用于逐帧前进等操作）
 *   - capture:     是否在捕获阶段处理事件（在目标元素之前拦截）
 *
 * 设计说明：
 *   - 快捷键定义集中在 defaultShortcuts 对象中，便于维护和审查
 *   - 构造时深拷贝默认绑定，支持运行时修改而不影响原始定义
 *   - 使用 code（物理键位）而非 key（字符值）处理 WASD，确保多语言键盘兼容
 */
import { platform } from 'playcanvas';

import { Events } from './events';
import { Shortcuts, ShortcutBinding } from './shortcuts';

// 检测当前运行平台是否为 macOS
// platform.name 是 PlayCanvas 提供的平台检测 API
const isMac = platform.name === 'osx';

/**
 * 默认快捷键绑定定义 — 所有快捷键的权威配置来源
 *
 * 键名为事件的标识符（如 'camera.focus'），
 * 键值为 ShortcutBinding 对象，描述触发该事件所需的按键组合。
 *
 * 分组说明：
 *   - Navigation: 相机导航操作（复位、聚焦、飞行模式等）
 *   - Show:       显示/隐藏切换（覆盖层、网格、选中物体等）
 *   - Playback:   时间轴播放控制（播放、逐帧、关键帧操作）
 *   - Selection:  选择操作（全选、反选、删除等）
 *   - Tools:      工具切换（移动、旋转、缩放、选择模式等）
 *   - Other:      编辑操作、面板切换等
 *   - Camera fly: 相机飞行键（WASD + 修饰键）
 */
const defaultShortcuts: Record<string, ShortcutBinding> = {
    // ========== 导航 Navigation ==========
    /** 相机复位到默认视角（Shift + F） */
    'camera.reset': { keys: ['f'], shift: 'required' },
    /** 聚焦到选中物体（F） */
    'camera.focus': { keys: ['f'] },
    /** 切换相机控制模式（V） */
    'camera.toggleControlMode': { keys: ['v'] },
    /** URL 导入 LAS（Ctrl + U） */
    'scene.importUrl': { keys: ['u'], ctrl: 'required' },

    // ========== 显示/隐藏 Show ==========
    /** 切换覆盖层显示（Tab） */
    'camera.toggleOverlay': { keys: ['Tab'] },
    /** 切换渲染模式 — 在球体/环/点云之间切换（M） */
    'camera.toggleMode': { keys: ['m'] },
    /** 切换无限网格的可见性（G） */
    'grid.toggleVisible': { keys: ['g'] },
    /** 隐藏选中的 splat（H） */
    'select.hide': { keys: ['h'] },
    /** 取消隐藏所有 splat（Shift + H） */
    'select.unhide': { keys: ['h'], shift: 'required' },

    // ========== 播放 Playback ==========
    /** 切换时间轴播放/暂停（Space 空格键） */
    'timeline.togglePlay': { keys: [' '] },
    /** 跳转到上一帧（逗号,），支持键盘重复（按住连发） */
    'timeline.prevFrame': { keys: [','], repeat: true },
    /** 跳转到下一帧（句号.），支持键盘重复 */
    'timeline.nextFrame': { keys: ['.'], repeat: true },
    /** 跳转到上一个关键帧（<），支持键盘重复 */
    'timeline.prevKey': { keys: ['<'], shift: 'optional', repeat: true },
    /** 跳转到下一个关键帧（>），支持键盘重复 */
    'timeline.nextKey': { keys: ['>'], shift: 'optional', repeat: true },
    /** 在当前帧添加关键帧（Enter） */
    'track.addKey': { keys: ['Enter'] },
    /** 删除当前帧的关键帧（Shift + Enter） */
    'track.removeKey': { keys: ['Enter'], shift: 'required' },

    // ========== 选择 Selection ==========
    /** 全选所有 splat（Ctrl/Cmd + A），capture 在捕获阶段拦截，防止浏览器"全选"行为 */
    'select.all': { keys: ['a'], ctrl: 'required', capture: true },
    /** 取消全部选择（Ctrl/Cmd + Shift + A），capture 同上 */
    'select.none': { keys: ['a'], ctrl: 'required', shift: 'required', capture: true },
    /** 反选（Ctrl/Cmd + I） */
    'select.invert': { keys: ['i'], ctrl: 'required' },
    /** 删除选中的 splat（Delete 或 Backspace） */
    'select.delete': { keys: ['Delete', 'Backspace'] },

    // ========== 工具 Tools ==========
    /** 切换到移动工具（1） */
    'tool.move': { keys: ['1'] },
    /** 切换到旋转工具（2） */
    'tool.rotate': { keys: ['2'] },
    /** 切换到缩放工具（3） */
    'tool.scale': { keys: ['3'] },
    /** 切换矩形选择工具（R） */
    'tool.rectSelection': { keys: ['r'] },
    /** 切换套索选择工具（L） */
    'tool.lassoSelection': { keys: ['l'] },
    /** 切换多边形选择工具（P） */
    'tool.polygonSelection': { keys: ['p'] },
    /** 切换笔刷选择工具（B） */
    'tool.brushSelection': { keys: ['b'] },
    /** 切换泛洪选择工具（O） */
    'tool.floodSelection': { keys: ['o'] },
    /** 切换吸管选择工具（Ctrl/Cmd + E），capture 防止冲突 */
    'tool.eyedropperSelection': { keys: ['e'], ctrl: 'required', capture: true },
    /** 缩小笔刷半径（[），支持键盘重复 */
    'tool.brushSelection.smaller': { keys: ['['], repeat: true },
    /** 放大笔刷半径（]），支持键盘重复 */
    'tool.brushSelection.bigger': { keys: [']'], repeat: true },
    /** 取消当前激活的工具（Escape） */
    'tool.deactivate': { keys: ['Escape'] },
    /** 切换变换坐标空间（Shift + C） — 在局部坐标和世界坐标之间切换 */
    'tool.toggleCoordSpace': { keys: ['c'], shift: 'required' },

    // ========== 其他 Other ==========
    /** 撤销（Ctrl/Cmd + Z），capture 防止浏览器默认行为，repeat 支持连续撤销 */
    'edit.undo': { keys: ['z'], ctrl: 'required', repeat: true, capture: true },
    /** 重做（Ctrl/Cmd + Shift + Z） */
    'edit.redo': { keys: ['z'], ctrl: 'required', shift: 'required', repeat: true, capture: true },
    /** 切换数据面板（Ctrl/Cmd + D） */
    'dataPanel.toggle': { keys: ['d'], ctrl: 'required', capture: true },
    /** 切换时间轴面板（Ctrl/Cmd + T） */
    'timelinePanel.toggle': { keys: ['t'], ctrl: 'required', capture: true },

    // ========== 相机飞行键 Camera fly keys ==========
    // 使用 codes（物理键位码）而非 keys（字符值），确保在非 QWERTY 键盘布局下
    // （如 AZERTY、Dvorak）WASD 仍然对应正确的物理位置
    // held: true 表示持续按住时生效（用于飞行模式的连续移动）

    /** 相机向前飞行（W 键），shift/alt 可选（用于加速/减速） */
    'camera.fly.forward': { codes: ['KeyW'], held: true, shift: 'optional', alt: 'optional' },
    /** 相机向后飞行（S 键） */
    'camera.fly.backward': { codes: ['KeyS'], held: true, shift: 'optional', alt: 'optional' },
    /** 相机向左飞行（A 键） */
    'camera.fly.left': { codes: ['KeyA'], held: true, shift: 'optional', alt: 'optional' },
    /** 相机向右飞行（D 键） */
    'camera.fly.right': { codes: ['KeyD'], held: true, shift: 'optional', alt: 'optional' },
    /** 相机向下飞行（Q 键） */
    'camera.fly.down': { codes: ['KeyQ'], held: true, shift: 'optional', alt: 'optional' },
    /** 相机向上飞行（E 键） */
    'camera.fly.up': { codes: ['KeyE'], held: true, shift: 'optional', alt: 'optional' },
    /** 飞行加速修饰键（按住 Shift 加速移动） */
    'camera.modifier.fast': { codes: ['ShiftLeft', 'ShiftRight'], held: true, alt: 'optional' },
    /** 飞行减速修饰键（按住 Alt 减速移动） */
    'camera.modifier.slow': { codes: ['AltLeft', 'AltRight'], held: true, shift: 'optional' }
};

/**
 * ShortcutManager 类 — 快捷键管理器
 *
 * 管理快捷键绑定定义，提供查询和格式化显示功能。
 * 在构造时自动创建 Shortcuts 实例并注册所有默认绑定，
 * 使键盘事件能够正确触发对应的编辑器操作。
 */
class ShortcutManager {
    /** 所有快捷键绑定的运行时副本（可修改而不影响 defaultShortcuts 原始定义） */
    private bindings: Record<string, ShortcutBinding>;

    /**
     * @param events - Events 事件总线实例
     *
     * 构造过程：
     *   1. 深拷贝默认快捷键绑定（避免修改原始定义）
     *   2. 创建 Shortcuts 实例（底层键盘事件处理器）
     *   3. 遍历所有绑定，逐一注册到 Shortcuts 实例
     */
    constructor(events: Events) {
        // 深拷贝默认绑定：对每个绑定创建新对象 { ...defaultShortcuts[id] }
        // 这样运行时修改绑定不会影响 defaultShortcuts 常量
        this.bindings = {};
        for (const id in defaultShortcuts) {
            this.bindings[id] = { ...defaultShortcuts[id] };
        }

        // 创建 Shortcuts 实例并注册所有绑定
        const shortcuts = new Shortcuts(events);
        for (const id in this.bindings) {
            const binding = this.bindings[id];
            // register() 将绑定添加到 Shortcuts 的匹配列表中
            shortcuts.register({
                event: id,              // 触发的事件标识符
                keys: binding.keys,     // 按键值列表
                codes: binding.codes,   // 物理键位码列表
                ctrl: binding.ctrl,     // Ctrl/Cmd 修饰键要求
                shift: binding.shift,   // Shift 修饰键要求
                alt: binding.alt,       // Alt 修饰键要求
                held: binding.held,     // 是否持续按住
                repeat: binding.repeat, // 是否响应键盘重复
                capture: binding.capture // 是否捕获阶段处理
            });
        }
    }

    /**
     * 获取指定事件 ID 的快捷键绑定配置
     *
     * @param id - 事件标识符，如 'edit.undo'、'camera.focus' 等
     * @returns ShortcutBinding 对象（包含 keys、modifiers 等配置），或 undefined（不存在该 ID）
     */
    get(id: string): ShortcutBinding | undefined {
        return this.bindings[id];
    }

    /**
     * 格式化快捷键为人类可读的显示字符串
     *
     * 自动适配操作系统显示风格：
     *   - macOS: 使用 Unicode 符号 — ⌘ (Cmd), ⌥ (Option), ⇧ (Shift)
     *     格式：⌘ ⇧ Z（只有空格无加号）
     *   - Windows/Linux: 使用英文单词 — Ctrl, Alt, Shift
     *     格式：Ctrl + Shift + Z
     *
     * 特殊处理：
     *   - 空格键: 显示为 "Space"
     *   - Escape: 显示为 "Esc"
     *   - 物理键位码如 KeyW: 提取为 "W"
     *   - 单个字符键: 转大写显示
     *
     * @param id - 事件标识符
     * @returns 格式化后的快捷键字符串，如 "Ctrl + Z" 或 "⌘Z"
     *   如果 ID 不存在或没有可显示的键，返回空字符串
     */
    formatShortcut(id: string): string {
        const binding = this.bindings[id];
        if (!binding) return '';

        const parts: string[] = [];

        // 按顺序添加修饰键符号（Mac 用 Unicode 符号，Windows 用英文）
        if (binding.ctrl === 'required') parts.push(isMac ? '⌘' : 'Ctrl');
        if (binding.alt === 'required') parts.push(isMac ? '⌥' : 'Alt');
        if (binding.shift === 'required') parts.push(isMac ? '⇧' : 'Shift');

        // 获取第一个键或键码作为显示文本
        let keyDisplay = binding.keys?.[0] ?? binding.codes?.[0];
        if (!keyDisplay) return '';

        // 特殊键名转换
        if (keyDisplay === ' ') {
            keyDisplay = 'Space';
        } else if (keyDisplay === 'Escape') {
            keyDisplay = 'Esc';
        } else if (keyDisplay.startsWith('Key')) {
            // 物理键位码 KeyW → W（去掉 "Key" 前缀）
            keyDisplay = keyDisplay.slice(3);
        } else if (keyDisplay.length === 1) {
            // 单个字符键转为大写
            keyDisplay = keyDisplay.toUpperCase();
        }

        parts.push(keyDisplay);

        // Mac 风格用空格分隔，Windows 风格用 " + " 分隔
        return isMac ? parts.join(' ') : parts.join(' + ');
    }
}

export { ShortcutManager };
