/**
 * @file rect-selection.ts
 * @description 矩形选择工具 —— 在画布上通过拖拽绘制矩形来框选 3D 高斯点。
 *
 * 核心功能：
 * - 使用 SVG <rect> 元素绘制选择框预览
 * - 支持修饰键切换选区模式：Shift=追加，Ctrl=移除，无=替换
 * - 短点击（未拖拽）会变为点选模式，选择单个高斯点
 * - 坐标系统：以父容器尺寸为基准，归一化到 0~1 区间，便于跨分辨率使用
 */

import { Events } from '../events';

/**
 * 矩形选择工具类
 *
 * 生命周期：
 * 1. new RectSelection(events, parent) —— 创建 SVG 层并绑定指针事件
 * 2. activate() —— 显示工具层，开始监听事件
 * 3. 用户拖拽绘制矩形，释放鼠标后触发选区
 * 4. deactivate() —— 隐藏工具层，停止监听事件
 * 5. destroy() —— 清理预留钩子（当前为空实现）
 */
class RectSelection {
    /** 激活工具：显示 SVG 层并注册指针事件监听器 */
    activate: () => void;
    /** 停用工具：隐藏 SVG 层并移除指针事件监听器，如有进行中的拖拽则取消 */
    deactivate: () => void;

    /**
     * @param events - 全局事件总线，用于触发选区操作（select.rect / select.point）
     * @param parent - 工具挂载的父 DOM 元素，作为画布容器
     */
    constructor(events: Events, parent: HTMLElement) {
        // 创建 SVG 覆盖层，用于绘制选择矩形
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.classList.add('tool-svg', 'hidden');
        svg.id = 'rect-select-svg';
        parent.appendChild(svg);

        // 创建 SVG <rect> 元素，作为选择框的视觉表示
        const rect = document.createElementNS(svg.namespaceURI, 'rect') as SVGRectElement;
        svg.appendChild(rect);

        // 拖拽起点（指针按下时的坐标）
        const start = { x: 0, y: 0 };
        // 拖拽终点（指针移动中的当前坐标）
        const end = { x: 0, y: 0 };
        // 当前正在拖拽的指针ID，undefined 表示未拖拽
        let dragId: number | undefined;
        // 标记拖拽过程中是否产生了移动（用于区分拖拽选择 vs 点选）
        let dragMoved = false;

        /**
         * 根据 start 和 end 坐标更新 SVG 矩形的属性
         * 使用 Math.min/max 计算，因此可以从任意方向（如从右下往左上）拖拽
         */
        const updateRect = () => {
            const x = Math.min(start.x, end.x);
            const y = Math.min(start.y, end.y);
            const width = Math.abs(start.x - end.x);
            const height = Math.abs(start.y - end.y);

            rect.setAttribute('x', x.toString());
            rect.setAttribute('y', y.toString());
            rect.setAttribute('width', width.toString());
            rect.setAttribute('height', height.toString());
        };

        /**
         * 指针按下事件处理：开始一次拖拽操作
         *
         * - pointerType === 'mouse' 时检查 button === 0（左键）
         * - 触控笔/手指时检查 isPrimary（主指针，防止多点触控干扰）
         * - 调用 setPointerCapture 确保后续 pointermove/pointerup 都发往此元素
         */
        const pointerdown = (e: PointerEvent) => {
            if (dragId === undefined && (e.pointerType === 'mouse' ? e.button === 0 : e.isPrimary)) {
                e.preventDefault();
                e.stopPropagation();

                dragId = e.pointerId;
                dragMoved = false;
                // 指针捕获：即使拖拽移出元素边界，也能继续接收 move/up 事件
                parent.setPointerCapture(dragId);

                start.x = end.x = e.offsetX;
                start.y = end.y = e.offsetY;

                updateRect();

                svg.classList.remove('hidden');
            }
        };

        /**
         * 指针移动事件处理：更新拖拽终点并重绘矩形
         */
        const pointermove = (e: PointerEvent) => {
            if (e.pointerId === dragId) {
                e.preventDefault();
                e.stopPropagation();

                dragMoved = true;
                end.x = e.offsetX;
                end.y = e.offsetY;

                updateRect();
            }
        };

        /**
         * 结束拖拽的清理工作：释放指针捕获、重置状态、隐藏 SVG
         */
        const dragEnd = () => {
            parent.releasePointerCapture(dragId);
            dragId = undefined;
            svg.classList.add('hidden');
        };

        /**
         * 指针释放事件处理：根据是否拖拽选择不同的选区模式
         *
         * 选区模式（通过修饰键控制）：
         * - shiftKey：追加 —— 将新选区添加到已有选区中
         * - ctrlKey：移除 —— 从已有选区中移除
         * - 无修饰键：替换 —— 新选区直接替换旧选区
         *
         * 点击行为分为两种：
         * - 拖拽移动过 → 矩形框选，触发 events.invoke('select.rect', ...)
         * - 仅点击未移动 → 点选单个高斯点，触发 events.invoke('select.point', ...)
         */
        const pointerup = async (e: PointerEvent) => {
            if (e.pointerId === dragId) {
                e.preventDefault();
                e.stopPropagation();

                const w = parent.clientWidth;
                const h = parent.clientHeight;

                if (dragMoved) {
                    // 矩形选择：将像素坐标归一化为 0~1 范围，便于后续与世界坐标映射
                    await events.invoke(
                        'select.rect',
                        e.shiftKey ? 'add' : (e.ctrlKey ? 'remove' : 'set'), {
                            start: { x: Math.min(start.x, end.x) / w, y: Math.min(start.y, end.y) / h },
                            end: { x: Math.max(start.x, end.x) / w, y: Math.max(start.y, end.y) / h }
                        });
                } else {
                    // 点选模式：根据点击位置选择单个高斯点
                    await events.invoke(
                        'select.point',
                        e.shiftKey ? 'add' : (e.ctrlKey ? 'remove' : 'set'),
                        { x: e.offsetX / parent.clientWidth, y: e.offsetY / parent.clientHeight }
                    );
                }

                dragEnd();
            }
        };

        this.activate = () => {
            parent.style.display = 'block';
            parent.addEventListener('pointerdown', pointerdown);
            parent.addEventListener('pointermove', pointermove);
            parent.addEventListener('pointerup', pointerup);
        };

        this.deactivate = () => {
            // 清理进行中的拖拽操作，防止切换工具后残留状态
            if (dragId !== undefined) {
                dragEnd();
            }
            parent.style.display = 'none';
            parent.removeEventListener('pointerdown', pointerdown);
            parent.removeEventListener('pointermove', pointermove);
            parent.removeEventListener('pointerup', pointerup);
        };
    }

    /**
     * 销毁工具（预留钩子，当前为空实现）
     * 用于需要额外清理 DOM 资源时扩展
     */
    destroy() {

    }
}

export { RectSelection };
