/**
 * selection.ts - 选择事件注册模块
 *
 * 管理场景中"当前选中的 Splat"状态。SuperSplat 中一次只能选中一个 Splat
 * （Splat 内部的单个高斯体选择由编辑操作管理，见 edit-ops.ts）。
 *
 * 主要功能：
 *   - 设置当前选中的 Splat（setSelection）
 *   - 查询当前选中的 Splat（selection 查询函数）
 *   - 切换到下一个 Splat（selection.next，在多个 SPLAT 间切换）
 *   - 当新 Splat 添加到场景时自动选中
 *   - 当 Splat 被移除/不可见时自动取消选中
 *   - 通过拾取器选中 Splat（camera.focalPointPicked）
 *
 * 设计特点：
 *   - 使用闭包变量 selection 存储当前选中，不依赖外部状态管理
 *   - setSelection 只在 Splat 实际变化时触发 'selection.changed' 事件
 *   - 对不可见的 Splat 不会设置为选中（防止选中被隐藏的对象）
 */

import { Element, ElementType } from './element';
import { Events } from './events';
import { PointCloud } from './pointcloud';
import { Scene } from './scene';
import { Splat } from './splat';

/**
 * 注册选择相关事件
 *
 * 将元素级别的选择逻辑绑定到事件总线上。
 *
 * @param events - 全局事件总线
 * @param scene  - 3D 场景对象
 */
const registerSelectionEvents = (events: Events, scene: Scene) => {
    /** 当前选中的元素引用（Splat 或 PointCloud） */
    let selection: Splat | PointCloud = null;

    /**
     * 设置当前选中的元素
     */
    const setSelection = (element: Splat | PointCloud) => {
        if (element !== selection && (!element || element.visible)) {
            const prev = selection;
            selection = element;
            events.fire('selection.changed', selection, prev);
        }
    };

    events.on('selection', (element: Splat | PointCloud) => {
        setSelection(element);
    });

    events.function('selection', () => {
        return selection;
    });

    events.on('selection.next', () => {
        const splats = scene.getElementsByType(ElementType.splat) as Splat[];
        if (splats.length > 1) {
            const idx = splats.indexOf(selection as Splat);
            setSelection(splats[(idx + 1) % splats.length]);
        }
    });

    /**
     * 新元素添加到场景时自动选中（Splat 或 PointCloud）
     */
    events.on('scene.elementAdded', (element: Element) => {
        if (element.type === ElementType.splat) {
            setSelection(element as Splat);
        } else if (element.type === ElementType.pointcloud) {
            setSelection(element as PointCloud);
        }
    });

    events.on('scene.elementRemoved', (element: Element) => {
        if (element === selection) {
            const splats = scene.getElementsByType(ElementType.splat) as Splat[];
            if (splats.length > 0) {
                setSelection(splats.length === 1 ? null : splats.find(v => v !== element));
            } else {
                setSelection(null);
            }
        }
    });

    events.on('splat.visibility', (splat: Splat) => {
        if (splat === selection && !splat.visible) {
            setSelection(null);
        }
    });

    events.on('camera.focalPointPicked', (details: { splat: Splat }) => {
        setSelection(details.splat);
    });
};

export { registerSelectionEvents };
