/**
 * camera-pose-gizmos.ts - 相机姿态可视化 Gizmo
 *
 * 本文件实现相机关键帧位置的可视化辅助图形（Gizmo）。
 * 每个已设置的关键帧处渲染一个小型的线条相机图标：
 * - 四棱锥体（从相机位置延伸到视锥体的四个角）
 * - 四边形底座（视锥体近平面矩形）
 * - 向上的三角形指示器（指示相机的"上方"方向）
 *
 * 核心设计：
 * - CameraPoseGizmos 继承 Element，作为场景元素参与统一生命周期
 * - 使用 PlayCanvas 的 PRIMITIVE_LINES 图元，通过 ShaderMaterial 渲染
 * - "脏标记"模式：仅在关键帧变化或场景边界改变时重建网格
 * - 通过模块级临时向量避免每帧分配（性能优化）
 *
 * Gizmo 颜色为青色 (0, 255, 255)，蓝色系以区别于场景中的其他颜色。
 */

import {
    PRIMITIVE_LINES,
    Entity,
    Mesh,
    MeshInstance,
    ShaderMaterial,
    Vec3
} from 'playcanvas';

import { Element, ElementType } from './element';
import { vertexShader, fragmentShader } from './shaders/debug-shader';

/**
 * 临时向量，用于视锥体几何计算。
 * 模块级定义以避免每帧重建 gizmo 时堆分配。
 * 所有 rebuildMesh 中的几何计算都复用这些向量。
 */
const tmpForward = new Vec3();    // 前向方向
const tmpRight = new Vec3();      // 右向方向
const tmpUp = new Vec3();         // 上向方向
const tmpBase = new Vec3();       // 底座中心点
const tmpTL = new Vec3();         // 底座左上角
const tmpTR = new Vec3();         // 底座右上角
const tmpBL = new Vec3();         // 底座左下角
const tmpBR = new Vec3();         // 底座右下角
const tmpUpTip = new Vec3();      // 向上指示器顶端

/**
 * 每相机图标的线段数：
 * 4 条棱锥边 + 4 条底边 + 2 条向上三角 = 10 条线
 */
const LINES_PER_CAMERA = 10;
// 每条线段 2 个顶点
const VERTS_PER_CAMERA = LINES_PER_CAMERA * 2;

/**
 * CameraPoseGizmos 类 - 相机姿态可视化器。
 *
 * 作为一个场景元素存在，在渲染前检查是否需要重建网格。
 * 通过监听关键帧事件和场景边界事件来标记需要重建。
 */
class CameraPoseGizmos extends Element {
    /** 包含 Gizmo 网格的实体 */
    entity: Entity;
    /** 线条网格 */
    mesh: Mesh;
    /** 着色器材质（使用全局 debug shader） */
    material: ShaderMaterial;
    /** 网格实例 */
    meshInstance: MeshInstance;
    /** 脏标记：为 true 时需要重建网格 */
    dirty = true;

    constructor() {
        super(ElementType.debug);
    }

    /**
     * 添加到场景时初始化 Gizmo 网格和资源。
     *
     * 创建：
     * - 着色器材质：使用 debug-shader 的顶点和片段着色器
     * - 网格：初始为空（顶点数为 0）
     * - 网格实例：挂载到实体上，使用世界层渲染
     * - 事件监听：关键帧变化、场景边界变化时标记需要重建
     */
    add() {
        const scene = this.scene;
        const device = scene.graphicsDevice;

        // 创建着色器材质
        this.material = new ShaderMaterial({
            uniqueName: 'cameraPoseGizmoMaterial',
            vertexGLSL: vertexShader,
            fragmentGLSL: fragmentShader
        });
        this.material.depthWrite = true;
        this.material.depthTest = true;
        this.material.update();

        // 创建网格（初始为空，在 rebuildMesh 中填充顶点）
        this.mesh = new Mesh(device);
        this.mesh.primitive[0] = {
            baseVertex: 0,
            type: PRIMITIVE_LINES,    // 线段图元
            base: 0,
            count: 0                  // 初始无线段
        };

        // 创建网格实例，禁用背面剔除（线条没有面概念）
        this.meshInstance = new MeshInstance(this.mesh, this.material, null);
        this.meshInstance.cull = false;

        // 创建实体并添加渲染组件
        this.entity = new Entity('cameraPoseGizmos');
        this.entity.addComponent('render', {
            meshInstances: [this.meshInstance],
            layers: [scene.worldLayer.id]    // 在世界层渲染
        });

        scene.app.root.addChild(this.entity);

        // 姿态变化时标记需要重建
        const markDirty = () => {
            this.dirty = true;
            if (scene.events.invoke('camera.showPoses')) {
                // 如果当前可见，立即触发渲染
                scene.forceRender = true;
            }
        };
        const { events } = scene;
        events.on('track.keyAdded', markDirty);
        events.on('track.keyRemoved', markDirty);
        events.on('track.keyMoved', markDirty);
        events.on('track.keyUpdated', markDirty);
        events.on('track.keysCleared', markDirty);
        events.on('track.keysLoaded', markDirty);
        // 场景边界变化也可能影响 gizmo 尺寸
        events.on('scene.boundChanged', markDirty);
    }

    /** 销毁实体和相关资源 */
    destroy() {
        this.entity?.destroy();
    }

    /**
     * 渲染前回调。
     *
     * 检查 Gizmo 可见性（用户设置 + 覆盖层开关）。
     * 如果可见且脏标记为 true，重建网格。
     */
    onPreRender() {
        const { scene } = this;
        // 只有用户启用且覆盖层打开时才可见
        const visible = scene.events.invoke('camera.showPoses') && scene.camera.renderOverlays;

        this.entity.enabled = visible;

        if (visible && this.dirty) {
            this.dirty = false;
            this.rebuildMesh();
        }
    }

    /**
     * 重建 Gizmo 网格。
     *
     * 遍历所有相机姿态，为每个姿态构建图标几何：
     *
     * 每个相机图标的构建步骤：
     * 1. 从位置和注视目标计算前向方向
     * 2. 计算右向和上向（处理向上/向下看时的退化情况）
     * 3. 在前方固定距离处计算底座中心
     * 4. 计算底座的四个角点（来自近平面）
     * 5. 构建 4 条棱锥边（相机位置→底座角）
     * 6. 构建 4 条底座边（底座矩形轮廓）
     * 7. 构建 2 条向上三角边（指示相机上方方向）
     */
    private rebuildMesh() {
        const poses = this.scene.events.invoke('camera.poses') as { position: Vec3, target: Vec3 }[];
        if (!poses || poses.length === 0) {
            // 无姿态：清空网格
            this.mesh.primitive[0].count = 0;
            return;
        }

        // Gizmo 的几何参数（在标准化空间中）
        const depth = 0.08;      // 底座离相机位置的距离
        const halfW = 0.06;      // 底座半宽
        const halfH = 0.04;      // 底座半高

        const numVerts = poses.length * VERTS_PER_CAMERA;
        const positions: number[] = [];
        // 顶点颜色：RGBA 每顶点 4 字节
        const colors = new Uint8Array(numVerts * 4);

        /** 辅助函数：添加一条线段（两个顶点） */
        const pushLine = (a: Vec3, b: Vec3) => {
            positions.push(a.x, a.y, a.z, b.x, b.y, b.z);
        };

        for (const pose of poses) {
            const { position, target } = pose;

            // 计算前向方向（从相机指向目标）
            tmpForward.sub2(target, position).normalize();

            // 计算右向方向
            // 处理退化情况：当相机几乎垂直向上/向下看时，
            // 前向方向与 UP 向量平行，叉积会退化。
            // 此时使用 BACK 向量代替 UP 来计算右向。
            if (Math.abs(tmpForward.y) > 0.999) {
                tmpRight.cross(tmpForward, Vec3.BACK).normalize();
            } else {
                tmpRight.cross(tmpForward, Vec3.UP).normalize();
            }

            // 计算上向（叉积保证正交）
            tmpUp.cross(tmpRight, tmpForward);

            // 底座中心点：在相机前方 depth 距离处
            tmpBase.copy(position).addScaled(tmpForward, depth);

            // 计算底座四个角点
            // TL = Top-Left, TR = Top-Right, BL = Bottom-Left, BR = Bottom-Right
            tmpTL.copy(tmpBase).addScaled(tmpUp, halfH).addScaled(tmpRight, -halfW);
            tmpTR.copy(tmpBase).addScaled(tmpUp, halfH).addScaled(tmpRight, halfW);
            tmpBL.copy(tmpBase).addScaled(tmpUp, -halfH).addScaled(tmpRight, -halfW);
            tmpBR.copy(tmpBase).addScaled(tmpUp, -halfH).addScaled(tmpRight, halfW);

            // 4 条棱锥边：从相机位置到四个角
            pushLine(position, tmpTL);
            pushLine(position, tmpTR);
            pushLine(position, tmpBL);
            pushLine(position, tmpBR);

            // 4 条底座矩形边
            pushLine(tmpTL, tmpTR);
            pushLine(tmpTR, tmpBR);
            pushLine(tmpBR, tmpBL);
            pushLine(tmpBL, tmpTL);

            // 2 条向上指示器边（形成小三角指示"上方"方向）
            tmpUpTip.copy(tmpBase).addScaled(tmpUp, halfH * 1.5);
            pushLine(tmpTL, tmpUpTip);
            pushLine(tmpTR, tmpUpTip);
        }

        // 填充所有顶点的颜色为青色 (0, 255, 255, 255)
        // 青色是经典的 3D 软件相机颜色
        for (let i = 0; i < numVerts; i++) {
            const off = i * 4;
            colors[off] = 0;          // R
            colors[off + 1] = 255;    // G
            colors[off + 2] = 255;    // B
            colors[off + 3] = 255;    // A
        }

        this.mesh.setPositions(positions);
        this.mesh.setColors32(colors);
        this.mesh.update(PRIMITIVE_LINES);
    }
}

export { CameraPoseGizmos };
